INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C1','sci',5,1,'u2',1,'모스 부호 — 점과 선을 이용해 신호를 보내는 방법 · 점(·)은 신호를 짧게, 선(—)은 신호를 길게 보냄 · 숫자 하나는 점과 선 다섯 개로 나타냄 · 손전등이나 스마트 기기의 빛으로 보냄',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C2','sci',5,1,'u2',1,'숫자 모스 부호 — 1 = ·————, 2 = ··———, 3 = ···——, 4 = ····—, 5 = ·····(점 다섯), 6 = —····, 7 = ——···, 8 = ———··, 9 = ————·, 0 = —————(선 다섯) · 1부터 5까지는 앞에서부터 점이 하나씩 늘고, 6부터는 앞에서부터 선이 하나씩 늘어남',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C3','sci',5,1,'u2',1,'빛 신호 활동 — 모둠원이 보낼 숫자를 하나씩 고르고 순서를 정함 → 교실을 어둡게 하고 한 사람씩 차례대로 천장이나 벽을 향해 신호를 보냄 → 점은 짧게, 선은 길게 → 다른 모둠이 보고 숫자를 알아맞힘 · 손전등이나 스마트 기기의 빛을 눈에 비추지 않도록 특히 주의',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C4','sci',5,1,'u2',1,'빛 신호의 좋은 점 — 소리를 내지 않고도 멀리 있는 사람에게 내용을 전할 수 있음 · 빛이 없으면 우리는 아무것도 볼 수 없음(동굴 속을 밝혀 주는 빛)',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C5','sci',5,1,'u2',2,'물체를 보려면 — 어둠상자 속 물체는 손전등을 켜지 않으면 잘 보이지 않고 손전등을 켜면 잘 보임 · 우리가 물체를 보기 위해서는 물체를 비추는 빛이 있어야 함 · 빛이 없으면 눈을 뜨고 있어도 아무것도 보이지 않음 · 눈에서 빛이 나와서 보는 것이 아님',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C6','sci',5,1,'u2',2,'어둠상자 실험 — 어둠상자에 물체를 넣고 뚜껑을 닫은 뒤 손전등으로 뚜껑의 구멍을 막음(빈틈이 없도록) → 관찰 구멍으로 물체를 관찰 → 손전등을 켠 다음 다시 관찰 → 물체를 보려면 무엇이 필요한지 이야기 · 물체를 넣을 때 다른 친구가 보지 않도록, 친구와 역할을 바꾸어 반복, 손전등 빛을 눈에 비추지 않기',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C7','sci',5,1,'u2',2,'낮과 밤 — 낮에는 햇빛이 있어서 물체를 볼 수 있음 · 밤에는 많은 전등이 빛을 내기 때문에 주변의 물체를 볼 수 있음 · 가로등이 켜지면 길이 잘 보이고 고장 나면 앞이 잘 보이지 않음 · 깜깜한 밤바다에서 배는 등대의 빛을 보고 길을 찾음 · 전등을 꺼도 창문·문틈으로 들어온 빛이 있으면 보임',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C8','sci',5,1,'u2',2,'빛이 없는 세상 — 눈을 뜨고 있어도 아무것도 보이지 않아 아침에 방문을 찾기 어렵고 길가의 돌에 걸려 넘어질 수 있음 · 목소리를 듣거나 냄새를 맡는 일은 빛과 관계없음 · 불편함을 글쓰기·그림·역할놀이 등 다양한 방법으로 표현',ARRAY['물체를 보려면 빛이 있어야 함을 알고, 빛으로 신호를 주고받을 수 있음(문구 초안 — 성취기준 코드 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C9','sci',5,1,'u2',3,'빛의 직진 — 햇빛이나 레이저 지시기의 빛은 곧게 나아감 · 빛이 곧게 나아가는 성질을 빛의 직진이라고 함 · 방향을 바꾸어도 빛은 언제나 곧게 나아감 · 구름 사이로 쏟아지는 햇빛, 밤길을 비추는 자동차 전조등에서 볼 수 있음',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C10','sci',5,1,'u2',3,'직진 실험 — 햇빛이 비치는 곳에서 구멍 뚫린 검은색 도화지를 들고 그 아래에 검은색 도화지를 나란하게 듦 → 아래 도화지를 위아래로 천천히 움직이며 구멍을 통과한 햇빛을 관찰 → 아래 도화지를 수직으로 세우면 햇빛이 곧게 뻗은 모습이 보임 → 교실을 어둡게 하고 레이저 지시기를 켬 → 앞쪽에 분무기로 물을 뿌리면 빛이 나아가는 길이 잘 보임(물은 빛을 곧게 만드는 것이 아니라 길을 보이게 함) · 태양을 직접 바라보지 않고 햇빛 보안경, 레이저 빛을 눈에 비추지 않고 레이저 보안경',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C11','sci',5,1,'u2',3,'그림자 — 빛이 곧게 나아가다가 불투명한 물체를 만나면 더 이상 나아가지 못해 물체 뒤에 그림자가 생김 · 그림자가 생기는 것은 빛이 직진하는 것과 관련 있는 현상 · 손전등 두 개를 비추면 두 빛이 각각 곧게 나아가다 물체에 막혀 그림자도 두 개 생김',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C12','sci',5,1,'u2',4,'빛의 반사 — 빛이 직진하다가 거울에 부딪치면 나아가는 방향이 바뀜 · 빛의 이러한 성질을 빛의 반사라고 함 · 거울에 닿은 빛은 사라지거나 거울을 통과하지 않음 · 거울을 치우면 빛은 곧게 나아감',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C13','sci',5,1,'u2',4,'반사 실험 — 흰 종이를 깔고 받침대에 끼운 평면거울을 수직으로 세움 → 교실을 어둡게 하고 레이저 지시기(확산형)를 거울을 향해 켬 → 여러 방향으로 비추며 거울을 만난 빛을 관찰 → 모양판을 접어 세우고 조금 떨어진 곳에 거울을 세움 → 각 모양판에 빛이 닿도록 레이저 지시기나 거울을 움직임 · 거울이나 빛의 방향을 바꾸면 빛이 닿는 곳도 달라짐 · 거울이 깨지지 않도록 조심, 레이저 빛을 눈에 비추지 않기',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C14','sci',5,1,'u2',4,'반사와 생활 — 우리가 물체를 볼 수 있는 까닭은 물체가 반사한 빛이 우리 눈에 들어오기 때문 · 손목시계나 물병에 닿은 햇빛이 천장에 동그란 빛을 만듦 · 잔잔한 물에 풍경이 비침 · 산꼭대기에 거울을 설치해 그늘진 곳에 햇빛이 들도록 함 · 자동차 거울로 뒤쪽을 봄',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C15','sci',5,1,'u2',5,'렌즈 — 투명한 유리나 플라스틱을 이용해 빛이 통과할 때 빛의 방향이 변하도록 한 기구 · 볼록 렌즈: 가운데가 볼록하고 가장자리로 갈수록 얇아짐 · 오목 렌즈: 가운데가 오목하고 가장자리로 갈수록 두꺼워짐 · 돋보기로 글씨를 보면 크게 보임',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C16','sci',5,1,'u2',5,'렌즈를 통과한 빛 — 빛이 직진하다가 렌즈를 통과하면서 나아가는 방향이 꺾임 · 볼록 렌즈를 통과한 나란한 빛은 안쪽으로 꺾여 한곳으로 모임 · 오목 렌즈를 통과한 빛은 바깥쪽으로 꺾여 퍼져 나감 · 두 렌즈에서 꺾이는 모습이 다름 · 렌즈를 빼면 빛은 곧게 나아감',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C17','sci',5,1,'u2',5,'물에 비춘 빛 — 빛이 공기 중에서 직진하다가 물로 비스듬히 들어갈 때 공기와 물의 경계에서 나아가는 방향이 꺾임 · 물에서 공기로 나아갈 때에도 경계에서 꺾임 · 물을 빼면 꺾이는 곳이 없어 곧게 나아감 · 실험: 물이 든 투명한 플라스틱 통에 스포이트로 우유 4~5방울 → 유리 막대로 저음(물속 빛의 길이 보이게) → 레이저 지시기를 여러 각도로 비춤 → 앞쪽에 분무기로 물을 뿌림(공기 중 빛의 길이 보이게) · 렌즈가 깨지지 않게, 볼록 렌즈로 태양을 보지 않기, 실험 물질 맛보지 않기, 끝나면 정리',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C18','sci',5,1,'u2',5,'빛의 굴절 — 빛이 직진하다가 서로 다른 물질의 경계에서 꺾여 나아가는 성질 · 직진(곧게 나아감)·반사(거울에 부딪쳐 방향이 바뀜)·굴절(경계에서 꺾임)은 모두 빛의 성질 · 빛이 나아가는 모습은 눈으로 직접 보기 어려워 증강 현실(AR)·시뮬레이션으로 거울과 렌즈의 크기·각도를 바꾸며 관찰할 수 있음',ARRAY['햇빛·레이저 지시기의 빛을 관찰하여 빛의 직진, 거울에서의 반사, 렌즈와 물에서의 굴절을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C19','sci',5,1,'u2',6,'거울의 쓰임새(빛의 반사 이용) — 치과 거울: 입안의 잘 보이지 않는 부분을 봄 · 전등 갓: 안쪽의 거울이 전등 빛을 반사해 더 밝게 비춤 · 자동차 뒷거울: 뒤에 있는 자동차를 봄 · 신발 가게 거울: 신발을 신은 모습을 봄 · 거울 예술 작품 · 거울은 보이지 않던 곳을 보여 줌',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C20','sci',5,1,'u2',6,'렌즈의 쓰임새(빛의 굴절 이용) — 돋보기안경: 작은 글씨를 크게 봄 · 관찰용 확대경: 작은 곤충이나 식물의 잎을 관찰 · 수술할 때 볼록 렌즈로 만든 확대경으로 수술 부위를 크게 봄 · 사진기에는 볼록 렌즈와 오목 렌즈가 들어 있음 · 멀리 있는 물체가 흐리게 보이면 오목 렌즈로 만든 안경을 씀 · 렌즈로 물체를 크게 보거나 작게 볼 수 있음',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C21','sci',5,1,'u2',6,'조사·발표 — 모둠원과 조사 계획을 세움 → 스마트 기기로 조사(신뢰할 수 있는 누리집에서 최신 자료) → 각 예의 쓰임새를 이야기 → 붙임쪽지에 글과 그림으로(한 장에 하나의 예만) → 도화지에 붙여 발표 자료를 완성하고 역할을 나눠 발표 · 다른 사람의 창작물을 허락 없이 쓰지 않기 · 발표를 들을 때는 쓰임새를 정확하게 조사했는지 살핌',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C22','sci',5,1,'u2',7,'거울 장치 — 거울 미로 체험장: 거울로 벽을 만들어 내 모습과 길이 주위의 거울에 반사되어 보이므로 길을 찾기 어려움 · 거울로 피자 한 판: 도화지에 피자 한 조각을 그리고, 거울 두 개를 셀로판테이프로 붙여 각도를 조절할 수 있게 한 뒤, 피자 조각에 올려 각도를 조절해 한 판으로 보이게 함 · 거울은 빛의 반사를 이용',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C23','sci',5,1,'u2',7,'렌즈 장치와 과정 — 볼록 렌즈로 간이 프로젝터: 구멍 뚫린 어두운 종이 상자에 볼록 렌즈를 끼우고 스마트 기기를 세워 고정한 뒤 뚜껑을 닫음(다른 빛이 들어오지 않게), 볼록 렌즈가 빛을 굴절시켜 화면을 크게 비춤 · 과정: 만들고 싶은 장치 이야기 → 그림과 글로 나타내기(어떤 성질을 어디에 이용할지 먼저 정함) → 재료 정하기·준비 → 만들기 → 소개 → 다른 모둠의 잘한 점 칭찬 · 멋지게 만드는 것보다 성질을 옳게 이용하는 것이 중요 · 깨지지 않게 조심, 끝나면 정리하고 폐기물을 올바르게 처리',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C24','sci',5,1,'u2',8,'라이파이 — 빛을 사용해 와이파이보다 빠르면서 편리하게 통신하는 기술(와이파이는 지금 인터넷·통신에 쓰는 기술) · 우리가 현재 쓰는 LED 등을 이용 · LED 등의 빛이 아주 빠르게 깜박이며 정보를 실어 보냄(너무 빨라 눈에는 그냥 켜진 것처럼 보임) → 기기가 그 빛을 받아 정보를 읽어 냄(빛이 곧게 나아가 기기까지 닿아야 함) · 첫 시간의 빛 신호와 같은 생각에서 출발',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C25','sci',5,1,'u2',8,'라이파이 — 좋은 점: LED 등의 빛이 있는 곳이라면 어디에서든 빠른 인터넷, 빛을 가리면 다른 사람이 통신 내용을 알 수 없어 보안에 유리 · 아쉬운 점: 빛이 통과하지 못하는 장애물이 있으면 통신이 끊길 수 있고 빛이 닿지 않는 곳에서는 사용이 어려움 · 그래서 더 안정적인 통신이 되도록 기술을 발전시키고 있음',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u2-C26','sci',5,1,'u2',8,'발전과 직업 — 최근 라이파이 기술의 세계 표준 방식(여러 나라가 함께 쓰기로 정한 방식)이 정해져 많은 국가에서 연구 중 · 광통신 연구원·무선 통신 연구원은 빛을 이용한 통신망을 연구하며 기존 통신 방식은 물론 빛의 성질에 관한 이해도 필요 · 가까운 미래에 더 빠르고 안정적인 통신',ARRAY['거울과 렌즈의 쓰임새를 조사하고, 빛의 성질을 이용한 장치와 기술을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X01','sci',5,'u2',ARRAY['SC5-1-u2-C1']::text[],'모스 부호의 점과 선을 뒤바꾼다(점은 길게, 선은 짧게)','점은 짧게, 선은 길게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X02','sci',5,'u2',ARRAY['SC5-1-u2-C2']::text[],'숫자 모스 부호의 짜임을 잘못 안다(5는 선 다섯, 0은 점 다섯, 1부터 선이 늘어난다, 숫자마다 칸 수가 다르다 등)','다섯 칸 · 1~5는 점이 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X03','sci',5,'u2',ARRAY['SC5-1-u2-C3','SC5-1-u2-C6']::text[],'빛을 다루는 활동의 방법이나 안전을 잘못 안다(빛을 친구 눈에 비추기, 밝은 교실, 한꺼번에 켜기 등)','눈에 비추지 않고 한 사람씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X04','sci',5,'u2',ARRAY['SC5-1-u2-C4']::text[],'빛 신호는 소리가 있어야 하거나 가까운 곳에서만 전할 수 있다고 여긴다','소리 없이 멀리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X05','sci',5,'u2',ARRAY['SC5-1-u2-C5']::text[],'물체를 보려면 빛이 아니라 소리·바람·온도가 필요하다고 여긴다','물체를 비추는 빛') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X06','sci',5,'u2',ARRAY['SC5-1-u2-C5','SC5-1-u2-C14']::text[],'눈에서 빛이 나와 물체에 닿아야 물체를 볼 수 있다고 여긴다','물체에서 눈으로 들어와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X07','sci',5,'u2',ARRAY['SC5-1-u2-C5','SC5-1-u2-C7']::text[],'빛이 없어도 가까운 물체는 보이거나, 어두우면 물체가 스스로 밝아진다고 여긴다','빛이 없으면 보이지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X08','sci',5,'u2',ARRAY['SC5-1-u2-C6']::text[],'어둠상자 실험 방법을 잘못 안다(뚜껑 열기, 구멍에 틈 남기기, 물체를 미리 보여 주기 등)','빈틈없이 · 모르게 · 바꾸어 반복') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X09','sci',5,'u2',ARRAY['SC5-1-u2-C7']::text[],'낮에 물체가 잘 보이는 까닭을 따뜻함·눈의 크기·물체의 크기 때문이라고 여긴다','낮에는 햇빛') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X10','sci',5,'u2',ARRAY['SC5-1-u2-C8']::text[],'빛이 사라지면 소리·냄새·맛처럼 빛과 관계없는 것도 사라진다고 여긴다','보는 일만 빛과 관계있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X11','sci',5,'u2',ARRAY['SC5-1-u2-C9']::text[],'빛이 구불구불하게, 빙글빙글 돌며, 휘어서 나아간다고 여긴다','빛은 곧게 나아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X12','sci',5,'u2',ARRAY['SC5-1-u2-C10']::text[],'물을 뿌려야만 빛이 곧게 나아가거나, 물이 빛을 세게·차갑게 한다고 여긴다','물은 길을 보이게 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X13','sci',5,'u2',ARRAY['SC5-1-u2-C11']::text[],'빛이 물체나 장애물을 만나면 돌아서 지나간다고 여긴다','막히면 더 나아가지 못해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X14','sci',5,'u2',ARRAY['SC5-1-u2-C10']::text[],'직진 실험의 안전을 잘못 안다(태양을 직접 바라보기, 보안경 없이 관찰 등)','태양을 직접 보지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X15','sci',5,'u2',ARRAY['SC5-1-u2-C11']::text[],'그림자를 물체가 스스로 만들거나 그림자가 스스로 나뉜다고 여긴다','빛이 막힌 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X16','sci',5,'u2',ARRAY['SC5-1-u2-C12']::text[],'거울에 부딪친 빛이 사라지거나 거울을 그대로 통과한다고 여긴다','방향이 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X17','sci',5,'u2',ARRAY['SC5-1-u2-C12','SC5-1-u2-C13']::text[],'거울이 없어도 빛의 방향이 바뀌거나, 거울의 방향을 바꾸어도 빛이 닿는 곳은 같다고 여긴다','거울이 있어야, 방향 따라 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X18','sci',5,'u2',ARRAY['SC5-1-u2-C13']::text[],'반사 실험의 방법이나 안전을 잘못 안다(교실을 밝게, 빛을 세게, 거울 두드리기, 모양판 치우기 등)','어둡게 · 거울을 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X19','sci',5,'u2',ARRAY['SC5-1-u2-C11','SC5-1-u2-C14','SC5-1-u2-C18']::text[],'빛의 직진·반사·굴절과 관계있는 현상을 서로 바꾸어 짝짓거나, 빛과 관계없는 현상(소리·얼음 등)을 빛의 성질로 여긴다','곧게 · 되비침 · 꺾임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X20','sci',5,'u2',ARRAY['SC5-1-u2-C15']::text[],'볼록 렌즈와 오목 렌즈의 모양을 뒤바꾸거나 렌즈의 뜻을 잘못 안다','가운데가 볼록 · 가운데가 오목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X21','sci',5,'u2',ARRAY['SC5-1-u2-C16']::text[],'볼록 렌즈와 오목 렌즈를 지난 빛이 똑같이 나아간다고 여기거나 모임과 퍼짐을 뒤바꾼다','볼록은 모이고 오목은 퍼져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X22','sci',5,'u2',ARRAY['SC5-1-u2-C17']::text[],'빛이 공기에서 물로, 물에서 공기로 나아갈 때 경계에서 꺾이지 않는다고 여기거나 물속에서 사라진다고 여긴다','경계에서 꺾여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X23','sci',5,'u2',ARRAY['SC5-1-u2-C18']::text[],'굴절과 반사를 바꾸어 안다(거울은 굴절, 렌즈는 반사 등)','거울은 되비추고 렌즈는 꺾어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X24','sci',5,'u2',ARRAY['SC5-1-u2-C17']::text[],'굴절 실험의 방법이나 안전을 잘못 안다(볼록 렌즈로 태양 보기, 물질 맛보기, 우유의 역할 등)','우유는 길을 보이게 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X25','sci',5,'u2',ARRAY['SC5-1-u2-C16','SC5-1-u2-C17']::text[],'렌즈나 물을 지나도 빛이 꺾이지 않는다고 여기거나, 물·렌즈를 빼도 꺾인다고 여긴다','경계가 있어야 꺾여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X26','sci',5,'u2',ARRAY['SC5-1-u2-C19','SC5-1-u2-C20']::text[],'거울과 렌즈의 쓰임을 서로 바꾸어 안다(거울로 물체를 크게 보기, 돋보기는 반사 등)','거울은 반사, 렌즈는 굴절') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X27','sci',5,'u2',ARRAY['SC5-1-u2-C20']::text[],'렌즈는 모두 물체를 크게만 보여 준다고 여긴다','크게도, 작게도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X28','sci',5,'u2',ARRAY['SC5-1-u2-C14','SC5-1-u2-C19']::text[],'거울·전등 갓·시계처럼 빛을 되비추는 물체가 스스로 빛을 내거나 온도를 바꾼다고 여긴다','받은 빛을 되비춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X29','sci',5,'u2',ARRAY['SC5-1-u2-C21']::text[],'조사하고 발표하는 방법이나 태도를 잘못 안다(허락 없이 가져다 쓰기, 혼자 다 하기, 한 쪽지에 여러 예 등)','출처 · 한 장에 하나 · 역할') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X30','sci',5,'u2',ARRAY['SC5-1-u2-C22']::text[],'거울 미로가 빛을 꺾거나 흡수해서 길이 헷갈린다고 여긴다','반사되어 여러 곳에 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X31','sci',5,'u2',ARRAY['SC5-1-u2-C23']::text[],'간이 프로젝터가 빛의 반사를 이용하거나, 뚜껑을 열어 두어도 된다고 여긴다','볼록 렌즈 · 어둡게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X32','sci',5,'u2',ARRAY['SC5-1-u2-C23']::text[],'장치는 크고 멋지게 만드는 것이 가장 중요하다고 여기거나 이용할 성질을 정하지 않고 만든다','어떤 성질을 이용했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X33','sci',5,'u2',ARRAY['SC5-1-u2-C23']::text[],'장치를 만들 때의 안전과 정리를 잘못 안다(깨진 조각 맨손으로 잡기, 남은 재료 아무 데나 버리기 등)','조심하고 정리해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X34','sci',5,'u2',ARRAY['SC5-1-u2-C22']::text[],'거울 장치를 만드는 까닭을 모른다(피자 조각을 크게 그리기, 각도를 조절하지 않기 등)','두 거울의 각도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X35','sci',5,'u2',ARRAY['SC5-1-u2-C24']::text[],'라이파이가 소리·바람·자석으로 통신하거나, 빛의 깜박임을 사람이 눈으로 읽는다고 여긴다','LED 등의 빛') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X36','sci',5,'u2',ARRAY['SC5-1-u2-C24','SC5-1-u2-C25']::text[],'라이파이는 빛이 없거나 장애물이 있어도 잘 쓸 수 있다고 여긴다','빛이 닿아야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X37','sci',5,'u2',ARRAY['SC5-1-u2-C25']::text[],'라이파이가 보안에 유리한 까닭을 잘못 안다(비밀번호가 바뀌어서, 빛이 벽을 뚫어서 등)','빛을 가리면 알 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X38','sci',5,'u2',ARRAY['SC5-1-u2-C26']::text[],'라이파이는 이미 완성되어 연구할 것이 없거나, 관련 직업에 빛의 성질 이해가 필요 없다고 여긴다','계속 연구하고 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X39','sci',5,'u2',ARRAY['SC5-1-u2-C25']::text[],'라이파이의 좋은 점과 아쉬운 점을 뒤바꾼다','어디서든·보안 / 장애물·빛 없는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u2-X40','sci',5,'u2',ARRAY['SC5-1-u2-C18','SC5-1-u2-C19','SC5-1-u2-C20']::text[],'거울과 렌즈가 사라지면 빛이 곧게 나아가지 못하거나 낮에도 아무것도 보이지 않는다고 여긴다','빛 자체는 그대로예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#1','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C1',1,'mc','auto','모스 부호에서 점(·)은 신호를 어떻게 보내나요?',ARRAY['SC5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C1","difficulty":1,"kind":"mc","stem":"모스 부호에서 점(·)은 신호를 어떻게 보내나요?","options":[{"t":"신호를 짧게 보낸다","correct":true},{"t":"신호를 길게 보낸다","mis":"SC5-1-u2-X01"},{"t":"신호를 보내지 않는다","mis":"SC5-1-u2-X01"},{"t":"신호를 두 번 보낸다","mis":"SC5-1-u2-X01"}],"explanation":["점의 모양을 떠올려요.","짧은 표시예요.","짧게 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#2','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C3',1,'ox','auto','빛으로 신호를 보낼 때 손전등의 빛을 친구의 눈에 비추지 않아요.',ARRAY['SC5-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C3","difficulty":1,"kind":"ox","stem":"빛으로 신호를 보낼 때 손전등의 빛을 친구의 눈에 비추지 않아요.","answer":"O","reason_options":[{"t":"눈에 빛을 비추면 눈을 다칠 수 있기 때문에","correct":true},{"t":"눈에 비추면 신호가 너무 잘 보이기 때문에","mis":"SC5-1-u2-X03"}],"mis":"SC5-1-u2-X03","explanation":["안전을 떠올려요.","눈은 소중해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#3','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C1',1,'sa','auto','「점과 선을 이용해 신호를 보내는 방법을 □□ 부호라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u2-C1","difficulty":1,"kind":"sa","stem":"「점과 선을 이용해 신호를 보내는 방법을 □□ 부호라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["모스"],"explanation":["점과 선의 신호예요.","두 글자예요.","모스 부호예요."],"mis":"SC5-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#4','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C3',1,'mc','auto','빛으로 신호를 보낼 때 교실은 어떻게 하는 것이 알맞은가요?',ARRAY['SC5-1-u2-X03']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C3","difficulty":1,"kind":"mc","stem":"빛으로 신호를 보낼 때 교실은 어떻게 하는 것이 알맞은가요?","options":[{"t":"교실을 어둡게 한다","correct":true},{"t":"교실을 가장 밝게 한다","mis":"SC5-1-u2-X03"},{"t":"창문을 열어 햇빛이 많이 들게 한다","mis":"SC5-1-u2-X03"},{"t":"불을 켰다 껐다 계속 바꾼다","mis":"SC5-1-u2-X03"}],"explanation":["빛 신호가 잘 보여야 해요.","주변이 어두워야 해요.","어둡게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#5','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C2',2,'mc','auto','숫자 5를 나타내는 모스 부호는 어느 것인가요?',ARRAY['SC5-1-u2-X02']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C2","difficulty":2,"kind":"mc","stem":"숫자 5를 나타내는 모스 부호는 어느 것인가요?","options":[{"t":"· · · · ·","correct":true},{"t":"— — — — —","mis":"SC5-1-u2-X02"},{"t":"· · · · —","mis":"SC5-1-u2-X02"},{"t":"— · · · ·","mis":"SC5-1-u2-X02"}],"explanation":["1부터 점이 하나씩 늘어요.","5는 점이 몇 개일까요?","점 다섯 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#6','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C2',2,'match','auto','숫자와 모스 부호를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC5-1-u2-C2","difficulty":2,"kind":"match","stem":"숫자와 모스 부호를 알맞게 이으세요.","pairs":[{"l":"1","r":"· — — — —"},{"l":"6","r":"— · · · ·"},{"l":"9","r":"— — — — ·"},{"l":"0","r":"— — — — —"}],"mis":"SC5-1-u2-X02","explanation":["점과 선의 개수를 세어요.","1은 점 하나, 6은 선 하나로 시작해요.","0은 선만 다섯 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#7','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C4',2,'mc','auto','빛으로 신호를 보내면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X04']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C4","difficulty":2,"kind":"mc","stem":"빛으로 신호를 보내면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"소리를 내지 않고도 멀리 있는 사람에게 전할 수 있다","correct":true},{"t":"신호를 보내면 물체를 끌어당길 수 있다","mis":"SC5-1-u2-X04"},{"t":"소리를 크게 내야만 신호가 전해진다","mis":"SC5-1-u2-X04"},{"t":"바로 옆에 있는 사람에게만 전할 수 있다","mis":"SC5-1-u2-X04"}],"explanation":["빛 신호를 떠올려요.","소리가 필요 없어요.","멀리까지 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_basic#8','sci',5,1,'u2','L01','g5_1_sci_u2_L01_basic','lesson_basic','SC5-1-u2-C3',2,'error','auto','빛 신호 활동을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X03']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C3","difficulty":2,"kind":"error","stem":"빛 신호 활동을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「모두 한꺼번에 손전등을 켜서 빨리 보내자.」","correct":true,"mis_target":"SC5-1-u2-X03"},{"t":"수아 — 「천장이나 벽을 향해 신호를 보내자.」","mis":"SC5-1-u2-X03"},{"t":"민재 — 「한 사람씩 차례대로 보내자.」","mis":"SC5-1-u2-X03"}],"explanation":["신호가 섞이면 어떨까요?","한 사람씩 보내요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
