INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#1','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C2',2,'sa','auto','「— — — · ·」 신호가 나타내는 숫자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C2","difficulty":2,"kind":"sa","stem":"「— — — · ·」 신호가 나타내는 숫자를 쓰세요.","answer":["8"],"explanation":["선이 몇 개인가요?","선 셋으로 시작해요.","8이에요."],"mis":"SC5-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#2','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C3',2,'mc','auto','빛 신호 보내기 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C3","difficulty":2,"kind":"mc","stem":"빛 신호 보내기 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉢ → ㉠","correct":true},{"t":"㉠ → ㉡ → ㉣ → ㉢","mis":"SC5-1-u2-X03"},{"t":"㉣ → ㉡ → ㉠ → ㉢","mis":"SC5-1-u2-X03"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SC5-1-u2-X03"}],"explanation":["먼저 숫자를 골라요.","보낸 다음 알아맞혀요.","㉡ → ㉣ → ㉢ → ㉠이에요."],"asset":{"type":"passage","lines":["㉠ 다른 모둠이 신호를 보고 어떤 숫자인지 알아맞힌다.","㉡ 모둠원이 보낼 숫자를 하나씩 고르고 순서를 정한다.","㉢ 점은 신호를 짧게, 선은 신호를 길게 보낸다.","㉣ 교실을 어둡게 하고 한 사람씩 천장이나 벽을 향해 신호를 보낸다."],"title":"빛 신호 보내기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
