INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#4','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C2',3,'error','auto','숫자 모스 부호에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X02']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C2","difficulty":3,"kind":"error","stem":"숫자 모스 부호에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「1부터 5까지는 선이 하나씩 늘어나.」","correct":true,"mis_target":"SC5-1-u2-X02"},{"t":"지호 — 「5는 점만 다섯 개야.」","mis":"SC5-1-u2-X02"},{"t":"예서 — 「0은 선만 다섯 개야.」","mis":"SC5-1-u2-X02"}],"explanation":["1과 2를 견줘요.","점이 늘어요.","하린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#5','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C4',3,'ox','auto','빛 신호는 소리가 나지 않아서 조용히 해야 하는 곳에서도 멀리 있는 친구에게 전할 수 있어요.',ARRAY['SC5-1-u2-X04']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C4","difficulty":3,"kind":"ox","stem":"빛 신호는 소리가 나지 않아서 조용히 해야 하는 곳에서도 멀리 있는 친구에게 전할 수 있어요.","answer":"O","reason_options":[{"t":"빛은 소리 없이도 멀리 있는 사람의 눈에 보이기 때문에","correct":true},{"t":"빛 신호는 가까이 있는 사람만 볼 수 있기 때문에","mis":"SC5-1-u2-X04"}],"mis":"SC5-1-u2-X04","explanation":["빛 신호의 좋은 점이에요.","소리가 없어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#6','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C3',3,'mc','auto','신호를 천장이나 벽을 향해 보내는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X03','SC5-1-u2-X04']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C3","difficulty":3,"kind":"mc","stem":"신호를 천장이나 벽을 향해 보내는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빛이 사람의 눈에 바로 비치지 않으면서 모두가 볼 수 있기 때문에","correct":true},{"t":"천장에 비추면 빛이 길게 늘어나기 때문에","mis":"SC5-1-u2-X03"},{"t":"벽에 비추면 신호가 소리로 바뀌기 때문에","mis":"SC5-1-u2-X04"},{"t":"천장을 밝게 비춰야 교실이 환해지기 때문에","mis":"SC5-1-u2-X03"}],"explanation":["눈을 지켜요.","모두 볼 수 있어야 해요.","천장이나 벽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#7','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C3',3,'match','auto','지킬 일과 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-1-u2-C3","difficulty":3,"kind":"match","stem":"지킬 일과 그 까닭을 알맞게 이으세요.","pairs":[{"l":"교실을 어둡게 한다","r":"빛 신호가 잘 보이게 한다"},{"l":"한 사람씩 차례대로 보낸다","r":"신호가 서로 섞이지 않게 한다"},{"l":"빛을 눈에 비추지 않는다","r":"눈을 보호한다"}],"mis":"SC5-1-u2-X03","explanation":["까닭을 하나씩 떠올려요.","보이기·섞이지 않기·보호예요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#8','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C2',4,'mc','auto','잠긴 상자의 비밀번호 세 자리를 「· · — — —」, 「— — — — ·」, 「· · · · ·」 차례로 받았어요. 비밀번호는 어느 것인가요?',ARRAY['SC5-1-u2-X01','SC5-1-u2-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C2","difficulty":4,"kind":"mc","stem":"잠긴 상자의 비밀번호 세 자리를 「· · — — —」, 「— — — — ·」, 「· · · · ·」 차례로 받았어요. 비밀번호는 어느 것인가요?","options":[{"t":"295","correct":true},{"t":"740","mis":"SC5-1-u2-X01"},{"t":"285","mis":"SC5-1-u2-X02"},{"t":"296","mis":"SC5-1-u2-X02"}],"explanation":["하나씩 숫자로 바꿔요.","점 둘 · 선 넷 · 점 다섯이에요.","295예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#9','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C4',4,'mc','auto','소리를 내면 안 되는 도서관에서 멀리 떨어진 친구에게 숫자를 전하려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X04','SC5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C4","difficulty":4,"kind":"mc","stem":"소리를 내면 안 되는 도서관에서 멀리 떨어진 친구에게 숫자를 전하려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"손전등을 벽에 비추며 모스 부호로 숫자 신호를 보낸다","correct":true},{"t":"친구 이름을 크게 불러 숫자를 외친다","mis":"SC5-1-u2-X04"},{"t":"손전등을 친구 눈에 바로 비춰 신호를 보낸다","mis":"SC5-1-u2-X03"},{"t":"빛 신호는 가까이에서만 보이니 친구 옆으로 가서 귓속말한다","mis":"SC5-1-u2-X04"}],"explanation":["소리를 내면 안 돼요.","빛 신호를 써요.","눈에는 비추지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L01_challenge#10','sci',5,1,'u2','L01','g5_1_sci_u2_L01_challenge','lesson_challenge','SC5-1-u2-C4',4,'essay','teacher','빛으로 숫자 신호를 보내는 활동을 떠올려, 빛으로 신호를 보내면 좋은 점과 신호를 보낼 때 지켜야 할 점을 두 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C4","difficulty":4,"kind":"essay","stem":"빛으로 숫자 신호를 보내는 활동을 떠올려, 빛으로 신호를 보내면 좋은 점과 신호를 보낼 때 지켜야 할 점을 두 가지씩 쓰세요.","answer_guide":{"answer":"예: 빛으로 신호를 보내면 소리를 내지 않아도 되고, 멀리 있는 사람에게도 내용을 전할 수 있다. 신호를 보낼 때에는 손전등이나 스마트 기기의 빛을 사람의 눈에 비추지 않고 천장이나 벽을 향해 보낸다. 또 한 사람씩 차례대로 보내서 신호가 섞이지 않게 한다.","scoring_points":["좋은 점 두 가지를 썼는가","눈에 비추지 않기를 썼는가","다른 지킬 점 하나를 더 썼는가"]},"explanation":["좋은 점부터 떠올려요.","안전을 떠올려요.","두 가지씩 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#1','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C5',1,'mc','auto','물체를 보기 위해 꼭 있어야 하는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X05']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C5","difficulty":1,"kind":"mc","stem":"물체를 보기 위해 꼭 있어야 하는 것은 어느 것인가요?","options":[{"t":"물체를 비추는 빛","correct":true},{"t":"물체에서 나는 소리","mis":"SC5-1-u2-X05"},{"t":"물체 주변의 바람","mis":"SC5-1-u2-X05"},{"t":"물체의 차가운 온도","mis":"SC5-1-u2-X05"}],"explanation":["어둠상자를 떠올려요.","손전등을 켰을 때 보였어요.","빛이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#2','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C5',1,'ox','auto','손전등을 켜지 않은 어둠상자 속 물체는 잘 보이지 않아요.',ARRAY['SC5-1-u2-X05']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C5","difficulty":1,"kind":"ox","stem":"손전등을 켜지 않은 어둠상자 속 물체는 잘 보이지 않아요.","answer":"O","reason_options":[{"t":"물체를 비추는 빛이 없기 때문에","correct":true},{"t":"물체가 소리를 내지 않기 때문에","mis":"SC5-1-u2-X05"}],"mis":"SC5-1-u2-X05","explanation":["손전등을 끈 상자 속이에요.","빛이 없어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#3','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C5',1,'sa','auto','「우리가 물체를 보려면 물체를 비추는 □이 있어야 합니다.」 □에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u2-C5","difficulty":1,"kind":"sa","stem":"「우리가 물체를 보려면 물체를 비추는 □이 있어야 합니다.」 □에 알맞은 말을 쓰세요.","answer":["빛"],"explanation":["손전등을 켰어요.","한 글자예요.","빛이에요."],"mis":"SC5-1-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#4','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C7',1,'mc','auto','낮에 물체가 잘 보이는 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C7","difficulty":1,"kind":"mc","stem":"낮에 물체가 잘 보이는 까닭은 어느 것인가요?","options":[{"t":"햇빛이 있어서 물체를 비추기 때문에","correct":true},{"t":"낮에는 공기가 따뜻하기 때문에","mis":"SC5-1-u2-X09"},{"t":"낮에는 눈이 더 커지기 때문에","mis":"SC5-1-u2-X09"},{"t":"낮에는 물체가 더 커지기 때문에","mis":"SC5-1-u2-X09"}],"explanation":["낮에 있는 것을 떠올려요.","해가 비춰요.","햇빛 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#5','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C7',2,'match','auto','상황과 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C7","difficulty":2,"kind":"match","stem":"상황과 까닭을 알맞게 이으세요.","pairs":[{"l":"손전등을 켠 어둠상자 속","r":"빛이 물체를 비추어 잘 보인다"},{"l":"손전등을 끈 어둠상자 속","r":"빛이 없어 물체가 보이지 않는다"},{"l":"가로등이 켜진 밤길","r":"전등의 빛이 있어 길이 잘 보인다"},{"l":"가로등이 고장 난 밤길","r":"빛이 없어 앞이 잘 보이지 않는다"}],"mis":"SC5-1-u2-X07","explanation":["빛이 있는지 봐요.","있으면 보이고 없으면 안 보여요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#6','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C6',2,'mc','auto','손전등으로 어둠상자 뚜껑의 구멍을 막을 때 주의할 점은 어느 것인가요?',ARRAY['SC5-1-u2-X08','SC5-1-u2-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C6","difficulty":2,"kind":"mc","stem":"손전등으로 어둠상자 뚜껑의 구멍을 막을 때 주의할 점은 어느 것인가요?","options":[{"t":"빈틈이 없도록 잘 막는다","correct":true},{"t":"바깥 빛이 조금 들어오게 틈을 남긴다","mis":"SC5-1-u2-X08"},{"t":"뚜껑을 살짝 열어 둔다","mis":"SC5-1-u2-X08"},{"t":"손전등 빛을 친구 눈에 비추며 막는다","mis":"SC5-1-u2-X03"}],"explanation":["바깥 빛이 들어오면 어떨까요?","빛을 막아야 해요.","빈틈없이 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#7','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C7',2,'mc','auto','방의 전등을 껐는데도 물체가 보였어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X05']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C7","difficulty":2,"kind":"mc","stem":"방의 전등을 껐는데도 물체가 보였어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문이나 문틈으로 들어온 빛이 물체를 비추기 때문에","correct":true},{"t":"어두운 곳에서는 물체가 스스로 밝아지기 때문에","mis":"SC5-1-u2-X07"},{"t":"어두운 곳에서는 빛이 없어도 볼 수 있기 때문에","mis":"SC5-1-u2-X07"},{"t":"물체가 소리를 내어 자리를 알려 주기 때문에","mis":"SC5-1-u2-X05"}],"explanation":["다른 빛이 있을까요?","창문과 문틈이에요.","들어온 빛 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#8','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C8',2,'ox','auto','빛이 모두 사라지면 꽃의 냄새도 맡을 수 없어요.',ARRAY['SC5-1-u2-X10']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C8","difficulty":2,"kind":"ox","stem":"빛이 모두 사라지면 꽃의 냄새도 맡을 수 없어요.","answer":"X","reason_options":[{"t":"냄새를 맡는 일은 빛과 관계가 없기 때문에","correct":true},{"t":"빛이 없으면 모든 감각이 함께 사라지기 때문에","mis":"SC5-1-u2-X10"}],"mis":"SC5-1-u2-X10","explanation":["냄새는 무엇으로 맡나요?","코로 맡아요.","빛과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#9','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C7',2,'mc','auto','깜깜한 밤바다에서 등대가 필요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X05','SC5-1-u2-X09','SC5-1-u2-X07']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C7","difficulty":2,"kind":"mc","stem":"깜깜한 밤바다에서 등대가 필요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"배가 등대의 빛을 보고 길을 찾기 때문에","correct":true},{"t":"등대가 큰 소리로 길을 알려 주기 때문에","mis":"SC5-1-u2-X05"},{"t":"등대가 바닷물을 따뜻하게 하기 때문에","mis":"SC5-1-u2-X09"},{"t":"밤에는 빛이 없어도 배가 잘 보이기 때문에","mis":"SC5-1-u2-X07"}],"explanation":["등대는 무엇을 내나요?","빛을 내요.","빛을 보고 길을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_basic#10','sci',5,1,'u2','L02','g5_1_sci_u2_L02_basic','lesson_basic','SC5-1-u2-C6',3,'mc','auto','실험 기록의 ②와 ③을 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X06','SC5-1-u2-X08','SC5-1-u2-X07']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C6","difficulty":3,"kind":"mc","stem":"실험 기록의 ②와 ③을 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"물체를 보려면 물체를 비추는 빛이 있어야 한다","correct":true},{"t":"눈에서 빛이 나와야 물체를 볼 수 있다","mis":"SC5-1-u2-X06"},{"t":"상자가 클수록 물체가 잘 보인다","mis":"SC5-1-u2-X08"},{"t":"빛이 없어도 가까이 있는 물체는 보인다","mis":"SC5-1-u2-X07"}],"explanation":["달라진 것은 하나예요.","손전등을 켰어요.","빛이 있어야 보여요."],"asset":{"type":"passage","lines":["① 어둠상자에 물체를 넣고 뚜껑을 닫은 뒤 손전등으로 구멍을 막는다.","② 관찰 구멍으로 상자 속 물체를 관찰한다.","③ 손전등을 켠 다음 관찰 구멍으로 다시 관찰한다.","②의 결과 — 무엇인지 잘 보이지 않는다.","③의 결과 — 무엇인지 잘 보인다."],"title":"어둠상자 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#1','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C6',2,'sa','auto','「어둠상자 속 물체를 들여다보는 작은 구멍을 □□ 구멍이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C6","difficulty":2,"kind":"sa","stem":"「어둠상자 속 물체를 들여다보는 작은 구멍을 □□ 구멍이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["관찰"],"explanation":["들여다보는 구멍이에요.","두 글자예요.","관찰 구멍이에요."],"mis":"SC5-1-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#2','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C6',2,'mc','auto','어둠상자 실험을 바르게 하는 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X08','SC5-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C6","difficulty":2,"kind":"mc","stem":"어둠상자 실험을 바르게 하는 방법은 어느 것인가요?","options":[{"t":"물체를 넣을 때 다른 친구가 보지 않도록 한다","correct":true},{"t":"뚜껑을 활짝 열어 놓고 관찰한다","mis":"SC5-1-u2-X08"},{"t":"손전등 빛을 친구의 눈에 비추어 본다","mis":"SC5-1-u2-X03"},{"t":"한 번만 관찰하고 역할은 바꾸지 않는다","mis":"SC5-1-u2-X08"}],"explanation":["무엇이 들었는지 몰라야 해요.","보지 않게 넣어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#3','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C6',3,'error','auto','어둠상자 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X08']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C6","difficulty":3,"kind":"error","stem":"어둠상자 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「상자에 뭘 넣었는지 미리 보여 주면 더 잘 맞힐 거야.」","correct":true,"mis_target":"SC5-1-u2-X08"},{"t":"서아 — 「친구와 역할을 바꾸어 한 번 더 해 보자.」","mis":"SC5-1-u2-X08"},{"t":"이안 — 「구멍을 빈틈없이 막자.」","mis":"SC5-1-u2-X08"}],"explanation":["무엇을 알아보는 실험인가요?","미리 알면 안 돼요.","도윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#4','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C5',3,'mc','auto','「눈에서 빛이 나와야 물체를 볼 수 있다」는 생각이 옳지 않음을 보여 주는 결과는 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X05']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C5","difficulty":3,"kind":"mc","stem":"「눈에서 빛이 나와야 물체를 볼 수 있다」는 생각이 옳지 않음을 보여 주는 결과는 어느 것인가요?","options":[{"t":"손전등을 끄자 눈을 뜨고 있어도 상자 속 물체가 보이지 않았다","correct":true},{"t":"눈을 크게 뜨자 손전등 없이도 물체가 보였다","mis":"SC5-1-u2-X07"},{"t":"상자를 흔들자 물체 소리가 났다","mis":"SC5-1-u2-X05"},{"t":"손전등을 켜자 물체가 스스로 빛을 냈다","mis":"SC5-1-u2-X07"}],"explanation":["눈은 그대로 떴어요.","빛이 없을 때를 봐요.","보이지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#5','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C8',3,'mc','auto','빛이 모두 사라졌을 때 생기는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X10']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C8","difficulty":3,"kind":"mc","stem":"빛이 모두 사라졌을 때 생기는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"길가의 돌을 보지 못해 걸려 넘어질 수 있다","correct":true},{"t":"친구의 목소리가 들리지 않는다","mis":"SC5-1-u2-X10"},{"t":"꽃의 냄새를 맡을 수 없다","mis":"SC5-1-u2-X10"},{"t":"음식의 맛을 느낄 수 없다","mis":"SC5-1-u2-X10"}],"explanation":["빛과 관계있는 일을 찾아요.","보는 일이에요.","돌을 보지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#6','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C7',3,'ox','auto','가로등이 고장 난 밤길에서는 앞이 잘 보이지 않아요.',ARRAY['SC5-1-u2-X09']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C7","difficulty":3,"kind":"ox","stem":"가로등이 고장 난 밤길에서는 앞이 잘 보이지 않아요.","answer":"O","reason_options":[{"t":"밤에는 전등의 빛이 물체를 비춰야 보이기 때문에","correct":true},{"t":"밤에는 눈이 작아지기 때문에","mis":"SC5-1-u2-X09"}],"mis":"SC5-1-u2-X09","explanation":["밤에 빛을 내는 것은?","가로등이 꺼졌어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#7','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C7',3,'mc','auto','같은 공원 의자가 낮에는 또렷하게, 밤에는 흐릿하게 보이는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X09','SC5-1-u2-X07']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C7","difficulty":3,"kind":"mc","stem":"같은 공원 의자가 낮에는 또렷하게, 밤에는 흐릿하게 보이는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"낮에는 햇빛이, 밤에는 가로등 빛만 의자를 비추기 때문에","correct":true},{"t":"밤이 되면 의자가 작아지기 때문에","mis":"SC5-1-u2-X09"},{"t":"밤이 되면 의자가 스스로 어두워지기 때문에","mis":"SC5-1-u2-X07"},{"t":"밤에는 공기가 차가워지기 때문에","mis":"SC5-1-u2-X09"}],"explanation":["의자는 그대로예요.","비추는 빛이 달라요.","햇빛과 가로등이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#8','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C5',4,'mc','auto','동굴 깊은 곳에서 손전등이 꺼졌어요. 가장 알맞은 설명은 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X05']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C5","difficulty":4,"kind":"mc","stem":"동굴 깊은 곳에서 손전등이 꺼졌어요. 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"동굴 속 물체를 비추는 빛이 없어 눈을 떠도 보이지 않는다","correct":true},{"t":"조금 기다리면 눈이 익숙해져 빛 없이도 잘 보인다","mis":"SC5-1-u2-X07"},{"t":"소리를 크게 내면 동굴 벽이 보인다","mis":"SC5-1-u2-X05"},{"t":"어두우면 동굴 벽이 스스로 빛을 낸다","mis":"SC5-1-u2-X07"}],"explanation":["빛이 들어오지 않는 곳이에요.","비추는 빛이 없어요.","보이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#9','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C6',4,'mc','auto','어떤 모둠이 뚜껑을 활짝 연 채 손전등을 켜고 관찰했어요. 이 실험의 문제점은 어느 것인가요?',ARRAY['SC5-1-u2-X08','SC5-1-u2-X06','SC5-1-u2-X09']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C6","difficulty":4,"kind":"mc","stem":"어떤 모둠이 뚜껑을 활짝 연 채 손전등을 켜고 관찰했어요. 이 실험의 문제점은 어느 것인가요?","options":[{"t":"바깥 빛도 들어와 손전등 빛 때문에 보이는지 알 수 없다","correct":true},{"t":"문제가 없다 — 어떻게 해도 결과는 같다","mis":"SC5-1-u2-X08"},{"t":"뚜껑을 열면 눈에서 나오는 빛이 막힌다","mis":"SC5-1-u2-X06"},{"t":"뚜껑을 열면 물체가 작아진다","mis":"SC5-1-u2-X09"}],"explanation":["무엇을 알아보는 실험인가요?","손전등 빛만 있어야 해요.","바깥 빛이 섞여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L02_challenge#10','sci',5,1,'u2','L02','g5_1_sci_u2_L02_challenge','lesson_challenge','SC5-1-u2-C8',4,'essay','teacher','빛이 없는 세상을 상상하여 생길 수 있는 불편한 점을 두 가지 쓰고, 그런 일이 생기는 까닭을 물체를 보는 데 필요한 것과 이어서 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C8","difficulty":4,"kind":"essay","stem":"빛이 없는 세상을 상상하여 생길 수 있는 불편한 점을 두 가지 쓰고, 그런 일이 생기는 까닭을 물체를 보는 데 필요한 것과 이어서 쓰세요.","answer_guide":{"answer":"예: 아침에 일어나 방문을 찾기 어렵다. 길을 걷다가 길가의 돌을 보지 못해 걸려 넘어질 수 있다. 우리가 물체를 보려면 물체를 비추는 빛이 있어야 하는데, 빛이 없으면 눈을 뜨고 있어도 아무것도 보이지 않기 때문이다.","scoring_points":["불편한 점 두 가지를 썼는가","빛이 있어야 물체가 보인다고 썼는가","눈을 떠도 보이지 않음을 썼는가"]},"explanation":["하루를 떠올려요.","볼 수 없으면 어떨까요?","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#1','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C9',1,'mc','auto','빛이 곧게 나아가는 성질을 무엇이라고 하나요?',ARRAY['SC5-1-u2-X11','SC5-1-u2-X19']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C9","difficulty":1,"kind":"mc","stem":"빛이 곧게 나아가는 성질을 무엇이라고 하나요?","options":[{"t":"빛의 직진","correct":true},{"t":"빛의 회전","mis":"SC5-1-u2-X11"},{"t":"빛의 흔들림","mis":"SC5-1-u2-X11"},{"t":"빛의 소리","mis":"SC5-1-u2-X19"}],"explanation":["곧게 나아가요.","두 글자예요.","빛의 직진이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#2','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C9',1,'sa','auto','「햇빛이나 레이저 지시기의 빛처럼 빛이 곧게 나아가는 성질을 빛의 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C9","difficulty":1,"kind":"sa","stem":"「햇빛이나 레이저 지시기의 빛처럼 빛이 곧게 나아가는 성질을 빛의 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["직진"],"explanation":["곧게 나아가요.","두 글자예요.","직진이에요."],"mis":"SC5-1-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#3','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C10',1,'ox','auto','햇빛을 관찰할 때 태양을 직접 바라보지 않아요.',ARRAY['SC5-1-u2-X14']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C10","difficulty":1,"kind":"ox","stem":"햇빛을 관찰할 때 태양을 직접 바라보지 않아요.","answer":"O","reason_options":[{"t":"태양을 직접 보면 눈을 다칠 수 있기 때문에","correct":true},{"t":"태양은 너무 멀어서 보아도 소용없기 때문에","mis":"SC5-1-u2-X14"}],"mis":"SC5-1-u2-X14","explanation":["안전을 떠올려요.","눈을 지켜요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#4','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C10',1,'mc','auto','레이저 지시기 앞쪽에 분무기로 물을 뿌리는 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X12']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C10","difficulty":1,"kind":"mc","stem":"레이저 지시기 앞쪽에 분무기로 물을 뿌리는 까닭은 어느 것인가요?","options":[{"t":"빛이 나아가는 길을 잘 볼 수 있기 때문에","correct":true},{"t":"빛을 차갑게 만들기 위해서","mis":"SC5-1-u2-X12"},{"t":"빛을 더 세게 만들기 위해서","mis":"SC5-1-u2-X12"},{"t":"빛의 방향을 바꾸기 위해서","mis":"SC5-1-u2-X12"}],"explanation":["물을 뿌리면 무엇이 보였나요?","빛의 길이에요.","잘 보이게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#5','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C10',2,'match','auto','빛의 직진 실험의 준비물과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C10","difficulty":2,"kind":"match","stem":"빛의 직진 실험의 준비물과 쓰임을 알맞게 이으세요.","pairs":[{"l":"구멍 뚫린 검은색 도화지","r":"햇빛이 통과할 구멍을 만든다"},{"l":"물이 든 분무기","r":"빛이 나아가는 길을 잘 보이게 한다"},{"l":"햇빛 보안경","r":"햇빛을 관찰할 때 눈을 지킨다"},{"l":"레이저 지시기","r":"어두운 교실에서 빛을 내보낸다"}],"mis":"SC5-1-u2-X14","explanation":["하나씩 떠올려요.","구멍·길·눈·빛이에요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#6','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C11',2,'mc','auto','물체 뒤에 그림자가 생기는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X15','SC5-1-u2-X13','SC5-1-u2-X11']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C11","difficulty":2,"kind":"mc","stem":"물체 뒤에 그림자가 생기는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"곧게 나아가던 빛이 불투명한 물체에 막혀 더 나아가지 못하기 때문에","correct":true},{"t":"물체가 스스로 그림자를 만들어 내기 때문에","mis":"SC5-1-u2-X15"},{"t":"빛이 물체를 돌아서 지나가기 때문에","mis":"SC5-1-u2-X13"},{"t":"빛이 물체 앞에서 구불구불 휘기 때문에","mis":"SC5-1-u2-X11"}],"explanation":["빛은 곧게 나아가요.","물체에 막혀요.","막힌 뒤쪽에 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#7','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C9',2,'ox','auto','빛은 구불구불한 길로 나아가요.',ARRAY['SC5-1-u2-X12']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C9","difficulty":2,"kind":"ox","stem":"빛은 구불구불한 길로 나아가요.","answer":"X","reason_options":[{"t":"햇빛도 레이저 지시기의 빛도 곧게 나아가기 때문에","correct":true},{"t":"물을 뿌릴 때에만 곧게 나아가기 때문에","mis":"SC5-1-u2-X12"}],"mis":"SC5-1-u2-X12","explanation":["실험을 떠올려요.","곧은 줄로 보였어요.","구불구불하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#8','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C10',2,'mc','auto','구멍 뚫린 도화지 아래에 다른 도화지를 수직으로 세웠을 때 보이는 모습은 어느 것인가요?',ARRAY['SC5-1-u2-X11','SC5-1-u2-X12']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C10","difficulty":2,"kind":"mc","stem":"구멍 뚫린 도화지 아래에 다른 도화지를 수직으로 세웠을 때 보이는 모습은 어느 것인가요?","options":[{"t":"구멍을 통과한 햇빛이 곧게 뻗어 있는 모습","correct":true},{"t":"햇빛이 구불구불하게 뻗은 모습","mis":"SC5-1-u2-X11"},{"t":"햇빛이 동그랗게 빙글빙글 도는 모습","mis":"SC5-1-u2-X11"},{"t":"햇빛이 구멍을 지나며 사라진 모습","mis":"SC5-1-u2-X12"}],"explanation":["빛의 길이 보여요.","어떤 모양이었나요?","곧게 뻗어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#9','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C11',2,'mc','auto','빛의 직진과 관련 있는 현상은 어느 것인가요?',ARRAY['SC5-1-u2-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C11","difficulty":2,"kind":"mc","stem":"빛의 직진과 관련 있는 현상은 어느 것인가요?","options":[{"t":"나무 아래에 그림자가 생긴다","correct":true},{"t":"종소리가 멀리까지 들린다","mis":"SC5-1-u2-X19"},{"t":"물이 얼어 얼음이 된다","mis":"SC5-1-u2-X19"},{"t":"바람에 나뭇잎이 흔들린다","mis":"SC5-1-u2-X19"}],"explanation":["빛이 하는 일을 찾아요.","그림자를 떠올려요.","그림자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_basic#10','sci',5,1,'u2','L03','g5_1_sci_u2_L03_basic','lesson_basic','SC5-1-u2-C11',3,'mc','auto','손전등 두 개로 한 물체를 비추었더니 그림자가 두 개 생겼어요. 그 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X15','SC5-1-u2-X11']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C11","difficulty":3,"kind":"mc","stem":"손전등 두 개로 한 물체를 비추었더니 그림자가 두 개 생겼어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 손전등의 빛이 각각 곧게 나아가다 물체에 막히기 때문에","correct":true},{"t":"손전등이 많을수록 물체가 커지기 때문에","mis":"SC5-1-u2-X15"},{"t":"그림자가 스스로 둘로 나뉘기 때문에","mis":"SC5-1-u2-X15"},{"t":"두 빛이 서로 부딪혀 두 갈래로 휘기 때문에","mis":"SC5-1-u2-X11"}],"explanation":["빛이 둘이에요.","각각 막혀요.","그림자도 둘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#1','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C11',2,'sa','auto','「빛이 곧게 나아가다가 □□□한 물체를 만나면 더 이상 나아가지 못해 그림자가 생깁니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C11","difficulty":2,"kind":"sa","stem":"「빛이 곧게 나아가다가 □□□한 물체를 만나면 더 이상 나아가지 못해 그림자가 생깁니다.」 □□□에 알맞은 말을 쓰세요.","answer":["불투명"],"explanation":["빛이 통과하지 못해요.","세 글자예요.","불투명이에요."],"mis":"SC5-1-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#2','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C10',2,'mc','auto','빛의 직진 실험의 ⑤ ( 가 )에 들어갈 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X03','SC5-1-u2-X12','SC5-1-u2-X14']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C10","difficulty":2,"kind":"mc","stem":"빛의 직진 실험의 ⑤ ( 가 )에 들어갈 알맞은 것은 어느 것인가요?","options":[{"t":"레이저 지시기 앞쪽에 분무기로 물을 뿌리며 빛을 관찰한다","correct":true},{"t":"레이저 지시기의 빛을 친구 눈에 비추어 본다","mis":"SC5-1-u2-X03"},{"t":"교실을 다시 밝게 하고 빛을 관찰한다","mis":"SC5-1-u2-X12"},{"t":"태양을 직접 바라보며 빛의 길을 찾는다","mis":"SC5-1-u2-X14"}],"explanation":["④ 다음이에요.","빛의 길을 보여 줘요.","물을 뿌려요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 검은색 도화지 아래에 검은색 도화지를 나란하게 든다.","② 아래 도화지를 위아래로 천천히 움직이며 햇빛을 관찰한다.","③ 아래 도화지를 구멍 아래에 수직으로 세우고 관찰한다.","④ 교실을 어둡게 하고 레이저 지시기를 켠다.","⑤ ( 가 )"],"title":"빛의 직진 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#3','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C9',3,'error','auto','빛의 직진 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X12','SC5-1-u2-X11']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C9","difficulty":3,"kind":"error","stem":"빛의 직진 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「물을 뿌려야만 빛이 곧게 나아가.」","correct":true,"mis_target":"SC5-1-u2-X12"},{"t":"유나 — 「물을 뿌리면 빛이 지나가는 길이 잘 보여.」","mis":"SC5-1-u2-X12"},{"t":"건우 — 「방향을 바꾸어도 빛은 곧게 나아가.」","mis":"SC5-1-u2-X11"}],"explanation":["물의 역할을 떠올려요.","물은 길을 보이게 해요.","지안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#4','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C11',3,'mc','auto','그림처럼 벽에 그림자가 생기는 것과 관계있는 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X13','SC5-1-u2-X19','SC5-1-u2-X11']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C11","difficulty":3,"kind":"mc","stem":"그림처럼 벽에 그림자가 생기는 것과 관계있는 빛의 성질은 어느 것인가요?","options":[{"t":"빛이 곧게 나아가는 성질","correct":true},{"t":"빛이 물체를 돌아서 지나가는 성질","mis":"SC5-1-u2-X13"},{"t":"빛이 소리를 내며 퍼지는 성질","mis":"SC5-1-u2-X19"},{"t":"빛이 물체에 닿으면 사라지지 않고 휘는 성질","mis":"SC5-1-u2-X11"}],"explanation":["빛줄기를 따라가요.","곧은 선이에요.","빛의 직진이에요."],"asset":{"type":"geo","items":[{"w":300,"h":180,"seg":[[[30,90],[280,45]],[[30,90],[280,135]],[[280,10],[280,170]],[[140,70],[160,70]],[[160,70],[160,110]],[[160,110],[140,110]],[[140,110],[140,70]]],"lab":[[[40,112],"손전등"],[[150,128],"상자"],[[250,90],"그림자"],[[262,162],"벽"]],"cap":"손전등 빛과 상자, 벽"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#5','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C9',3,'ox','auto','레이저 지시기의 방향을 위아래로 바꾸면 빛이 휘어서 나아가요.',ARRAY['SC5-1-u2-X11']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C9","difficulty":3,"kind":"ox","stem":"레이저 지시기의 방향을 위아래로 바꾸면 빛이 휘어서 나아가요.","answer":"X","reason_options":[{"t":"방향을 바꾸어도 빛은 언제나 곧게 나아가기 때문에","correct":true},{"t":"방향을 바꾸면 빛의 길이 휘기 때문에","mis":"SC5-1-u2-X11"}],"mis":"SC5-1-u2-X11","explanation":["바꿔 봐요 활동이에요.","언제나 곧았어요.","휘지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#6','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C10',3,'mc','auto','아래 도화지를 위아래로 천천히 움직일 때 구멍을 통과한 햇빛은 어떻게 보이나요?',ARRAY['SC5-1-u2-X11','SC5-1-u2-X12']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C10","difficulty":3,"kind":"mc","stem":"아래 도화지를 위아래로 천천히 움직일 때 구멍을 통과한 햇빛은 어떻게 보이나요?","options":[{"t":"구멍 모양의 밝은 빛이 도화지를 따라 그대로 비친다","correct":true},{"t":"빛이 구불구불 움직이며 다른 곳에 생긴다","mis":"SC5-1-u2-X11"},{"t":"도화지를 멀리하면 빛이 휘어 사라진다","mis":"SC5-1-u2-X11"},{"t":"물을 뿌려야만 빛이 비친다","mis":"SC5-1-u2-X12"}],"explanation":["구멍을 지난 햇빛이에요.","곧게 내려와요.","그대로 따라와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#7','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C9',3,'mc','auto','빛이 곧게 나아간다는 것을 알 수 있는 관찰은 어느 것인가요?',ARRAY['SC5-1-u2-X11','SC5-1-u2-X13']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C9","difficulty":3,"kind":"mc","stem":"빛이 곧게 나아간다는 것을 알 수 있는 관찰은 어느 것인가요?","options":[{"t":"물을 뿌리자 레이저 지시기의 빛이 곧은 줄로 보였다","correct":true},{"t":"빛이 빙글빙글 돌며 나아갔다","mis":"SC5-1-u2-X11"},{"t":"빛이 구불구불한 길로 나아갔다","mis":"SC5-1-u2-X11"},{"t":"빛이 물체를 돌아 벽까지 닿았다","mis":"SC5-1-u2-X13"}],"explanation":["곧은 줄을 찾아요.","물을 뿌렸어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#8','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C11',4,'mc','auto','해가 서쪽 하늘에 떠 있을 때 놀이터 미끄럼틀의 그림자는 어느 쪽에 생기나요?',ARRAY['SC5-1-u2-X15','SC5-1-u2-X13']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C11","difficulty":4,"kind":"mc","stem":"해가 서쪽 하늘에 떠 있을 때 놀이터 미끄럼틀의 그림자는 어느 쪽에 생기나요?","options":[{"t":"해의 반대쪽인 동쪽","correct":true},{"t":"해가 있는 쪽인 서쪽","mis":"SC5-1-u2-X15"},{"t":"그림자는 아무 쪽에나 생긴다","mis":"SC5-1-u2-X15"},{"t":"빛이 미끄럼틀을 돌아가 그림자가 생기지 않는다","mis":"SC5-1-u2-X13"}],"explanation":["빛은 해에서 와요.","막힌 뒤쪽이에요.","반대쪽인 동쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#9','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C10',4,'mc','auto','어떤 모둠이 밝은 교실에서 물을 뿌리지 않고 레이저 지시기의 빛을 관찰했어요. 어떤 일이 생길까요?',ARRAY['SC5-1-u2-X12','SC5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C10","difficulty":4,"kind":"mc","stem":"어떤 모둠이 밝은 교실에서 물을 뿌리지 않고 레이저 지시기의 빛을 관찰했어요. 어떤 일이 생길까요?","options":[{"t":"빛이 나아가는 길이 잘 보이지 않는다","correct":true},{"t":"빛이 곧게 나아가지 않고 휜다","mis":"SC5-1-u2-X12"},{"t":"물이 없어 빛이 바로 사라진다","mis":"SC5-1-u2-X12"},{"t":"아무 문제 없이 빛의 길이 또렷하게 보인다","mis":"SC5-1-u2-X03"}],"explanation":["어둡게 하고 물을 뿌렸어요.","둘 다 빠졌어요.","길이 잘 안 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L03_challenge#10','sci',5,1,'u2','L03','g5_1_sci_u2_L03_challenge','lesson_challenge','SC5-1-u2-C11',4,'essay','teacher','그림자가 생기는 까닭을 빛의 직진과 이어서 설명하고, 손전등 두 개로 비추면 그림자가 두 개 생기는 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C11","difficulty":4,"kind":"essay","stem":"그림자가 생기는 까닭을 빛의 직진과 이어서 설명하고, 손전등 두 개로 비추면 그림자가 두 개 생기는 까닭도 쓰세요.","answer_guide":{"answer":"예: 빛은 곧게 나아가는데, 곧게 나아가던 빛이 불투명한 물체를 만나면 더 이상 나아가지 못해 물체 뒤쪽에 빛이 닿지 않는 곳이 생긴다. 이것이 그림자이다. 손전등 두 개로 비추면 두 빛이 각각 곧게 나아가다가 물체에 막히기 때문에 그림자도 두 개 생긴다.","scoring_points":["빛이 곧게 나아간다고 썼는가","불투명한 물체에 막힌다고 썼는가","두 빛이 각각 막힌다고 썼는가"]},"explanation":["빛이 나아가는 모습을 떠올려요.","막힌 뒤쪽이에요.","두 개의 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#1','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C12',1,'mc','auto','곧게 나아가던 빛이 거울에 부딪치면 어떻게 되나요?',ARRAY['SC5-1-u2-X16','SC5-1-u2-X11']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C12","difficulty":1,"kind":"mc","stem":"곧게 나아가던 빛이 거울에 부딪치면 어떻게 되나요?","options":[{"t":"나아가는 방향이 바뀐다","correct":true},{"t":"그 자리에서 사라진다","mis":"SC5-1-u2-X16"},{"t":"방향이 바뀌지 않고 거울을 통과한다","mis":"SC5-1-u2-X16"},{"t":"빙글빙글 돌기 시작한다","mis":"SC5-1-u2-X11"}],"explanation":["모양판 맞히기를 떠올려요.","거울에서 빛이 달라져요.","방향이 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#2','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C12',1,'sa','auto','「빛이 직진하다가 거울에 부딪쳐 나아가는 방향이 바뀌는 성질을 빛의 □□라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C12","difficulty":1,"kind":"sa","stem":"「빛이 직진하다가 거울에 부딪쳐 나아가는 방향이 바뀌는 성질을 빛의 □□라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["반사"],"explanation":["거울에서 일어나요.","두 글자예요.","반사예요."],"mis":"SC5-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#3','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C13',1,'ox','auto','평면거울을 다룰 때 거울이 깨지지 않도록 조심해요.',ARRAY['SC5-1-u2-X18']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C13","difficulty":1,"kind":"ox","stem":"평면거울을 다룰 때 거울이 깨지지 않도록 조심해요.","answer":"O","reason_options":[{"t":"깨진 거울에 다칠 수 있기 때문에","correct":true},{"t":"깨진 거울에서는 빛이 더 세지기 때문에","mis":"SC5-1-u2-X18"}],"mis":"SC5-1-u2-X18","explanation":["안전을 떠올려요.","거울은 깨질 수 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#4','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C14',1,'mc','auto','우리가 물체를 볼 수 있는 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X06','SC5-1-u2-X05']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C14","difficulty":1,"kind":"mc","stem":"우리가 물체를 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"물체가 반사한 빛이 우리 눈에 들어오기 때문에","correct":true},{"t":"눈에서 빛이 나와 물체에 닿기 때문에","mis":"SC5-1-u2-X06"},{"t":"물체가 소리를 내어 알려 주기 때문에","mis":"SC5-1-u2-X05"},{"t":"물체가 우리 눈을 끌어당기기 때문에","mis":"SC5-1-u2-X06"}],"explanation":["빛은 어디서 어디로 갈까요?","물체에서 눈으로 와요.","반사한 빛이 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#5','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C13',2,'match','auto','빛의 반사 실험의 준비물과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"match","stem":"빛의 반사 실험의 준비물과 쓰임을 알맞게 이으세요.","pairs":[{"l":"받침대","r":"거울을 수직으로 세워 준다"},{"l":"평면거울","r":"빛이 부딪쳐 방향이 바뀐다"},{"l":"모양판","r":"빛을 맞힐 목표가 된다"},{"l":"레이저 보안경","r":"레이저를 쓸 때 눈을 지킨다"}],"mis":"SC5-1-u2-X18","explanation":["하나씩 떠올려요.","세우기·바꾸기·목표·눈이에요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#6','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C14',2,'mc','auto','빛의 반사와 관련 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X19']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C14","difficulty":2,"kind":"mc","stem":"빛의 반사와 관련 있는 것은 어느 것인가요?","options":[{"t":"잔잔한 물에 산의 모습이 비친다","correct":true},{"t":"물체 뒤에 그림자가 생긴다","mis":"SC5-1-u2-X19"},{"t":"물이 얼어 얼음이 된다","mis":"SC5-1-u2-X19"},{"t":"멀리서 종소리가 들린다","mis":"SC5-1-u2-X19"}],"explanation":["되비치는 것을 찾아요.","물 위에 비쳐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#7','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C12',2,'ox','auto','거울을 치워도 빛은 나아가는 방향이 바뀌어요.',ARRAY['SC5-1-u2-X17']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C12","difficulty":2,"kind":"ox","stem":"거울을 치워도 빛은 나아가는 방향이 바뀌어요.","answer":"X","reason_options":[{"t":"빛은 거울에 부딪쳐야 방향이 바뀌고, 거울이 없으면 곧게 나아가기 때문에","correct":true},{"t":"빛은 스스로 방향을 바꾸며 나아가기 때문에","mis":"SC5-1-u2-X17"}],"mis":"SC5-1-u2-X17","explanation":["거울 치우기를 떠올려요.","거울이 없으면 곧게 가요.","바뀌지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#8','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C13',2,'mc','auto','레이저 지시기의 빛으로 모양판을 맞히기 어려울 때 해 볼 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X18']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"mc","stem":"레이저 지시기의 빛으로 모양판을 맞히기 어려울 때 해 볼 일로 알맞은 것은 어느 것인가요?","options":[{"t":"레이저 지시기는 그대로 두고 평면거울을 움직여 본다","correct":true},{"t":"레이저 지시기의 빛을 더 세게 만든다","mis":"SC5-1-u2-X18"},{"t":"교실을 밝게 해서 빛이 잘 보이게 한다","mis":"SC5-1-u2-X18"},{"t":"모양판을 치우고 벽에 바로 비춘다","mis":"SC5-1-u2-X18"}],"explanation":["빛이 닿는 곳을 바꿔야 해요.","거울의 방향이 중요해요.","거울을 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#9','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C14',2,'mc','auto','손목시계에 햇빛이 닿자 천장에 동그란 빛이 생겼어요. 그 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X28','SC5-1-u2-X05','SC5-1-u2-X16']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C14","difficulty":2,"kind":"mc","stem":"손목시계에 햇빛이 닿자 천장에 동그란 빛이 생겼어요. 그 까닭은 어느 것인가요?","options":[{"t":"시계에 닿은 햇빛이 반사되어 천장으로 갔기 때문에","correct":true},{"t":"시계가 스스로 빛을 내기 때문에","mis":"SC5-1-u2-X28"},{"t":"천장에 전등이 숨어 있기 때문에","mis":"SC5-1-u2-X05"},{"t":"햇빛이 시계를 그대로 통과했기 때문에","mis":"SC5-1-u2-X16"}],"explanation":["빛은 어디서 왔나요?","햇빛이 시계에 닿았어요.","반사되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_basic#10','sci',5,1,'u2','L04','g5_1_sci_u2_L04_basic','lesson_basic','SC5-1-u2-C12',3,'mc','auto','그림에서 레이저 지시기의 빛이 모양판 나에 닿은 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X16','SC5-1-u2-X11','SC5-1-u2-X17']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C12","difficulty":3,"kind":"mc","stem":"그림에서 레이저 지시기의 빛이 모양판 나에 닿은 까닭은 어느 것인가요?","options":[{"t":"빛이 평면거울에 부딪쳐 나아가는 방향이 바뀌었기 때문에","correct":true},{"t":"빛이 평면거울을 통과했기 때문에","mis":"SC5-1-u2-X16"},{"t":"빛이 스스로 휘어 나아갔기 때문에","mis":"SC5-1-u2-X11"},{"t":"모양판이 빛을 끌어당겼기 때문에","mis":"SC5-1-u2-X17"}],"explanation":["빛줄기를 따라가요.","거울에서 방향이 바뀌어요.","반사 때문이에요."],"asset":{"type":"geo","items":[{"w":300,"h":205,"seg":[[[260,15],[260,185]],[[40,40],[260,100]],[[260,100],[40,160]]],"lab":[[[80,24],"레이저 지시기"],[[238,196],"평면거울"],[[22,100],"가"],[[22,160],"나"],[[22,190],"다"]],"cap":"평면거울로 모양판 맞히기"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#1','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C13',2,'sa','auto','「흰 종이를 깔고, 받침대에 끼운 □□거울을 수직으로 세웁니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"sa","stem":"「흰 종이를 깔고, 받침대에 끼운 □□거울을 수직으로 세웁니다.」 □□에 알맞은 말을 쓰세요.","answer":["평면"],"explanation":["판판한 거울이에요.","두 글자예요.","평면거울이에요."],"mis":"SC5-1-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#2','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C13',2,'mc','auto','평면거울 실험의 ⑤ ( 가 )에 들어갈 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X17','SC5-1-u2-X18','SC5-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"mc","stem":"평면거울 실험의 ⑤ ( 가 )에 들어갈 알맞은 것은 어느 것인가요?","options":[{"t":"각 모양판에 빛이 닿도록 레이저 지시기를 움직여 본다","correct":true},{"t":"거울을 치우고 모양판에 바로 비춘다","mis":"SC5-1-u2-X17"},{"t":"교실을 밝게 하고 빛을 찾는다","mis":"SC5-1-u2-X18"},{"t":"레이저 지시기의 빛을 친구 눈에 비춘다","mis":"SC5-1-u2-X03"}],"explanation":["④에서 모양판을 세웠어요.","모양판을 맞혀요.","빛이 닿게 움직여요."],"asset":{"type":"passage","lines":["① 흰 종이를 깔고 받침대에 끼운 평면거울을 수직으로 세운다.","② 교실을 어둡게 하고 레이저 지시기를 거울을 향해 켠다.","③ 레이저 지시기를 여러 방향으로 비추며 빛을 관찰한다.","④ 모양판을 접어 세우고 떨어진 곳에 거울을 세운다.","⑤ ( 가 )"],"title":"평면거울 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#3','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C12',3,'error','auto','평면거울 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X16','SC5-1-u2-X17']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C12","difficulty":3,"kind":"error","stem":"평면거울 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「거울에 닿은 빛은 거울 속으로 들어가 사라져.」","correct":true,"mis_target":"SC5-1-u2-X16"},{"t":"준호 — 「거울의 방향을 바꾸면 빛이 닿는 곳도 달라져.」","mis":"SC5-1-u2-X17"},{"t":"시윤 — 「거울을 치우면 빛은 곧게 나아가.」","mis":"SC5-1-u2-X17"}],"explanation":["거울에 닿은 빛을 떠올려요.","방향이 바뀌었어요.","라희가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#4','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C14',3,'mc','auto','산꼭대기에 거울을 설치해 그늘진 마을에 햇빛이 들게 했어요. 이용한 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X19','SC5-1-u2-X28']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C14","difficulty":3,"kind":"mc","stem":"산꼭대기에 거울을 설치해 그늘진 마을에 햇빛이 들게 했어요. 이용한 빛의 성질은 어느 것인가요?","options":[{"t":"빛의 반사","correct":true},{"t":"그림자가 생기는 성질","mis":"SC5-1-u2-X19"},{"t":"거울이 스스로 빛을 만드는 성질","mis":"SC5-1-u2-X28"},{"t":"빛이 소리로 바뀌는 성질","mis":"SC5-1-u2-X19"}],"explanation":["거울로 햇빛을 보내요.","방향을 바꿔요.","반사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#5','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C14',3,'ox','auto','잔잔한 물에 풍경이 비쳐 보이는 것은 빛의 반사와 관련 있어요.',ARRAY['SC5-1-u2-X28']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C14","difficulty":3,"kind":"ox","stem":"잔잔한 물에 풍경이 비쳐 보이는 것은 빛의 반사와 관련 있어요.","answer":"O","reason_options":[{"t":"풍경에서 온 빛이 물에 반사되어 눈에 들어오기 때문에","correct":true},{"t":"물이 스스로 풍경 모양의 빛을 내기 때문에","mis":"SC5-1-u2-X28"}],"mis":"SC5-1-u2-X28","explanation":["물이 거울 같아요.","빛이 되비쳐요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#6','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C13',3,'mc','auto','레이저 지시기는 그대로 두고 평면거울의 방향만 바꾸었어요. 어떤 일이 생기나요?',ARRAY['SC5-1-u2-X17','SC5-1-u2-X16']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C13","difficulty":3,"kind":"mc","stem":"레이저 지시기는 그대로 두고 평면거울의 방향만 바꾸었어요. 어떤 일이 생기나요?","options":[{"t":"빛이 닿는 곳이 달라진다","correct":true},{"t":"빛이 닿는 곳은 그대로이다","mis":"SC5-1-u2-X17"},{"t":"빛이 거울에서 사라진다","mis":"SC5-1-u2-X16"},{"t":"빛이 거울을 통과해 뒤로 간다","mis":"SC5-1-u2-X16"}],"explanation":["거울 방향을 바꿨어요.","빛의 방향도 바뀌어요.","닿는 곳이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#7','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C14',3,'mc','auto','그림자와 자동차 거울을 빛의 성질과 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C14","difficulty":3,"kind":"mc","stem":"그림자와 자동차 거울을 빛의 성질과 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"나무 아래 그림자 — 직진, 자동차 거울에 보이는 뒤차 — 반사","correct":true},{"t":"나무 아래 그림자 — 반사, 자동차 거울에 보이는 뒤차 — 직진","mis":"SC5-1-u2-X19"},{"t":"두 현상 모두 반사","mis":"SC5-1-u2-X19"},{"t":"두 현상 모두 빛과 관계없음","mis":"SC5-1-u2-X19"}],"explanation":["그림자는 막혀서 생겨요.","거울은 되비쳐요.","직진과 반사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#8','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C14',4,'mc','auto','친구가 「눈에서 빛이 나와야 물체가 보여.」라고 해요. 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X05','SC5-1-u2-X06']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C14","difficulty":4,"kind":"mc","stem":"친구가 「눈에서 빛이 나와야 물체가 보여.」라고 해요. 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손전등을 끈 어둠상자 속은 눈을 떠도 안 보였고, 물체가 반사한 빛이 눈에 들어와야 보인다","correct":true},{"t":"눈을 크게 뜨면 어두워도 잘 보인다","mis":"SC5-1-u2-X07"},{"t":"물체가 소리를 내야 보인다","mis":"SC5-1-u2-X05"},{"t":"눈에서 나온 빛이 거울에 반사되어 보인다","mis":"SC5-1-u2-X06"}],"explanation":["어둠상자를 떠올려요.","빛은 물체에서 눈으로 와요.","첫 번째가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#9','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C13',4,'mc','auto','레이저 지시기를 그대로 둔 채 모양판 가, 나, 다를 차례로 맞히려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X18','SC5-1-u2-X17']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C13","difficulty":4,"kind":"mc","stem":"레이저 지시기를 그대로 둔 채 모양판 가, 나, 다를 차례로 맞히려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"평면거울의 방향을 조금씩 바꾸어 본다","correct":true},{"t":"레이저 지시기의 빛을 더 세게 한다","mis":"SC5-1-u2-X18"},{"t":"평면거울을 치운다","mis":"SC5-1-u2-X17"},{"t":"교실을 밝게 한다","mis":"SC5-1-u2-X18"}],"explanation":["빛의 출발은 그대로예요.","거울을 바꿔요.","방향을 조금씩 바꿔요."],"asset":{"type":"geo","items":[{"w":300,"h":205,"seg":[[[260,15],[260,185]],[[40,40],[260,100]],[[260,100],[40,160]]],"lab":[[[80,24],"레이저 지시기"],[[238,196],"평면거울"],[[22,100],"가"],[[22,160],"나"],[[22,190],"다"]],"cap":"평면거울로 모양판 맞히기"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L04_challenge#10','sci',5,1,'u2','L04','g5_1_sci_u2_L04_challenge','lesson_challenge','SC5-1-u2-C12',4,'essay','teacher','빛이 거울에 부딪칠 때 일어나는 일을 쓰고, 산꼭대기의 거울로 그늘진 마을에 햇빛을 보내는 방법을 이 성질과 이어서 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C12","difficulty":4,"kind":"essay","stem":"빛이 거울에 부딪칠 때 일어나는 일을 쓰고, 산꼭대기의 거울로 그늘진 마을에 햇빛을 보내는 방법을 이 성질과 이어서 설명하세요.","answer_guide":{"answer":"예: 곧게 나아가던 빛이 거울에 부딪치면 나아가는 방향이 바뀐다. 이것을 빛의 반사라고 한다. 산꼭대기에 거울을 세우고 햇빛이 거울에 부딪친 뒤 그늘진 마을 쪽으로 나아가도록 거울의 방향을 맞추면, 반사된 햇빛이 마을을 비춘다.","scoring_points":["방향이 바뀐다고 썼는가","빛의 반사라는 이름을 썼는가","거울의 방향을 맞춘다고 썼는가"]},"explanation":["거울에 닿은 빛을 떠올려요.","이름을 써요.","마을 쪽으로 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#1','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C18',1,'mc','auto','빛이 직진하다가 서로 다른 물질의 경계에서 꺾여 나아가는 성질은 무엇인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X19']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C18","difficulty":1,"kind":"mc","stem":"빛이 직진하다가 서로 다른 물질의 경계에서 꺾여 나아가는 성질은 무엇인가요?","options":[{"t":"빛의 굴절","correct":true},{"t":"빛의 직진","mis":"SC5-1-u2-X23"},{"t":"빛의 반사","mis":"SC5-1-u2-X23"},{"t":"빛의 그림자","mis":"SC5-1-u2-X19"}],"explanation":["경계에서 꺾여요.","두 글자예요.","빛의 굴절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#2','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C15',1,'sa','auto','「가운데가 볼록하고 가장자리로 갈수록 얇아지는 렌즈를 □□ 렌즈라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C15","difficulty":1,"kind":"sa","stem":"「가운데가 볼록하고 가장자리로 갈수록 얇아지는 렌즈를 □□ 렌즈라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["볼록"],"explanation":["가운데가 튀어나왔어요.","두 글자예요.","볼록 렌즈예요."],"mis":"SC5-1-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#3','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C17',1,'ox','auto','볼록 렌즈로 태양을 바라보면 안 돼요.',ARRAY['SC5-1-u2-X24']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C17","difficulty":1,"kind":"ox","stem":"볼록 렌즈로 태양을 바라보면 안 돼요.","answer":"O","reason_options":[{"t":"눈을 크게 다칠 수 있기 때문에","correct":true},{"t":"렌즈가 더러워지기 때문에","mis":"SC5-1-u2-X24"}],"mis":"SC5-1-u2-X24","explanation":["안전을 떠올려요.","눈을 지켜요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#4','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C16',1,'mc','auto','빛을 렌즈에 비추면 렌즈를 통과한 빛은 어떻게 되나요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X23']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C16","difficulty":1,"kind":"mc","stem":"빛을 렌즈에 비추면 렌즈를 통과한 빛은 어떻게 되나요?","options":[{"t":"나아가는 방향이 꺾인다","correct":true},{"t":"방향이 바뀌지 않고 그대로 곧게 나아간다","mis":"SC5-1-u2-X25"},{"t":"렌즈 속에서 사라진다","mis":"SC5-1-u2-X25"},{"t":"거울처럼 되돌아 나온다","mis":"SC5-1-u2-X23"}],"explanation":["렌즈를 지난 빛을 떠올려요.","방향이 달라졌어요.","꺾여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#5','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C17',2,'match','auto','렌즈와 물 실험의 준비물과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C17","difficulty":2,"kind":"match","stem":"렌즈와 물 실험의 준비물과 쓰임을 알맞게 이으세요.","pairs":[{"l":"스포이트로 넣은 우유 몇 방울","r":"물속에서 빛이 지나가는 길이 보이게 한다"},{"l":"물이 든 분무기","r":"공기 중에서 빛이 지나가는 길이 보이게 한다"},{"l":"유리 막대","r":"떨어뜨린 우유를 물에 고루 젓는다"},{"l":"받침대","r":"렌즈를 끼워 세워 준다"}],"mis":"SC5-1-u2-X24","explanation":["하나씩 떠올려요.","물속·공기 중·젓기·세우기예요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#6','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C15',2,'mc','auto','오목 렌즈는 어떤 렌즈인가요?',ARRAY['SC5-1-u2-X20']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C15","difficulty":2,"kind":"mc","stem":"오목 렌즈는 어떤 렌즈인가요?","options":[{"t":"가운데가 오목하고 가장자리로 갈수록 두꺼워지는 렌즈","correct":true},{"t":"가운데가 볼록하고 가장자리로 갈수록 얇아지는 렌즈","mis":"SC5-1-u2-X20"},{"t":"앞뒤가 모두 평평한 렌즈","mis":"SC5-1-u2-X20"},{"t":"빛이 통과하지 못하는 렌즈","mis":"SC5-1-u2-X20"}],"explanation":["오목은 들어간 모양이에요.","가운데가 얇아요.","가장자리가 두꺼워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#7','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C17',2,'mc','auto','레이저 지시기의 빛이 공기에서 물로 비스듬히 들어갈 때 어떻게 되나요?',ARRAY['SC5-1-u2-X22','SC5-1-u2-X11']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C17","difficulty":2,"kind":"mc","stem":"레이저 지시기의 빛이 공기에서 물로 비스듬히 들어갈 때 어떻게 되나요?","options":[{"t":"공기와 물의 경계에서 나아가는 방향이 꺾인다","correct":true},{"t":"아무 일 없이 그대로 곧게 나아간다","mis":"SC5-1-u2-X22"},{"t":"물속으로 들어가면 사라진다","mis":"SC5-1-u2-X22"},{"t":"물속에서 빙글빙글 돈다","mis":"SC5-1-u2-X11"}],"explanation":["경계를 떠올려요.","공기와 물이 만나요.","꺾여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#8','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C16',2,'ox','auto','볼록 렌즈와 오목 렌즈를 지난 빛은 똑같이 나아가요.',ARRAY['SC5-1-u2-X21']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C16","difficulty":2,"kind":"ox","stem":"볼록 렌즈와 오목 렌즈를 지난 빛은 똑같이 나아가요.","answer":"X","reason_options":[{"t":"볼록 렌즈를 지난 빛은 모이고 오목 렌즈를 지난 빛은 퍼지기 때문에","correct":true},{"t":"렌즈 모양과 관계없이 빛은 똑같이 꺾이기 때문에","mis":"SC5-1-u2-X21"}],"mis":"SC5-1-u2-X21","explanation":["두 렌즈를 견줘요.","꺾이는 모습이 달랐어요.","똑같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#9','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C18',2,'mc','auto','빛의 굴절과 관련 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X19','SC5-1-u2-X23']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C18","difficulty":2,"kind":"mc","stem":"빛의 굴절과 관련 있는 것은 어느 것인가요?","options":[{"t":"돋보기로 보면 글씨가 크게 보인다","correct":true},{"t":"물체 뒤에 그림자가 생긴다","mis":"SC5-1-u2-X19"},{"t":"거울에 부딪친 빛이 되돌아 나온다","mis":"SC5-1-u2-X23"},{"t":"손전등으로 모스 부호를 보낸다","mis":"SC5-1-u2-X19"}],"explanation":["렌즈를 찾아요.","돋보기는 렌즈예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_basic#10','sci',5,1,'u2','L05','g5_1_sci_u2_L05_basic','lesson_basic','SC5-1-u2-C17',3,'mc','auto','물속에서 빛을 물 밖으로 나아가도록 아래쪽에서 위쪽으로 비스듬히 비추면 어떻게 될까요?',ARRAY['SC5-1-u2-X22','SC5-1-u2-X11']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C17","difficulty":3,"kind":"mc","stem":"물속에서 빛을 물 밖으로 나아가도록 아래쪽에서 위쪽으로 비스듬히 비추면 어떻게 될까요?","options":[{"t":"물과 공기의 경계에서 나아가는 방향이 꺾인다","correct":true},{"t":"아무 일 없이 그대로 곧게 나아간다","mis":"SC5-1-u2-X22"},{"t":"물 밖으로 나오지 못하고 사라진다","mis":"SC5-1-u2-X22"},{"t":"물속에서 빙글빙글 돌기만 한다","mis":"SC5-1-u2-X11"}],"explanation":["반대 방향이에요.","그래도 경계를 지나요.","꺾여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#1','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C18',2,'sa','auto','「빛이 렌즈를 통과하거나 공기에서 물로 비스듬히 들어갈 때 꺾여 나아가는 성질을 빛의 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C18","difficulty":2,"kind":"sa","stem":"「빛이 렌즈를 통과하거나 공기에서 물로 비스듬히 들어갈 때 꺾여 나아가는 성질을 빛의 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["굴절"],"explanation":["꺾여 나아가요.","두 글자예요.","굴절이에요."],"mis":"SC5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#2','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C16',2,'mc','auto','그림의 렌즈 ㉠은 어느 렌즈이고, 그렇게 판단한 까닭은 무엇인가요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X23','SC5-1-u2-X25']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C16","difficulty":2,"kind":"mc","stem":"그림의 렌즈 ㉠은 어느 렌즈이고, 그렇게 판단한 까닭은 무엇인가요?","options":[{"t":"볼록 렌즈 — 지난 빛이 안쪽으로 꺾여 한곳으로 모인다","correct":true},{"t":"오목 렌즈 — 지난 빛이 안쪽으로 꺾여 한곳으로 모인다","mis":"SC5-1-u2-X21"},{"t":"평면거울 — 빛이 부딪쳐 되돌아 나온다","mis":"SC5-1-u2-X23"},{"t":"렌즈가 아니다 — 빛이 꺾이지 않았다","mis":"SC5-1-u2-X25"}],"explanation":["빛줄기를 따라가요.","한곳으로 모였어요.","볼록 렌즈예요."],"asset":{"type":"geo","items":[{"w":300,"h":180,"seg":[[[20,50],[150,50]],[[20,90],[150,90]],[[20,130],[150,130]],[[150,50],[250,90]],[[150,90],[250,90]],[[150,130],[250,90]]],"lab":[[[150,168],"렌즈 ㉠"]],"oval":[[150,90,10,66]],"cap":"렌즈 ㉠을 지난 빛"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#3','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C17',3,'error','auto','렌즈와 물 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X22','SC5-1-u2-X25']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C17","difficulty":3,"kind":"error","stem":"렌즈와 물 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「빛은 물속으로 들어갈 때에는 꺾이지 않아.」","correct":true,"mis_target":"SC5-1-u2-X22"},{"t":"하준 — 「물을 빼면 빛은 꺾이지 않고 곧게 나아가.」","mis":"SC5-1-u2-X25"},{"t":"나연 — 「렌즈를 지난 빛도 방향이 꺾여.」","mis":"SC5-1-u2-X25"}],"explanation":["물에 비춘 빛을 떠올려요.","경계에서 꺾였어요.","소율이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#4','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C18',3,'mc','auto','거울과 렌즈에서 본 두 현상을 빛의 성질과 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X19']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C18","difficulty":3,"kind":"mc","stem":"거울과 렌즈에서 본 두 현상을 빛의 성질과 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"거울에 부딪친 빛이 모양판에 닿음 — 반사, 렌즈를 지나며 빛이 꺾임 — 굴절","correct":true},{"t":"거울에 부딪친 빛이 모양판에 닿음 — 굴절, 렌즈를 지나며 빛이 꺾임 — 반사","mis":"SC5-1-u2-X23"},{"t":"두 현상 모두 반사","mis":"SC5-1-u2-X23"},{"t":"두 현상 모두 직진","mis":"SC5-1-u2-X19"}],"explanation":["거울과 렌즈를 견줘요.","되비침과 꺾임이에요.","반사와 굴절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#5','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C16',3,'mc','auto','볼록 렌즈와 오목 렌즈를 지난 빛을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X25']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C16","difficulty":3,"kind":"mc","stem":"볼록 렌즈와 오목 렌즈를 지난 빛을 바르게 견준 것은 어느 것인가요?","options":[{"t":"볼록 렌즈는 안쪽으로 모이게, 오목 렌즈는 바깥쪽으로 퍼지게 꺾인다","correct":true},{"t":"볼록 렌즈는 퍼지게, 오목 렌즈는 모이게 꺾인다","mis":"SC5-1-u2-X21"},{"t":"두 렌즈 모두 한곳으로 모이게 꺾인다","mis":"SC5-1-u2-X21"},{"t":"두 렌즈 모두 꺾이지 않고 곧게 나아간다","mis":"SC5-1-u2-X25"}],"explanation":["관찰 기록을 봐요.","안쪽과 바깥쪽이에요.","모임과 퍼짐이에요."],"asset":{"type":"passage","lines":["볼록 렌즈 — 지난 빛이 안쪽으로 꺾였다.","오목 렌즈 — 지난 빛이 바깥쪽으로 꺾였다.","공기에서 물로 비스듬히 — 공기와 물의 경계에서 꺾였다.","물을 뺀 빈 통 — 꺾이는 곳 없이 곧게 나아갔다."],"title":"렌즈와 물에 비춘 빛 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#6','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C17',3,'ox','auto','물에 우유를 몇 방울 떨어뜨리는 까닭은 물속에서 빛이 지나가는 길을 보기 위해서예요.',ARRAY['SC5-1-u2-X24']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C17","difficulty":3,"kind":"ox","stem":"물에 우유를 몇 방울 떨어뜨리는 까닭은 물속에서 빛이 지나가는 길을 보기 위해서예요.","answer":"O","reason_options":[{"t":"우유를 넣으면 물속의 빛의 길이 잘 보이기 때문에","correct":true},{"t":"우유를 넣어야만 빛이 꺾이기 때문에","mis":"SC5-1-u2-X24"}],"mis":"SC5-1-u2-X24","explanation":["우유의 역할이에요.","길을 보여 줘요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#7','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C18',3,'mc','auto','증강 현실(AR)이나 시뮬레이션으로 빛을 관찰하면 좋은 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X11','SC5-1-u2-X24']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C18","difficulty":3,"kind":"mc","stem":"증강 현실(AR)이나 시뮬레이션으로 빛을 관찰하면 좋은 까닭은 어느 것인가요?","options":[{"t":"눈으로 보기 어려운 빛의 길을 거울과 렌즈의 크기·각도를 바꾸며 볼 수 있어서","correct":true},{"t":"시뮬레이션에서만 빛이 꺾이고 실제 빛은 꺾이지 않아서","mis":"SC5-1-u2-X25"},{"t":"증강 현실에서는 빛이 구불구불 나아가는 모습을 볼 수 있어서","mis":"SC5-1-u2-X11"},{"t":"렌즈를 맛보아도 안전하기 때문에","mis":"SC5-1-u2-X24"}],"explanation":["체험 더하기를 떠올려요.","마음대로 바꿔 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#8','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C17',4,'mc','auto','그림처럼 꺾이던 빛이 있어요. 통의 물을 모두 빼고 같은 자리에서 똑같이 비추면 빛은 어떻게 나아갈까요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X22','SC5-1-u2-X23']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C17","difficulty":4,"kind":"mc","stem":"그림처럼 꺾이던 빛이 있어요. 통의 물을 모두 빼고 같은 자리에서 똑같이 비추면 빛은 어떻게 나아갈까요?","options":[{"t":"꺾이는 곳 없이 곧게 나아간다","correct":true},{"t":"그림과 똑같이 꺾여 나아간다","mis":"SC5-1-u2-X25"},{"t":"통 바닥에 닿지 못하고 사라진다","mis":"SC5-1-u2-X22"},{"t":"거울처럼 되돌아 나온다","mis":"SC5-1-u2-X23"}],"explanation":["물을 뺐어요.","경계가 없어요.","곧게 나아가요."],"asset":{"type":"geo","items":[{"w":300,"h":200,"seg":[[[10,100],[290,100]],[[60,25],[150,100]],[[150,100],[195,190]]],"lab":[[[88,12],"레이저 지시기"],[[40,82],"공기"],[[40,140],"물"],[[262,88],"경계"]],"cap":"공기에서 물로 비춘 빛"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#9','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C16',4,'mc','auto','그림의 렌즈 ㉡을 지난 빛을 보고 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X23','SC5-1-u2-X25']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C16","difficulty":4,"kind":"mc","stem":"그림의 렌즈 ㉡을 지난 빛을 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"바깥쪽으로 꺾여 퍼지므로 오목 렌즈이다","correct":true},{"t":"안쪽으로 꺾여 모이므로 볼록 렌즈이다","mis":"SC5-1-u2-X21"},{"t":"빛이 렌즈에 부딪쳐 반사되었다","mis":"SC5-1-u2-X23"},{"t":"렌즈를 지나도 빛은 꺾이지 않았다","mis":"SC5-1-u2-X25"}],"explanation":["빛줄기 끝을 봐요.","점점 벌어져요.","오목 렌즈예요."],"asset":{"type":"geo","items":[{"w":300,"h":180,"seg":[[[20,50],[150,50]],[[20,90],[150,90]],[[20,130],[150,130]],[[150,50],[270,15]],[[150,90],[270,90]],[[150,130],[270,165]]],"lab":[[[150,168],"렌즈 ㉡"]],"oval":[[150,90,10,66]],"cap":"렌즈 ㉡을 지난 빛"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L05_challenge#10','sci',5,1,'u2','L05','g5_1_sci_u2_L05_challenge','lesson_challenge','SC5-1-u2-C18',4,'essay','teacher','빛의 직진, 반사, 굴절을 각각 한 문장으로 설명하고, 굴절이 일어나는 예를 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C18","difficulty":4,"kind":"essay","stem":"빛의 직진, 반사, 굴절을 각각 한 문장으로 설명하고, 굴절이 일어나는 예를 두 가지 쓰세요.","answer_guide":{"answer":"예: 빛의 직진은 빛이 곧게 나아가는 성질이다. 빛의 반사는 곧게 나아가던 빛이 거울에 부딪쳐 나아가는 방향이 바뀌는 성질이다. 빛의 굴절은 빛이 서로 다른 물질의 경계에서 꺾여 나아가는 성질이다. 굴절은 빛이 볼록 렌즈나 오목 렌즈를 통과할 때, 빛이 공기에서 물로 비스듬히 들어갈 때 일어난다.","scoring_points":["직진·반사·굴절을 바르게 설명했는가","굴절이 경계에서 꺾임임을 썼는가","굴절의 예 두 가지를 썼는가"]},"explanation":["세 성질을 차례로 떠올려요.","경계를 넣어요.","예 두 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#1','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C20',1,'mc','auto','물체의 크기를 다르게 보려면 무엇을 쓰는 것이 알맞은가요?',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C20","difficulty":1,"kind":"mc","stem":"물체의 크기를 다르게 보려면 무엇을 쓰는 것이 알맞은가요?","options":[{"t":"렌즈","correct":true},{"t":"평면거울","mis":"SC5-1-u2-X26"},{"t":"온도계","mis":"SC5-1-u2-X26"},{"t":"확성기","mis":"SC5-1-u2-X26"}],"explanation":["크기를 다르게 봐요.","돋보기를 떠올려요.","렌즈예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#2','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C19',1,'ox','auto','치과 거울로 입안의 잘 보이지 않는 부분을 볼 수 있어요.',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C19","difficulty":1,"kind":"ox","stem":"치과 거울로 입안의 잘 보이지 않는 부분을 볼 수 있어요.","answer":"O","reason_options":[{"t":"거울이 빛을 반사해 보이지 않던 곳을 보여 주기 때문에","correct":true},{"t":"치과 거울이 빛을 꺾어 이를 크게 보여 주기 때문에","mis":"SC5-1-u2-X26"}],"mis":"SC5-1-u2-X26","explanation":["치과 거울은 거울이에요.","거울은 반사해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#3','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C21',1,'sa','auto','「조사한 내용을 한 장에 하나의 예씩 □□□□에 글과 그림으로 나타냅니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u2-C21","difficulty":1,"kind":"sa","stem":"「조사한 내용을 한 장에 하나의 예씩 □□□□에 글과 그림으로 나타냅니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["붙임쪽지"],"explanation":["도화지에 붙여요.","네 글자예요.","붙임쪽지예요."],"mis":"SC5-1-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#4','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C19',1,'mc','auto','전등 갓이 전등 빛을 더 밝게 비추는 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X28']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C19","difficulty":1,"kind":"mc","stem":"전등 갓이 전등 빛을 더 밝게 비추는 까닭은 어느 것인가요?","options":[{"t":"갓 안쪽의 거울이 전등 빛을 반사하기 때문에","correct":true},{"t":"갓이 스스로 빛을 내기 때문에","mis":"SC5-1-u2-X28"},{"t":"갓이 전등을 따뜻하게 하기 때문에","mis":"SC5-1-u2-X28"},{"t":"갓이 빛을 끌어당기기 때문에","mis":"SC5-1-u2-X28"}],"explanation":["갓 안쪽을 떠올려요.","거울이 있어요.","반사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#5','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C19',2,'match','auto','기구와 쓰임새를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C19","difficulty":2,"kind":"match","stem":"기구와 쓰임새를 알맞게 이으세요.","pairs":[{"l":"돋보기안경","r":"작은 글씨를 크게 볼 수 있다"},{"l":"관찰용 확대경","r":"작은 곤충이나 식물의 잎을 관찰한다"},{"l":"치과 거울","r":"입안의 잘 보이지 않는 부분을 본다"},{"l":"전등 갓","r":"전등 빛을 반사해 더 밝게 비춘다"}],"mis":"SC5-1-u2-X26","explanation":["거울인지 렌즈인지 떠올려요.","크게 보기와 되비추기예요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#6','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C20',2,'mc','auto','멀리 있는 물체가 흐리게 보일 때 쓰는 안경은 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X27']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C20","difficulty":2,"kind":"mc","stem":"멀리 있는 물체가 흐리게 보일 때 쓰는 안경은 어느 것인가요?","options":[{"t":"오목 렌즈로 만든 안경","correct":true},{"t":"평면거울로 만든 안경","mis":"SC5-1-u2-X26"},{"t":"볼록 렌즈로 만든 관찰용 확대경","mis":"SC5-1-u2-X27"},{"t":"전등 갓을 붙인 안경","mis":"SC5-1-u2-X26"}],"explanation":["멀리 있는 것이 흐려요.","오목 렌즈를 떠올려요.","오목 렌즈 안경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#7','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C21',2,'mc','auto','거울과 렌즈의 예를 바르게 조사하는 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C21","difficulty":2,"kind":"mc","stem":"거울과 렌즈의 예를 바르게 조사하는 방법은 어느 것인가요?","options":[{"t":"신뢰할 수 있는 누리집에서 최신 자료를 찾는다","correct":true},{"t":"인터넷에서 본 그림을 그대로 가져다 붙인다","mis":"SC5-1-u2-X29"},{"t":"발표 자료를 한 사람이 혼자 다 만든다","mis":"SC5-1-u2-X29"},{"t":"한 장의 붙임쪽지에 예를 여러 개 쓴다","mis":"SC5-1-u2-X29"}],"explanation":["믿을 수 있는 자료예요.","새로운 자료예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#8','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C20',2,'ox','auto','렌즈는 모두 물체를 크게만 보여 줘요.',ARRAY['SC5-1-u2-X27']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C20","difficulty":2,"kind":"ox","stem":"렌즈는 모두 물체를 크게만 보여 줘요.","answer":"X","reason_options":[{"t":"렌즈로 물체를 크게 보거나 작게 볼 수 있기 때문에","correct":true},{"t":"렌즈는 크게 보는 데에만 쓰기 때문에","mis":"SC5-1-u2-X27"}],"mis":"SC5-1-u2-X27","explanation":["렌즈의 쓰임을 떠올려요.","작게도 보여요.","크게만은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#9','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C19',2,'mc','auto','자동차 뒷거울로 뒤에 있는 자동차를 보는 것은 빛의 어떤 성질을 이용한 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X19','SC5-1-u2-X28']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C19","difficulty":2,"kind":"mc","stem":"자동차 뒷거울로 뒤에 있는 자동차를 보는 것은 빛의 어떤 성질을 이용한 것인가요?","options":[{"t":"빛의 반사","correct":true},{"t":"빛의 굴절","mis":"SC5-1-u2-X26"},{"t":"빛이 소리로 바뀌는 성질","mis":"SC5-1-u2-X19"},{"t":"거울이 스스로 빛을 내는 성질","mis":"SC5-1-u2-X28"}],"explanation":["뒷거울은 거울이에요.","거울은 되비춰요.","반사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_basic#10','sci',5,1,'u2','L06','g5_1_sci_u2_L06_basic','lesson_basic','SC5-1-u2-C20',3,'mc','auto','사진기로 사진을 찍는 것에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X19','SC5-1-u2-X27']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C20","difficulty":3,"kind":"mc","stem":"사진기로 사진을 찍는 것에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"볼록 렌즈와 오목 렌즈가 들어 있어 빛의 굴절을 이용한다","correct":true},{"t":"거울만 들어 있어 빛의 반사를 이용한다","mis":"SC5-1-u2-X26"},{"t":"렌즈 없이 빛이 곧게 들어가기만 한다","mis":"SC5-1-u2-X19"},{"t":"사진기 속 렌즈는 모두 물체를 크게만 보여 준다","mis":"SC5-1-u2-X27"}],"explanation":["사진기 속을 떠올려요.","렌즈가 있어요.","굴절을 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#1','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C20',2,'sa','auto','「작은 곤충이나 식물의 잎을 관찰할 때 사용하는 관찰용 □□□」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C20","difficulty":2,"kind":"sa","stem":"「작은 곤충이나 식물의 잎을 관찰할 때 사용하는 관찰용 □□□」 □□□에 알맞은 말을 쓰세요.","answer":["확대경"],"explanation":["크게 보는 기구예요.","세 글자예요.","확대경이에요."],"mis":"SC5-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#2','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C19',2,'mc','auto','어느 물건에 거울을 붙이면 더 편리해질까요?',ARRAY['SC5-1-u2-X28']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C19","difficulty":2,"kind":"mc","stem":"어느 물건에 거울을 붙이면 더 편리해질까요?","options":[{"t":"가방 안쪽 — 밖에서도 얼굴을 확인할 수 있다","correct":true},{"t":"냉장고 안쪽 — 음식을 더 차갑게 할 수 있다","mis":"SC5-1-u2-X28"},{"t":"스피커 안쪽 — 소리를 더 크게 낼 수 있다","mis":"SC5-1-u2-X28"},{"t":"옷장 안쪽 — 옷을 더 따뜻하게 할 수 있다","mis":"SC5-1-u2-X28"}],"explanation":["거울이 하는 일이에요.","모습을 비춰요.","가방 안쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#3','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C21',3,'error','auto','발표 자료를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C21","difficulty":3,"kind":"error","stem":"발표 자료를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"우진 — 「인터넷에서 찾은 그림을 출처 없이 그대로 붙이자.」","correct":true,"mis_target":"SC5-1-u2-X29"},{"t":"채원 — 「한 장의 붙임쪽지에는 하나의 예만 쓰자.」","mis":"SC5-1-u2-X29"},{"t":"다은 — 「모둠원끼리 맡을 부분을 나누자.」","mis":"SC5-1-u2-X29"}],"explanation":["다른 사람의 창작물이에요.","허락 없이 쓰지 않아요.","우진이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#4','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C19',3,'mc','auto','거울과 렌즈의 쓰임을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C19","difficulty":3,"kind":"mc","stem":"거울과 렌즈의 쓰임을 바르게 말한 것은 어느 것인가요?","options":[{"t":"거울은 빛을 반사해 보이지 않던 곳을, 렌즈는 빛을 굴절시켜 크기를 다르게 보여 준다","correct":true},{"t":"거울은 빛을 굴절시켜 크게, 렌즈는 빛을 반사해 보이지 않던 곳을 보여 준다","mis":"SC5-1-u2-X26"},{"t":"거울과 렌즈 모두 빛을 반사한다","mis":"SC5-1-u2-X26"},{"t":"렌즈는 언제나 물체를 크게만 보여 준다","mis":"SC5-1-u2-X27"}],"explanation":["알아봐요를 떠올려요.","되비추고, 꺾어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#5','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C20',3,'ox','auto','수술할 때 볼록 렌즈로 만든 확대경으로 수술 부위를 크게 봐요.',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C20","difficulty":3,"kind":"ox","stem":"수술할 때 볼록 렌즈로 만든 확대경으로 수술 부위를 크게 봐요.","answer":"O","reason_options":[{"t":"볼록 렌즈가 빛을 굴절시켜 크게 보여 주기 때문에","correct":true},{"t":"확대경이 빛을 반사해 크게 보여 주기 때문에","mis":"SC5-1-u2-X26"}],"mis":"SC5-1-u2-X26","explanation":["확대경은 렌즈예요.","렌즈는 굴절이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#6','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C19',3,'mc','auto','신발 가게에 거울이 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X28','SC5-1-u2-X26']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C19","difficulty":3,"kind":"mc","stem":"신발 가게에 거울이 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"신발을 신은 모습을 볼 수 있게 하려고","correct":true},{"t":"발을 따뜻하게 하려고","mis":"SC5-1-u2-X28"},{"t":"신발을 크게 보이게 하려고","mis":"SC5-1-u2-X26"},{"t":"빛을 꺾어 발을 작아 보이게 하려고","mis":"SC5-1-u2-X26"}],"explanation":["거울로 무엇을 보나요?","내 모습이에요.","신은 모습을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#7','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C21',3,'mc','auto','다른 모둠의 발표를 들을 때 가장 중요하게 살펴볼 것은 어느 것인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C21","difficulty":3,"kind":"mc","stem":"다른 모둠의 발표를 들을 때 가장 중요하게 살펴볼 것은 어느 것인가요?","options":[{"t":"거울과 렌즈의 쓰임새를 정확하게 조사했는지","correct":true},{"t":"붙임쪽지의 색깔이 예쁜지","mis":"SC5-1-u2-X29"},{"t":"붙임쪽지를 가장 많이 붙였는지","mis":"SC5-1-u2-X29"},{"t":"발표를 가장 빨리 끝냈는지","mis":"SC5-1-u2-X29"}],"explanation":["조사의 목적이에요.","쓰임새예요.","정확한지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#8','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C19',4,'mc','auto','붙임쪽지 가운데 이용한 빛의 성질을 잘못 적은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C19","difficulty":4,"kind":"mc","stem":"붙임쪽지 가운데 이용한 빛의 성질을 잘못 적은 것은 어느 것인가요?","options":[{"t":"③ 전등 갓","correct":true},{"t":"① 치과 거울","mis":"SC5-1-u2-X26"},{"t":"② 돋보기안경","mis":"SC5-1-u2-X26"},{"t":"④ 사진기","mis":"SC5-1-u2-X26"}],"explanation":["거울인지 렌즈인지 봐요.","전등 갓 안쪽은 거울이에요.","③을 반사로 고쳐요."],"asset":{"type":"passage","lines":["① 치과 거울 — 입안의 잘 보이지 않는 곳을 본다. (반사)","② 돋보기안경 — 작은 글씨를 크게 본다. (굴절)","③ 전등 갓 — 안쪽 거울로 전등 빛을 더 밝게 한다. (굴절)","④ 사진기 — 렌즈가 들어 있어 사진을 찍는다. (굴절)"],"title":"우리 모둠 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#9','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C20',4,'mc','auto','할머니는 작은 글씨를 읽기 어렵고, 친구는 멀리 있는 칠판 글씨가 흐리게 보여요. 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X27']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C20","difficulty":4,"kind":"mc","stem":"할머니는 작은 글씨를 읽기 어렵고, 친구는 멀리 있는 칠판 글씨가 흐리게 보여요. 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"할머니 — 돋보기안경, 친구 — 오목 렌즈로 만든 안경","correct":true},{"t":"할머니 — 오목 렌즈로 만든 안경, 친구 — 돋보기안경","mis":"SC5-1-u2-X26"},{"t":"두 사람 모두 평면거울로 만든 안경","mis":"SC5-1-u2-X26"},{"t":"두 사람 모두 물체를 크게만 보여 주는 렌즈","mis":"SC5-1-u2-X27"}],"explanation":["작은 글씨는 크게 봐요.","멀리 흐리면 오목 렌즈예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L06_challenge#10','sci',5,1,'u2','L06','g5_1_sci_u2_L06_challenge','lesson_challenge','SC5-1-u2-C21',4,'essay','teacher','생활 속에서 거울을 이용하는 예와 렌즈를 이용하는 예를 하나씩 쓰고 각각 이용한 빛의 성질을 쓰세요. 그리고 조사하고 발표할 때 지킬 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C21","difficulty":4,"kind":"essay","stem":"생활 속에서 거울을 이용하는 예와 렌즈를 이용하는 예를 하나씩 쓰고 각각 이용한 빛의 성질을 쓰세요. 그리고 조사하고 발표할 때 지킬 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 자동차 뒷거울은 빛의 반사를 이용해 뒤에 있는 자동차를 볼 수 있게 한다. 돋보기안경은 빛의 굴절을 이용해 작은 글씨를 크게 볼 수 있게 한다. 조사할 때에는 신뢰할 수 있는 누리집에서 최신 자료를 찾고, 다른 사람의 창작물을 허락 없이 쓰지 않는다.","scoring_points":["거울의 예와 반사를 썼는가","렌즈의 예와 굴절을 썼는가","지킬 점을 썼는가"]},"explanation":["주변을 떠올려요.","거울과 렌즈를 나눠요.","지킬 점도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#1','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C22',1,'mc','auto','거울 미로 체험장에서 길을 찾기 어려운 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X30','SC5-1-u2-X11']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C22","difficulty":1,"kind":"mc","stem":"거울 미로 체험장에서 길을 찾기 어려운 까닭은 어느 것인가요?","options":[{"t":"내 모습과 길이 주위의 거울에 반사되어 보이기 때문에","correct":true},{"t":"거울이 빛을 모두 흡수해 어두워지기 때문에","mis":"SC5-1-u2-X30"},{"t":"거울이 빛을 꺾어 길을 크게 보여 주기 때문에","mis":"SC5-1-u2-X30"},{"t":"거울이 빛을 빙글빙글 돌게 하기 때문에","mis":"SC5-1-u2-X11"}],"explanation":["거울로 벽을 만들었어요.","여러 곳에 비쳐요.","반사 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#2','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C23',1,'ox','auto','장치를 만들 때 거울이나 렌즈가 깨지지 않도록 조심해요.',ARRAY['SC5-1-u2-X33']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C23","difficulty":1,"kind":"ox","stem":"장치를 만들 때 거울이나 렌즈가 깨지지 않도록 조심해요.","answer":"O","reason_options":[{"t":"깨진 조각에 다칠 수 있기 때문에","correct":true},{"t":"깨지면 빛의 성질이 바뀌기 때문에","mis":"SC5-1-u2-X33"}],"mis":"SC5-1-u2-X33","explanation":["안전을 떠올려요.","깨지면 위험해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#3','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C23',1,'sa','auto','「어두운 종이 상자에 볼록 렌즈를 끼워 화면을 크게 비추는 간이 □□□□를 만들 수 있습니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u2-C23","difficulty":1,"kind":"sa","stem":"「어두운 종이 상자에 볼록 렌즈를 끼워 화면을 크게 비추는 간이 □□□□를 만들 수 있습니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["프로젝터"],"explanation":["화면을 벽에 비춰요.","네 글자예요.","프로젝터예요."],"mis":"SC5-1-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#4','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C23',1,'mc','auto','장치를 만들기 전에 먼저 정해야 할 것은 어느 것인가요?',ARRAY['SC5-1-u2-X32']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C23","difficulty":1,"kind":"mc","stem":"장치를 만들기 전에 먼저 정해야 할 것은 어느 것인가요?","options":[{"t":"거울과 렌즈 가운데 무엇의 어떤 성질을 이용할지","correct":true},{"t":"가장 비싼 재료를 무엇으로 할지","mis":"SC5-1-u2-X32"},{"t":"장치를 얼마나 크게 만들지","mis":"SC5-1-u2-X32"},{"t":"장치를 무슨 색으로 칠할지","mis":"SC5-1-u2-X32"}],"explanation":["가장 중요한 것은?","성질이에요.","이용할 성질을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#5','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C22',2,'match','auto','만드는 과정과 그렇게 하는 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C22","difficulty":2,"kind":"match","stem":"만드는 과정과 그렇게 하는 까닭을 알맞게 이으세요.","pairs":[{"l":"도화지에 피자 한 조각을 그린다","r":"거울에 비칠 원래 그림이 있어야 한다"},{"l":"거울 두 개를 셀로판테이프로 붙인다","r":"두 거울의 각도를 조절할 수 있게 한다"},{"l":"종이 상자에 볼록 렌즈를 끼운다","r":"빛이 렌즈를 지나며 꺾이게 한다"},{"l":"어두운 종이 상자의 뚜껑을 닫는다","r":"다른 빛이 들어오지 않게 한다"}],"mis":"SC5-1-u2-X34","explanation":["까닭을 하나씩 떠올려요.","그림·각도·꺾임·어둠이에요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#6','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C23',2,'mc','auto','간이 프로젝터에서 볼록 렌즈가 하는 일은 어느 것인가요?',ARRAY['SC5-1-u2-X31','SC5-1-u2-X28']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C23","difficulty":2,"kind":"mc","stem":"간이 프로젝터에서 볼록 렌즈가 하는 일은 어느 것인가요?","options":[{"t":"빛을 굴절시켜 화면을 크게 비춰 준다","correct":true},{"t":"빛을 반사해 화면을 되비춰 준다","mis":"SC5-1-u2-X31"},{"t":"화면의 소리를 크게 만들어 준다","mis":"SC5-1-u2-X31"},{"t":"스마트 기기를 따뜻하게 해 준다","mis":"SC5-1-u2-X28"}],"explanation":["볼록 렌즈는 꺾어요.","화면이 커져요.","굴절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#7','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C22',2,'ox','auto','거울 미로는 빛이 굴절되어 길이 헷갈리는 장치예요.',ARRAY['SC5-1-u2-X30']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C22","difficulty":2,"kind":"ox","stem":"거울 미로는 빛이 굴절되어 길이 헷갈리는 장치예요.","answer":"X","reason_options":[{"t":"거울에 빛이 반사되어 내 모습과 길이 여러 곳에 보이기 때문에","correct":true},{"t":"거울이 빛을 꺾어 길이 휘어 보이기 때문에","mis":"SC5-1-u2-X30"}],"mis":"SC5-1-u2-X30","explanation":["거울이 하는 일이에요.","반사예요.","굴절이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#8','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C22',2,'mc','auto','피자 한 조각이 한 판으로 보이게 하려면 어떻게 해야 하나요?',ARRAY['SC5-1-u2-X34']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C22","difficulty":2,"kind":"mc","stem":"피자 한 조각이 한 판으로 보이게 하려면 어떻게 해야 하나요?","options":[{"t":"거울 두 개의 각도를 조절해 본다","correct":true},{"t":"피자 조각을 더 크게 그린다","mis":"SC5-1-u2-X34"},{"t":"방을 더 밝게 만든다","mis":"SC5-1-u2-X34"},{"t":"도화지를 여러 장 겹쳐 놓는다","mis":"SC5-1-u2-X34"}],"explanation":["거울 두 개를 붙였어요.","각도가 중요해요.","각도를 조절해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#9','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C23',2,'mc','auto','장치를 만들 때 바른 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X33','SC5-1-u2-X32']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C23","difficulty":2,"kind":"mc","stem":"장치를 만들 때 바른 방법은 어느 것인가요?","options":[{"t":"활동이 끝나면 주변을 정리하고 폐기물을 올바르게 처리한다","correct":true},{"t":"깨진 거울 조각을 맨손으로 잡아 붙인다","mis":"SC5-1-u2-X33"},{"t":"남은 재료를 아무 데나 버린다","mis":"SC5-1-u2-X33"},{"t":"다른 모둠 장치의 흠만 찾아 말한다","mis":"SC5-1-u2-X32"}],"explanation":["끝난 뒤를 떠올려요.","정리해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_basic#10','sci',5,1,'u2','L07','g5_1_sci_u2_L07_basic','lesson_basic','SC5-1-u2-C23',3,'mc','auto','간이 프로젝터 상자의 뚜껑을 활짝 열어 둔 설계는 어떤 점을 고쳐야 할까요?',ARRAY['SC5-1-u2-X31','SC5-1-u2-X32']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C23","difficulty":3,"kind":"mc","stem":"간이 프로젝터 상자의 뚜껑을 활짝 열어 둔 설계는 어떤 점을 고쳐야 할까요?","options":[{"t":"다른 빛이 들어와 화면이 잘 보이지 않으니 뚜껑을 닫아야 한다","correct":true},{"t":"고칠 것이 없다 — 뚜껑은 상관없다","mis":"SC5-1-u2-X31"},{"t":"뚜껑을 열면 볼록 렌즈가 빛을 반사하지 못한다","mis":"SC5-1-u2-X31"},{"t":"뚜껑을 열면 상자가 너무 커진다","mis":"SC5-1-u2-X32"}],"explanation":["어두운 상자였어요.","다른 빛이 들어와요.","뚜껑을 닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#1','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C22',2,'sa','auto','「거울로 벽을 만들어 내 모습과 길이 주위의 거울에 반사되어 보이는 거울 □□ 체험장」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C22","difficulty":2,"kind":"sa","stem":"「거울로 벽을 만들어 내 모습과 길이 주위의 거울에 반사되어 보이는 거울 □□ 체험장」 □□에 알맞은 말을 쓰세요.","answer":["미로"],"explanation":["길을 찾는 곳이에요.","두 글자예요.","미로예요."],"mis":"SC5-1-u2-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#2','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C23',2,'mc','auto','장치를 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X32']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C23","difficulty":2,"kind":"mc","stem":"장치를 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉤ → ㉠ → ㉣","correct":true},{"t":"㉤ → ㉡ → ㉢ → ㉣ → ㉠","mis":"SC5-1-u2-X32"},{"t":"㉢ → ㉤ → ㉡ → ㉠ → ㉣","mis":"SC5-1-u2-X32"},{"t":"㉡ → ㉤ → ㉢ → ㉣ → ㉠","mis":"SC5-1-u2-X32"}],"explanation":["먼저 그림과 글로 계획해요.","만든 다음 소개해요.","잘한 점은 마지막이에요."],"asset":{"type":"passage","lines":["㉠ 만든 장치를 친구들에게 소개한다.","㉡ 만들고 싶은 장치를 그림과 글로 나타낸다.","㉢ 필요한 재료를 정하고 준비한다.","㉣ 다른 모둠 장치에서 잘한 점을 이야기한다.","㉤ 거울이나 렌즈를 이용해 장치를 만든다."],"title":"장치 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#3','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C23',3,'error','auto','장치를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X32']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C23","difficulty":3,"kind":"error","stem":"장치를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「장치는 크고 비싸게 만들수록 좋은 장치야.」","correct":true,"mis_target":"SC5-1-u2-X32"},{"t":"가은 — 「만들기 전에 어떤 성질을 쓸지 정하자.」","mis":"SC5-1-u2-X32"},{"t":"로하 — 「다른 모둠의 잘한 점을 찾아 칭찬하자.」","mis":"SC5-1-u2-X32"}],"explanation":["무엇이 더 중요할까요?","성질을 옳게 이용하는 것이에요.","태윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#4','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C22',3,'mc','auto','거울 미로를 만들면서 거울 대신 투명한 유리판을 붙여 벽을 만들었어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['SC5-1-u2-X30','SC5-1-u2-X32']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C22","difficulty":3,"kind":"mc","stem":"거울 미로를 만들면서 거울 대신 투명한 유리판을 붙여 벽을 만들었어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"고쳐야 한다 — 투명한 유리판으로는 내 모습과 길이 거울처럼 비치지 않는다","correct":true},{"t":"그대로 둔다 — 유리판이 거울보다 빛을 더 잘 반사한다","mis":"SC5-1-u2-X30"},{"t":"그대로 둔다 — 유리판이 빛을 꺾어 길이 크게 보인다","mis":"SC5-1-u2-X30"},{"t":"그대로 둔다 — 재료가 달라도 성질은 상관없다","mis":"SC5-1-u2-X32"}],"explanation":["거울 미로의 비밀은 반사예요.","유리판은 투명해요.","고쳐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#5','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C22',3,'ox','auto','거울 두 개를 각도가 움직이게 붙인 것은 고칠 필요가 없어요.',ARRAY['SC5-1-u2-X34']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C22","difficulty":3,"kind":"ox","stem":"거울 두 개를 각도가 움직이게 붙인 것은 고칠 필요가 없어요.","answer":"O","reason_options":[{"t":"각도를 조절해야 피자 조각이 한 판으로 보이게 할 수 있기 때문에","correct":true},{"t":"각도는 장치에 아무 영향이 없기 때문에","mis":"SC5-1-u2-X34"}],"mis":"SC5-1-u2-X34","explanation":["각도를 왜 움직이게 했나요?","한 판으로 보이게 해요.","그대로 두어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#6','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C22',3,'mc','auto','장치와 이용한 것을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X31','SC5-1-u2-X30']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C22","difficulty":3,"kind":"mc","stem":"장치와 이용한 것을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"피자 한 판 장치 — 거울, 간이 프로젝터 — 볼록 렌즈","correct":true},{"t":"피자 한 판 장치 — 볼록 렌즈, 간이 프로젝터 — 거울","mis":"SC5-1-u2-X31"},{"t":"두 장치 모두 거울","mis":"SC5-1-u2-X31"},{"t":"두 장치 모두 렌즈","mis":"SC5-1-u2-X30"}],"explanation":["되비추는 장치와 꺾는 장치예요.","피자는 거울이에요.","프로젝터는 렌즈예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#7','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C23',3,'mc','auto','친구의 장치 발표를 들을 때 가장 중요하게 살펴볼 것은 어느 것인가요?',ARRAY['SC5-1-u2-X32']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C23","difficulty":3,"kind":"mc","stem":"친구의 장치 발표를 들을 때 가장 중요하게 살펴볼 것은 어느 것인가요?","options":[{"t":"거울이나 렌즈의 성질을 어떻게 이용했는지","correct":true},{"t":"장치가 얼마나 멋지게 보이는지","mis":"SC5-1-u2-X32"},{"t":"장치가 얼마나 큰지","mis":"SC5-1-u2-X32"},{"t":"재료가 얼마나 비싼지","mis":"SC5-1-u2-X32"}],"explanation":["나누어요를 떠올려요.","성질이 중요해요.","어떻게 이용했는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#8','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C22',4,'mc','auto','키가 작은 동생이 담장 너머를 볼 수 있는 장치를 만들려고 해요. 가장 알맞은 설계는 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X03','SC5-1-u2-X32']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C22","difficulty":4,"kind":"mc","stem":"키가 작은 동생이 담장 너머를 볼 수 있는 장치를 만들려고 해요. 가장 알맞은 설계는 어느 것인가요?","options":[{"t":"거울 두 개의 각도를 맞추어 담장 너머의 빛이 반사되어 동생 눈에 들어오게 한다","correct":true},{"t":"볼록 렌즈 하나로 담장 너머의 빛을 끌어당긴다","mis":"SC5-1-u2-X26"},{"t":"담장 앞에서 손전등을 동생 눈에 비춘다","mis":"SC5-1-u2-X03"},{"t":"거울을 아무렇게나 많이 붙일수록 잘 보인다","mis":"SC5-1-u2-X32"}],"explanation":["빛의 방향을 바꿔야 해요.","거울은 방향을 바꿔요.","두 거울의 각도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#9','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C23',4,'mc','auto','간이 프로젝터의 화면에 바깥 빛이 섞여 흐리게 보여요. 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u2-X31','SC5-1-u2-X32']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C23","difficulty":4,"kind":"mc","stem":"간이 프로젝터의 화면에 바깥 빛이 섞여 흐리게 보여요. 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"상자 뚜껑을 닫고 방을 어둡게 한다","correct":true},{"t":"볼록 렌즈를 빼고 구멍만 남긴다","mis":"SC5-1-u2-X31"},{"t":"방을 더 밝게 한다","mis":"SC5-1-u2-X31"},{"t":"상자를 더 크고 화려하게 꾸민다","mis":"SC5-1-u2-X32"}],"explanation":["바깥 빛이 문제예요.","어둡게 해야 해요.","뚜껑을 닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L07_challenge#10','sci',5,1,'u2','L07','g5_1_sci_u2_L07_challenge','lesson_challenge','SC5-1-u2-C23',4,'essay','teacher','거울이나 렌즈를 이용해 만들고 싶은 장치를 하나 정하여, 무엇을 이용하는지, 이용한 빛의 성질과 그 성질을 어디에 쓰는지, 만들 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C23","difficulty":4,"kind":"essay","stem":"거울이나 렌즈를 이용해 만들고 싶은 장치를 하나 정하여, 무엇을 이용하는지, 이용한 빛의 성질과 그 성질을 어디에 쓰는지, 만들 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 볼록 렌즈로 간이 프로젝터를 만들고 싶다. 구멍이 뚫린 어두운 종이 상자에 볼록 렌즈를 끼우고 스마트 기기를 세워 고정한 뒤 뚜껑을 닫는다. 볼록 렌즈가 빛을 굴절시켜 스마트 기기의 화면을 벽에 크게 비춘다. 만들 때에는 렌즈가 깨지지 않도록 조심하고, 끝나면 주변을 정리한다.","scoring_points":["이용할 것과 장치를 정했는가","빛의 성질과 쓰는 곳을 이어 썼는가","지킬 점을 썼는가"]},"explanation":["거울이나 렌즈를 골라요.","성질을 이어요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#1','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C24',1,'mc','auto','라이파이는 무엇을 이용해 통신하나요?',ARRAY['SC5-1-u2-X35']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C24","difficulty":1,"kind":"mc","stem":"라이파이는 무엇을 이용해 통신하나요?","options":[{"t":"LED 등의 빛","correct":true},{"t":"크게 울리는 소리","mis":"SC5-1-u2-X35"},{"t":"빠르게 부는 바람","mis":"SC5-1-u2-X35"},{"t":"자석이 끌어당기는 힘","mis":"SC5-1-u2-X35"}],"explanation":["이름에 힌트가 있어요.","빛을 써요.","LED 등의 빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#2','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C25',1,'ox','auto','빛이 통과하지 못하는 장애물이 있으면 라이파이 통신이 끊길 수 있어요.',ARRAY['SC5-1-u2-X36']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C25","difficulty":1,"kind":"ox","stem":"빛이 통과하지 못하는 장애물이 있으면 라이파이 통신이 끊길 수 있어요.","answer":"O","reason_options":[{"t":"빛이 곧게 나아가다 장애물에 막혀 기기에 닿지 못하기 때문에","correct":true},{"t":"장애물이 빛을 돌려 보내 더 세게 하기 때문에","mis":"SC5-1-u2-X36"}],"mis":"SC5-1-u2-X36","explanation":["빛은 막히면 어떻게 되나요?","기기에 닿지 못해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#3','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C24',1,'sa','auto','「빛을 사용해 와이파이보다 빠르면서 편리하게 통신하는 기술을 □□□□라고 합니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u2-C24","difficulty":1,"kind":"sa","stem":"「빛을 사용해 와이파이보다 빠르면서 편리하게 통신하는 기술을 □□□□라고 합니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["라이파이"],"explanation":["빛으로 하는 통신이에요.","네 글자예요.","라이파이예요."],"mis":"SC5-1-u2-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#4','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C25',1,'mc','auto','라이파이를 쓰는데 빛이 통과하지 못하는 장애물이 있으면 어떻게 되나요?',ARRAY['SC5-1-u2-X36','SC5-1-u2-X35','SC5-1-u2-X13']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C25","difficulty":1,"kind":"mc","stem":"라이파이를 쓰는데 빛이 통과하지 못하는 장애물이 있으면 어떻게 되나요?","options":[{"t":"통신이 끊길 수 있다","correct":true},{"t":"통신 속도가 오히려 더 빨라진다","mis":"SC5-1-u2-X36"},{"t":"빛 대신 소리로 바뀌어 통신한다","mis":"SC5-1-u2-X35"},{"t":"빛이 장애물을 돌아서 지나간다","mis":"SC5-1-u2-X13"}],"explanation":["빛은 막혀요.","정보가 닿지 않아요.","끊길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#5','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C26',2,'match','auto','말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u2-C26","difficulty":2,"kind":"match","stem":"말과 뜻을 알맞게 이으세요.","pairs":[{"l":"와이파이","r":"우리가 인터넷이나 통신을 할 때 쓰는 기술"},{"l":"라이파이","r":"빛을 사용해 빠르고 편리하게 통신하는 기술"},{"l":"세계 표준 방식","r":"여러 나라가 함께 쓰기로 정한 방식"},{"l":"광통신 연구원","r":"빛을 이용한 통신망을 연구하는 사람"}],"mis":"SC5-1-u2-X38","explanation":["하나씩 떠올려요.","지금 기술·빛 기술·약속·직업이에요.","네 가지를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#6','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C25',2,'mc','auto','라이파이가 보안에 유리한 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X37']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C25","difficulty":2,"kind":"mc","stem":"라이파이가 보안에 유리한 까닭은 어느 것인가요?","options":[{"t":"빛을 가리면 다른 사람이 통신 내용을 알 수 없기 때문에","correct":true},{"t":"통신할 때마다 새 비밀번호가 만들어지기 때문에","mis":"SC5-1-u2-X37"},{"t":"통신 속도가 너무 빨라 아무도 따라올 수 없기 때문에","mis":"SC5-1-u2-X37"},{"t":"빛이 벽을 뚫고 멀리까지 나아가기 때문에","mis":"SC5-1-u2-X37"}],"explanation":["빛을 가리면 어떻게 될까요?","밖으로 나가지 않아요.","알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#7','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C24',2,'ox','auto','라이파이는 우리가 현재 쓰고 있는 LED 등을 이용해 통신해요.',ARRAY['SC5-1-u2-X35']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C24","difficulty":2,"kind":"ox","stem":"라이파이는 우리가 현재 쓰고 있는 LED 등을 이용해 통신해요.","answer":"O","reason_options":[{"t":"따로 장치를 달지 않고 지금 쓰는 등의 빛을 그대로 이용하기 때문에","correct":true},{"t":"라이파이는 소리를 내는 스피커를 이용하기 때문에","mis":"SC5-1-u2-X35"}],"mis":"SC5-1-u2-X35","explanation":["통신 과정 ①을 떠올려요.","LED 등이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#8','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C25',2,'mc','auto','라이파이를 쓰기 어려운 곳은 어느 것인가요?',ARRAY['SC5-1-u2-X36']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C25","difficulty":2,"kind":"mc","stem":"라이파이를 쓰기 어려운 곳은 어느 것인가요?","options":[{"t":"불이 꺼진 캄캄한 창고 안","correct":true},{"t":"LED 등이 환하게 켜진 교실","mis":"SC5-1-u2-X36"},{"t":"조명이 밝게 켜진 도서관","mis":"SC5-1-u2-X36"},{"t":"LED 등이 켜진 거실","mis":"SC5-1-u2-X36"}],"explanation":["빛이 있어야 해요.","빛이 없는 곳을 찾아요.","캄캄한 창고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#9','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C24',2,'mc','auto','LED 등은 어떻게 정보를 실어 보내나요?',ARRAY['SC5-1-u2-X35']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C24","difficulty":2,"kind":"mc","stem":"LED 등은 어떻게 정보를 실어 보내나요?","options":[{"t":"빛이 아주 빠르게 깜박이며 정보를 실어 보낸다","correct":true},{"t":"등에서 소리가 나며 정보를 보낸다","mis":"SC5-1-u2-X35"},{"t":"등이 뜨거워지며 정보를 보낸다","mis":"SC5-1-u2-X35"},{"t":"사람이 눈으로 읽을 수 있게 천천히 깜박인다","mis":"SC5-1-u2-X35"}],"explanation":["통신 과정 ②예요.","아주 빨라요.","빠르게 깜박여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_basic#10','sci',5,1,'u2','L08','g5_1_sci_u2_L08_basic','lesson_basic','SC5-1-u2-C24',3,'mc','auto','1차시의 손전등 모스 부호와 라이파이의 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X35','SC5-1-u2-X36']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C24","difficulty":3,"kind":"mc","stem":"1차시의 손전등 모스 부호와 라이파이의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"빛을 켰다 껐다 하는 신호로 정보를 전한다","correct":true},{"t":"둘 다 소리로 정보를 전한다","mis":"SC5-1-u2-X35"},{"t":"라이파이는 빛이 없어도 정보를 전한다","mis":"SC5-1-u2-X36"},{"t":"둘 다 사람이 눈으로 하나하나 읽어야 한다","mis":"SC5-1-u2-X35"}],"explanation":["이어 봐요를 떠올려요.","빛 신호예요.","깜박이는 빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#1','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C26',2,'sa','auto','「빛을 이용한 통신망을 연구하는 □□□ 연구원」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u2-C26","difficulty":2,"kind":"sa","stem":"「빛을 이용한 통신망을 연구하는 □□□ 연구원」 □□□에 알맞은 말을 쓰세요.","answer":["광통신"],"explanation":["빛으로 하는 통신이에요.","세 글자예요.","광통신이에요."],"mis":"SC5-1-u2-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#2','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C25',2,'mc','auto','라이파이의 좋은 점은 어느 것인가요?',ARRAY['SC5-1-u2-X39','SC5-1-u2-X36']::text[],false,'{"seq":2,"concept":"SC5-1-u2-C25","difficulty":2,"kind":"mc","stem":"라이파이의 좋은 점은 어느 것인가요?","options":[{"t":"LED 등의 빛이 있는 곳이라면 어디에서든 빠른 인터넷을 쓸 수 있다","correct":true},{"t":"빛이 통과하지 못하는 장애물이 있으면 통신이 끊긴다","mis":"SC5-1-u2-X39"},{"t":"빛이 닿지 않는 곳에서는 사용이 어렵다","mis":"SC5-1-u2-X39"},{"t":"빛이 전혀 없는 곳에서도 잘 쓸 수 있다","mis":"SC5-1-u2-X36"}],"explanation":["좋은 점과 아쉬운 점을 나눠요.","어디서든 빨라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#3','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C25',3,'error','auto','라이파이에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u2-X36','SC5-1-u2-X37']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C25","difficulty":3,"kind":"error","stem":"라이파이에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「라이파이는 빛이 전혀 없는 곳에서도 잘 쓸 수 있어.」","correct":true,"mis_target":"SC5-1-u2-X36"},{"t":"하람 — 「빛을 가리면 통신 내용을 알 수 없어.」","mis":"SC5-1-u2-X37"},{"t":"윤재 — 「장애물이 있으면 끊길 수 있어.」","mis":"SC5-1-u2-X36"}],"explanation":["무엇으로 통신하나요?","빛이 있어야 해요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#4','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C26',3,'mc','auto','광통신 연구원이나 무선 통신 연구원에게 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X38','SC5-1-u2-X35']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C26","difficulty":3,"kind":"mc","stem":"광통신 연구원이나 무선 통신 연구원에게 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"기존의 통신 방식과 빛의 성질에 관한 이해","correct":true},{"t":"빛의 성질은 몰라도 된다","mis":"SC5-1-u2-X38"},{"t":"소리의 크기만 알면 된다","mis":"SC5-1-u2-X35"},{"t":"이미 완성된 기술이라 연구할 것이 없다","mis":"SC5-1-u2-X38"}],"explanation":["빛으로 통신해요.","빛의 성질이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#5','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C26',3,'ox','auto','라이파이는 이미 완성되어 더 연구할 것이 없어요.',ARRAY['SC5-1-u2-X38']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C26","difficulty":3,"kind":"ox","stem":"라이파이는 이미 완성되어 더 연구할 것이 없어요.","answer":"X","reason_options":[{"t":"더 안정적인 통신이 되도록 많은 나라에서 계속 연구하고 있기 때문에","correct":true},{"t":"세계 표준 방식이 정해졌으니 모든 연구가 끝났기 때문에","mis":"SC5-1-u2-X38"}],"mis":"SC5-1-u2-X38","explanation":["세계 표준이 정해졌어요.","그래서 많이 연구해요.","아직 발전 중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#6','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C25',3,'mc','auto','두꺼운 벽으로 막힌 옆방에서 라이파이를 쓰기 어려운 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X37','SC5-1-u2-X13','SC5-1-u2-X36']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C25","difficulty":3,"kind":"mc","stem":"두꺼운 벽으로 막힌 옆방에서 라이파이를 쓰기 어려운 까닭은 어느 것인가요?","options":[{"t":"빛이 벽을 통과하지 못해 옆방의 기기까지 닿지 못하기 때문에","correct":true},{"t":"빛이 벽을 뚫고 지나가 섞이기 때문에","mis":"SC5-1-u2-X37"},{"t":"빛이 벽을 돌아서 지나가 늦어지기 때문에","mis":"SC5-1-u2-X13"},{"t":"옆방은 언제나 빛이 너무 밝기 때문에","mis":"SC5-1-u2-X36"}],"explanation":["빛은 막히면 못 가요.","벽은 장애물이에요.","닿지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#7','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C24',3,'mc','auto','통신 과정 ③에서 기기가 정보를 읽으려면 무엇이 필요한가요?',ARRAY['SC5-1-u2-X35','SC5-1-u2-X28','SC5-1-u2-X36']::text[],false,'{"seq":7,"concept":"SC5-1-u2-C24","difficulty":3,"kind":"mc","stem":"통신 과정 ③에서 기기가 정보를 읽으려면 무엇이 필요한가요?","options":[{"t":"LED 등의 빛이 곧게 나아가 기기까지 닿아야 한다","correct":true},{"t":"기기가 큰 소리를 내야 한다","mis":"SC5-1-u2-X35"},{"t":"기기가 스스로 빛을 내야 한다","mis":"SC5-1-u2-X28"},{"t":"빛이 기기에 닿지 않아야 한다","mis":"SC5-1-u2-X36"}],"explanation":["빛이 정보를 실어요.","기기까지 와야 해요.","닿아야 해요."],"asset":{"type":"passage","lines":["① 우리가 지금 쓰고 있는 LED 등에 불이 켜진다.","② LED 등의 빛이 아주 빠르게 깜박이며 정보를 실어 보낸다.","③ 기기가 그 빛을 받아 정보를 읽어 낸다."],"title":"라이파이로 통신하는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#8','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C25',4,'mc','auto','도서관에서 라이파이로 노트북을 쓰는데 높은 책장이 LED 등과 노트북 사이를 가려 통신이 끊겼어요. 가장 알맞은 해결은 어느 것인가요?',ARRAY['SC5-1-u2-X36','SC5-1-u2-X37','SC5-1-u2-X35']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C25","difficulty":4,"kind":"mc","stem":"도서관에서 라이파이로 노트북을 쓰는데 높은 책장이 LED 등과 노트북 사이를 가려 통신이 끊겼어요. 가장 알맞은 해결은 어느 것인가요?","options":[{"t":"노트북을 LED 등의 빛이 바로 닿는 자리로 옮긴다","correct":true},{"t":"책장을 더 높게 쌓는다","mis":"SC5-1-u2-X36"},{"t":"보안을 위해 LED 등을 끈다","mis":"SC5-1-u2-X37"},{"t":"노트북 소리를 크게 키운다","mis":"SC5-1-u2-X35"}],"explanation":["왜 끊겼나요?","빛이 가려졌어요.","빛이 닿는 곳으로 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#9','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C25',4,'mc','auto','회의실에서 라이파이를 쓰며 창문을 커튼으로 가렸더니 밖에 있는 사람은 통신 내용을 알 수 없었어요. 그 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X37','SC5-1-u2-X35']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C25","difficulty":4,"kind":"mc","stem":"회의실에서 라이파이를 쓰며 창문을 커튼으로 가렸더니 밖에 있는 사람은 통신 내용을 알 수 없었어요. 그 까닭은 어느 것인가요?","options":[{"t":"빛이 커튼에 막혀 회의실 밖으로 나가지 못했기 때문에","correct":true},{"t":"커튼이 비밀번호를 만들어 주었기 때문에","mis":"SC5-1-u2-X37"},{"t":"빛이 커튼을 뚫고 나가 다른 빛과 섞였기 때문에","mis":"SC5-1-u2-X37"},{"t":"커튼이 빛을 소리로 바꾸었기 때문에","mis":"SC5-1-u2-X35"}],"explanation":["보안에 유리한 까닭이에요.","빛을 가렸어요.","밖으로 못 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_L08_challenge#10','sci',5,1,'u2','L08','g5_1_sci_u2_L08_challenge','lesson_challenge','SC5-1-u2-C25',4,'essay','teacher','라이파이의 좋은 점을 두 가지, 아쉬운 점을 한 가지 쓰고, 아쉬운 점이 생기는 까닭을 빛이 나아가는 성질과 이어서 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u2-C25","difficulty":4,"kind":"essay","stem":"라이파이의 좋은 점을 두 가지, 아쉬운 점을 한 가지 쓰고, 아쉬운 점이 생기는 까닭을 빛이 나아가는 성질과 이어서 설명하세요.","answer_guide":{"answer":"예: 라이파이는 LED 등의 빛이 있는 곳이라면 어디에서든 빠른 인터넷을 쓸 수 있고, 빛을 가리면 다른 사람이 통신 내용을 알 수 없어 보안에도 유리하다. 하지만 빛이 통과하지 못하는 장애물이 있으면 통신이 끊길 수 있다. 빛은 곧게 나아가는데 불투명한 장애물을 만나면 더 나아가지 못해 기기까지 닿지 못하기 때문이다.","scoring_points":["좋은 점 두 가지를 썼는가","아쉬운 점을 썼는가","빛의 직진과 이어 까닭을 썼는가"]},"explanation":["좋은 점부터 써요.","아쉬운 점을 찾아요.","빛의 직진과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#1','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C5',1,'mc','auto','하늘빛반 일지 ②에서 손전등을 켰을 때만 인형이 잘 보인 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X05','SC5-1-u2-X06','SC5-1-u2-X07']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C5","difficulty":1,"kind":"mc","stem":"하늘빛반 일지 ②에서 손전등을 켰을 때만 인형이 잘 보인 까닭은 어느 것인가요?","options":[{"t":"손전등 빛이 인형을 비추었기 때문에","correct":true},{"t":"인형이 소리를 냈기 때문에","mis":"SC5-1-u2-X05"},{"t":"눈에서 나온 빛이 인형에 닿았기 때문에","mis":"SC5-1-u2-X06"},{"t":"어두우면 인형이 스스로 밝아지기 때문에","mis":"SC5-1-u2-X07"}],"explanation":["켰을 때와 껐을 때예요.","빛이 비춰요.","빛 때문이에요."],"asset":{"type":"passage","lines":["① 어둠상자 구멍을 손전등으로 빈틈없이 막고 관찰 — 잘 보이지 않음","② 손전등을 켜고 관찰 — 상자 속 인형이 잘 보임","③ 짝과 역할을 바꾸어 한 번 더 함","④ 낮, 커튼을 모두 치고 불을 끔 — 커튼 틈 쪽 책만 보임","⑤ 밤, 가로등 아래 자전거는 보이고 골목 안 자전거는 안 보임"],"title":"하늘빛반 빛 탐구 일지 ② 물체를 보려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#2','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C2',1,'sa','auto','하늘빛반 일지 ①의 가 신호가 나타내는 숫자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C2","difficulty":1,"kind":"sa","stem":"하늘빛반 일지 ①의 가 신호가 나타내는 숫자를 쓰세요.","answer":["3"],"explanation":["점이 몇 개인가요?","점 셋에 선 둘이에요.","3이에요."],"asset":{"type":"passage","lines":["운동장 건너편 모둠이 빛 신호 세 개를 보냈다.","가 : · · · — —","나 : — — — — —","다 : — · · · ·","교실을 어둡게 하고 천장을 향해 신호를 보냈다.","한 친구가 손전등을 친구 눈에 비춰 주의를 받았다.","소리를 내지 않고도 숫자를 주고받았다."],"title":"하늘빛반 빛 탐구 일지 ① 빛 신호"},"mis":"SC5-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#3','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C3',1,'ox','auto','빛 신호를 보낼 때 한 사람씩 차례대로 보내요.',ARRAY['SC5-1-u2-X03']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C3","difficulty":1,"kind":"ox","stem":"빛 신호를 보낼 때 한 사람씩 차례대로 보내요.","answer":"O","reason_options":[{"t":"신호가 서로 섞이지 않게 하기 때문에","correct":true},{"t":"여럿이 한꺼번에 켜면 빛이 사라지기 때문에","mis":"SC5-1-u2-X03"}],"mis":"SC5-1-u2-X03","explanation":["신호가 섞이면 어떨까요?","알아보기 어려워요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#4','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C7',1,'mc','auto','밤에도 주변의 물체를 볼 수 있는 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X09','SC5-1-u2-X07','SC5-1-u2-X05']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C7","difficulty":1,"kind":"mc","stem":"밤에도 주변의 물체를 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"많은 전등이 빛을 내어 물체를 비추기 때문에","correct":true},{"t":"밤에는 눈이 커지기 때문에","mis":"SC5-1-u2-X09"},{"t":"밤에는 물체가 스스로 밝아지기 때문에","mis":"SC5-1-u2-X07"},{"t":"밤에는 물체가 소리를 내기 때문에","mis":"SC5-1-u2-X05"}],"explanation":["밤에 빛을 내는 것은?","전등이에요.","전등 빛 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#5','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C1',1,'mc','auto','모스 부호에서 선(—)은 신호를 어떻게 보내나요?',ARRAY['SC5-1-u2-X01','SC5-1-u2-X04']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C1","difficulty":1,"kind":"mc","stem":"모스 부호에서 선(—)은 신호를 어떻게 보내나요?","options":[{"t":"신호를 길게 보낸다","correct":true},{"t":"신호를 짧게 보낸다","mis":"SC5-1-u2-X01"},{"t":"신호를 소리로 바꾸어 보낸다","mis":"SC5-1-u2-X04"},{"t":"신호를 보내지 않는다","mis":"SC5-1-u2-X01"}],"explanation":["선은 긴 표시예요.","점과 반대예요.","길게 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#6','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C2',1,'blank','auto','「숫자 0은 모스 부호로 (    )만 다섯 개로 나타냅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u2-X02','SC5-1-u2-X04']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C2","difficulty":1,"kind":"blank","stem":"「숫자 0은 모스 부호로 (    )만 다섯 개로 나타냅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"선","correct":true},{"t":"점","mis":"SC5-1-u2-X02"},{"t":"점과 선","mis":"SC5-1-u2-X02"},{"t":"소리","mis":"SC5-1-u2-X04"}],"explanation":["0을 떠올려요.","긴 표시예요.","선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#7','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C18',1,'match','auto','빛의 성질과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-1-u2-C18","difficulty":1,"kind":"match","stem":"빛의 성질과 뜻을 알맞게 이으세요.","pairs":[{"l":"빛의 직진","r":"빛이 곧게 나아간다"},{"l":"빛의 반사","r":"빛이 거울에 부딪쳐 방향이 바뀐다"},{"l":"빛의 굴절","r":"빛이 서로 다른 물질의 경계에서 꺾인다"}],"mis":"SC5-1-u2-X23","explanation":["세 성질이에요.","곧게·바뀜·꺾임이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#8','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C4',1,'mc','auto','하늘빛반 일지 ①에서 소리를 내지 않고도 숫자를 주고받을 수 있었던 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X04']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C4","difficulty":1,"kind":"mc","stem":"하늘빛반 일지 ①에서 소리를 내지 않고도 숫자를 주고받을 수 있었던 까닭은 어느 것인가요?","options":[{"t":"빛 신호는 소리 없이도 멀리 있는 사람에게 전할 수 있기 때문에","correct":true},{"t":"빛 신호는 소리가 커야 전해지기 때문에","mis":"SC5-1-u2-X04"},{"t":"빛 신호는 바로 옆 사람에게만 보이기 때문에","mis":"SC5-1-u2-X04"},{"t":"손전등이 숫자를 소리로 바꾸어 주기 때문에","mis":"SC5-1-u2-X04"}],"explanation":["빛 신호의 좋은 점이에요.","소리가 필요 없어요.","멀리 전해요."],"asset":{"type":"passage","lines":["운동장 건너편 모둠이 빛 신호 세 개를 보냈다.","가 : · · · — —","나 : — — — — —","다 : — · · · ·","교실을 어둡게 하고 천장을 향해 신호를 보냈다.","한 친구가 손전등을 친구 눈에 비춰 주의를 받았다.","소리를 내지 않고도 숫자를 주고받았다."],"title":"하늘빛반 빛 탐구 일지 ① 빛 신호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#9','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C2',2,'mc','auto','하늘빛반 일지 ①의 나 신호가 나타내는 숫자는 어느 것인가요?',ARRAY['SC5-1-u2-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C2","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ①의 나 신호가 나타내는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"5","mis":"SC5-1-u2-X02"},{"t":"9","mis":"SC5-1-u2-X02"},{"t":"1","mis":"SC5-1-u2-X02"}],"explanation":["선만 있어요.","선 다섯 개예요.","0이에요."],"asset":{"type":"passage","lines":["운동장 건너편 모둠이 빛 신호 세 개를 보냈다.","가 : · · · — —","나 : — — — — —","다 : — · · · ·","교실을 어둡게 하고 천장을 향해 신호를 보냈다.","한 친구가 손전등을 친구 눈에 비춰 주의를 받았다.","소리를 내지 않고도 숫자를 주고받았다."],"title":"하늘빛반 빛 탐구 일지 ① 빛 신호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#10','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C6',2,'mc','auto','하늘빛반 일지 ②의 실험에서 바르게 한 점은 어느 것인가요?',ARRAY['SC5-1-u2-X08','SC5-1-u2-X03']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C6","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ②의 실험에서 바르게 한 점은 어느 것인가요?","options":[{"t":"구멍을 빈틈없이 막고 짝과 역할을 바꾸어 한 번 더 했다","correct":true},{"t":"뚜껑을 열어 바깥 빛도 들어오게 했다","mis":"SC5-1-u2-X08"},{"t":"상자 속 인형을 미리 보여 주었다","mis":"SC5-1-u2-X08"},{"t":"손전등 빛을 짝의 눈에 비추었다","mis":"SC5-1-u2-X03"}],"explanation":["실험 방법이에요.","빈틈없이, 바꾸어 반복해요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 어둠상자 구멍을 손전등으로 빈틈없이 막고 관찰 — 잘 보이지 않음","② 손전등을 켜고 관찰 — 상자 속 인형이 잘 보임","③ 짝과 역할을 바꾸어 한 번 더 함","④ 낮, 커튼을 모두 치고 불을 끔 — 커튼 틈 쪽 책만 보임","⑤ 밤, 가로등 아래 자전거는 보이고 골목 안 자전거는 안 보임"],"title":"하늘빛반 빛 탐구 일지 ② 물체를 보려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#11','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C9',2,'mc','auto','하늘빛반 일지 ③의 ①~③을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X11','SC5-1-u2-X12','SC5-1-u2-X13']::text[],false,'{"seq":11,"concept":"SC5-1-u2-C9","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ③의 ①~③을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"햇빛과 레이저 지시기의 빛은 곧게 나아간다","correct":true},{"t":"빛은 구불구불 나아간다","mis":"SC5-1-u2-X11"},{"t":"빛은 물을 뿌릴 때에만 곧게 나아간다","mis":"SC5-1-u2-X12"},{"t":"빛은 물체를 돌아서 나아간다","mis":"SC5-1-u2-X13"}],"explanation":["세 관찰을 견줘요.","모두 곧았어요.","곧게 나아가요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#12','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C12',2,'mc','auto','하늘빛반 일지 ④의 ①에서 빛이 모양판 가에 닿은 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X16','SC5-1-u2-X17','SC5-1-u2-X23']::text[],false,'{"seq":12,"concept":"SC5-1-u2-C12","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ④의 ①에서 빛이 모양판 가에 닿은 까닭은 어느 것인가요?","options":[{"t":"빛이 거울에 부딪쳐 나아가는 방향이 바뀌었기 때문에","correct":true},{"t":"빛이 거울을 통과했기 때문에","mis":"SC5-1-u2-X16"},{"t":"빛이 스스로 방향을 바꾸었기 때문에","mis":"SC5-1-u2-X17"},{"t":"빛이 물을 만나 꺾였기 때문에","mis":"SC5-1-u2-X23"}],"explanation":["거울을 만났어요.","방향이 바뀌었어요.","반사예요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#13','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C15',2,'mc','auto','하늘빛반 일지 ⑤의 렌즈 ㉮의 이름은 무엇인가요?',ARRAY['SC5-1-u2-X20','SC5-1-u2-X23']::text[],false,'{"seq":13,"concept":"SC5-1-u2-C15","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑤의 렌즈 ㉮의 이름은 무엇인가요?","options":[{"t":"볼록 렌즈","correct":true},{"t":"오목 렌즈","mis":"SC5-1-u2-X20"},{"t":"평면거울","mis":"SC5-1-u2-X23"},{"t":"모양판","mis":"SC5-1-u2-X20"}],"explanation":["가운데가 볼록해요.","이름 그대로예요.","볼록 렌즈예요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#14','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C19',2,'mc','auto','하늘빛반 일지 ⑥에서 빛의 반사를 이용한 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":14,"concept":"SC5-1-u2-C19","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑥에서 빛의 반사를 이용한 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"가, 다","mis":"SC5-1-u2-X26"},{"t":"가, 마","mis":"SC5-1-u2-X26"},{"t":"다, 마","mis":"SC5-1-u2-X26"}],"explanation":["거울을 찾아요.","신발 가게 거울과 거울 예술이에요.","나와 라예요."],"asset":{"type":"passage","lines":["가 수술용 확대경 — 렌즈","나 신발 가게 거울 — 거울","다 사진기 — 렌즈","라 거울 예술 작품 — 거울","마 멀리 있는 것이 흐릴 때 쓰는 안경 — 렌즈"],"title":"하늘빛반 빛 탐구 일지 ⑥ 생활 속 거울과 렌즈 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#15','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C16',2,'ox','auto','오목 렌즈를 지난 빛은 한곳으로 모여요.',ARRAY['SC5-1-u2-X21']::text[],false,'{"seq":15,"concept":"SC5-1-u2-C16","difficulty":2,"kind":"ox","stem":"오목 렌즈를 지난 빛은 한곳으로 모여요.","answer":"X","reason_options":[{"t":"오목 렌즈를 지난 빛은 바깥쪽으로 꺾여 퍼지기 때문에","correct":true},{"t":"모든 렌즈는 빛을 한곳으로 모으기 때문에","mis":"SC5-1-u2-X21"}],"mis":"SC5-1-u2-X21","explanation":["오목 렌즈예요.","퍼져요.","모이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#16','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C22',2,'mc','auto','하늘빛반 일지 ⑦에서 1모둠이 거울 두 개를 각도가 움직이게 붙인 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X34','SC5-1-u2-X30']::text[],false,'{"seq":16,"concept":"SC5-1-u2-C22","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑦에서 1모둠이 거울 두 개를 각도가 움직이게 붙인 까닭은 어느 것인가요?","options":[{"t":"각도를 조절해 피자 한 조각이 한 판으로 보이게 하려고","correct":true},{"t":"거울을 더 크게 보이게 하려고","mis":"SC5-1-u2-X34"},{"t":"빛을 꺾어 피자를 크게 하려고","mis":"SC5-1-u2-X30"},{"t":"거울이 깨지지 않게 하려고","mis":"SC5-1-u2-X34"}],"explanation":["피자 한 판 장치예요.","각도가 중요해요.","한 판으로 보이게 해요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#17','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C5',3,'error','auto','하늘빛반 일지 ⑧에서 보미의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u2-X06','SC5-1-u2-X07']::text[],false,'{"seq":17,"concept":"SC5-1-u2-C5","difficulty":3,"kind":"error","stem":"하늘빛반 일지 ⑧에서 보미의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"라온 — 「물체에서 반사된 빛이 눈에 들어와야 물체가 보여.」","correct":true,"mis_target":"SC5-1-u2-X06"},{"t":"세아 — 「눈을 크게 뜨면 빛이 더 많이 나와서 잘 보여.」","mis":"SC5-1-u2-X06"},{"t":"주원 — 「빛이 없어도 가까이 있으면 보여.」","mis":"SC5-1-u2-X07"}],"explanation":["어둠상자를 떠올려요.","빛은 물체에서 눈으로 와요.","라온이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#18','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C25',3,'ox','auto','하늘빛반 일지 ⑧의 시후 말처럼 라이파이는 빛이 없어도 잘 돼요.',ARRAY['SC5-1-u2-X36']::text[],false,'{"seq":18,"concept":"SC5-1-u2-C25","difficulty":3,"kind":"ox","stem":"하늘빛반 일지 ⑧의 시후 말처럼 라이파이는 빛이 없어도 잘 돼요.","answer":"X","reason_options":[{"t":"라이파이는 LED 등의 빛으로 정보를 실어 보내므로 빛이 닿아야 하기 때문에","correct":true},{"t":"라이파이는 와이파이처럼 빛이 필요 없기 때문에","mis":"SC5-1-u2-X36"}],"mis":"SC5-1-u2-X36","explanation":["무엇으로 통신하나요?","빛이에요.","빛이 있어야 해요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#19','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C14',3,'mc','auto','어둠상자 속 인형을 볼 수 있었던 과정을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u2-X06','SC5-1-u2-X07','SC5-1-u2-X16']::text[],false,'{"seq":19,"concept":"SC5-1-u2-C14","difficulty":3,"kind":"mc","stem":"어둠상자 속 인형을 볼 수 있었던 과정을 바르게 말한 것은 어느 것인가요?","options":[{"t":"손전등 빛이 인형을 비추고, 인형에서 반사된 빛이 관찰 구멍을 지나 눈에 들어왔다","correct":true},{"t":"눈에서 나온 빛이 관찰 구멍을 지나 인형에 닿았다","mis":"SC5-1-u2-X06"},{"t":"손전등을 켜자 인형이 스스로 밝아졌다","mis":"SC5-1-u2-X07"},{"t":"손전등 빛이 인형을 그대로 통과해 눈에 들어왔다","mis":"SC5-1-u2-X16"}],"explanation":["빛의 길을 따라가요.","물체에서 눈으로 와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#20','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C9',3,'mc','auto','레이저 지시기의 빛이 거울이나 렌즈를 만나기 전, 공기 속에서는 어떻게 나아가나요?',ARRAY['SC5-1-u2-X11','SC5-1-u2-X12']::text[],false,'{"seq":20,"concept":"SC5-1-u2-C9","difficulty":3,"kind":"mc","stem":"레이저 지시기의 빛이 거울이나 렌즈를 만나기 전, 공기 속에서는 어떻게 나아가나요?","options":[{"t":"곧게 나아간다","correct":true},{"t":"구불구불 나아간다","mis":"SC5-1-u2-X11"},{"t":"점점 휘어 나아간다","mis":"SC5-1-u2-X11"},{"t":"물이 있을 때에만 곧게 나아간다","mis":"SC5-1-u2-X12"}],"explanation":["직진을 떠올려요.","아무것도 만나지 않았어요.","곧게 나아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#21','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C19',3,'mc','auto','생활 속 기구와 이용한 빛의 성질을 바르게 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X19']::text[],false,'{"seq":21,"concept":"SC5-1-u2-C19","difficulty":3,"kind":"mc","stem":"생활 속 기구와 이용한 빛의 성질을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"치과 거울·전등 갓 — 반사, 수술용 확대경·사진기 — 굴절","correct":true},{"t":"치과 거울·전등 갓 — 굴절, 수술용 확대경·사진기 — 반사","mis":"SC5-1-u2-X26"},{"t":"네 가지 모두 반사","mis":"SC5-1-u2-X26"},{"t":"네 가지 모두 직진","mis":"SC5-1-u2-X19"}],"explanation":["거울과 렌즈로 나눠요.","거울은 반사예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#22','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C24',3,'mc','auto','1차시의 빛 신호와 라이파이를 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u2-X35','SC5-1-u2-X04']::text[],false,'{"seq":22,"concept":"SC5-1-u2-C24","difficulty":3,"kind":"mc","stem":"1차시의 빛 신호와 라이파이를 바르게 견준 것은 어느 것인가요?","options":[{"t":"빛 신호는 사람이 눈으로 읽고, 라이파이는 아주 빠른 깜박임을 기기가 읽는다","correct":true},{"t":"둘 다 소리로 정보를 전한다","mis":"SC5-1-u2-X35"},{"t":"라이파이의 깜박임도 사람이 하나하나 읽는다","mis":"SC5-1-u2-X35"},{"t":"빛 신호는 바로 옆 사람에게만 전할 수 있다","mis":"SC5-1-u2-X04"}],"explanation":["둘 다 빛이에요.","누가 읽나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#23','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C5',4,'mc','auto','깜깜한 방에서 거울 앞에 섰더니 내 모습이 보이지 않았고, 불을 켜자 보였어요. 가장 알맞은 설명은 어느 것인가요?',ARRAY['SC5-1-u2-X28','SC5-1-u2-X06','SC5-1-u2-X16']::text[],false,'{"seq":23,"concept":"SC5-1-u2-C5","difficulty":4,"kind":"mc","stem":"깜깜한 방에서 거울 앞에 섰더니 내 모습이 보이지 않았고, 불을 켜자 보였어요. 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"빛이 나를 비추고, 나에게서 온 빛이 거울에 반사되어 눈에 들어와야 보이기 때문에","correct":true},{"t":"거울이 스스로 빛을 내야 보이기 때문에","mis":"SC5-1-u2-X28"},{"t":"눈에서 나온 빛이 거울에 닿아야 보이기 때문에","mis":"SC5-1-u2-X06"},{"t":"어두우면 거울이 빛을 통과시키기 때문에","mis":"SC5-1-u2-X16"}],"explanation":["어둠상자와 거울을 이어요.","빛이 비춰야 해요.","반사되어 눈에 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#24','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C2',4,'essay','teacher','하늘빛반 일지 ①의 가, 나, 다 신호가 나타내는 숫자를 차례로 쓰고, 숫자 모스 부호가 어떤 짜임으로 되어 있는지 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u2-C2","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ①의 가, 나, 다 신호가 나타내는 숫자를 차례로 쓰고, 숫자 모스 부호가 어떤 짜임으로 되어 있는지 설명하세요.","answer_guide":{"answer":"예: 가는 3, 나는 0, 다는 6이다. 숫자 하나는 점과 선 다섯 개로 나타낸다. 1부터 5까지는 앞에서부터 점이 하나씩 늘어나서 5는 점만 다섯 개이고, 6부터는 앞에서부터 선이 하나씩 늘어나서 0은 선만 다섯 개이다. 점은 신호를 짧게, 선은 신호를 길게 보낸다.","scoring_points":["세 숫자를 바르게 썼는가","다섯 칸의 짜임을 설명했는가","점과 선이 늘어나는 차례를 썼는가"]},"explanation":["하나씩 숫자로 바꿔요.","점과 선의 개수를 봐요.","짜임을 써요."],"asset":{"type":"passage","lines":["운동장 건너편 모둠이 빛 신호 세 개를 보냈다.","가 : · · · — —","나 : — — — — —","다 : — · · · ·","교실을 어둡게 하고 천장을 향해 신호를 보냈다.","한 친구가 손전등을 친구 눈에 비춰 주의를 받았다.","소리를 내지 않고도 숫자를 주고받았다."],"title":"하늘빛반 빛 탐구 일지 ① 빛 신호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_a#25','sci',5,1,'u2','','g5_1_sci_u2_review_a','unit_review','SC5-1-u2-C6',4,'essay','teacher','하늘빛반 일지 ⑧의 보미와 찬희의 말이 왜 옳지 않은지 배운 실험을 근거로 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u2-C6","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ⑧의 보미와 찬희의 말이 왜 옳지 않은지 배운 실험을 근거로 바로잡아 쓰세요.","answer_guide":{"answer":"예: 보미야, 어둠상자에서 손전등을 끄면 눈을 뜨고 있어도 인형이 보이지 않았어. 눈에서 빛이 나오는 것이 아니라 빛이 물체를 비추고 물체에서 반사된 빛이 눈에 들어와야 물체가 보이는 거야. 찬희야, 물을 뿌리는 것은 빛이 나아가는 길을 잘 보이게 하려는 거야. 물이 없어도 빛은 언제나 곧게 나아가.","scoring_points":["보미의 말을 실험 근거로 바로잡았는가","찬희의 말을 물의 역할로 바로잡았는가","빛은 언제나 곧게 나아간다고 썼는가"]},"explanation":["보미부터 따져요.","찬희는 물의 역할이에요.","근거를 들어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#1','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C9',1,'mc','auto','하늘빛반 일지 ③의 ①~③에서 공통으로 관찰한 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X19','SC5-1-u2-X11']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C9","difficulty":1,"kind":"mc","stem":"하늘빛반 일지 ③의 ①~③에서 공통으로 관찰한 빛의 성질은 어느 것인가요?","options":[{"t":"빛의 직진","correct":true},{"t":"빛의 반사","mis":"SC5-1-u2-X19"},{"t":"빛의 굴절","mis":"SC5-1-u2-X19"},{"t":"빛의 흔들림","mis":"SC5-1-u2-X11"}],"explanation":["곧은 빛이에요.","곧게 나아가요.","직진이에요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#2','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C9',1,'sa','auto','「구름 사이로 쏟아지는 햇빛이 곧은 줄처럼 보이는 것은 빛의 □□과 관련 있습니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C9","difficulty":1,"kind":"sa","stem":"「구름 사이로 쏟아지는 햇빛이 곧은 줄처럼 보이는 것은 빛의 □□과 관련 있습니다.」 □□에 알맞은 말을 쓰세요.","answer":["직진"],"explanation":["곧은 줄이에요.","곧게 나아가요.","직진이에요."],"mis":"SC5-1-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#3','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C10',1,'ox','auto','레이저 지시기의 빛은 친구 눈에 비추어도 괜찮아요.',ARRAY['SC5-1-u2-X03']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C10","difficulty":1,"kind":"ox","stem":"레이저 지시기의 빛은 친구 눈에 비추어도 괜찮아요.","answer":"X","reason_options":[{"t":"눈에 비추면 눈을 다칠 수 있기 때문에","correct":true},{"t":"레이저 지시기의 빛은 약해서 괜찮기 때문에","mis":"SC5-1-u2-X03"}],"mis":"SC5-1-u2-X03","explanation":["안전을 떠올려요.","눈은 소중해요.","비추면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#4','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C11',1,'mc','auto','그림자는 빛이 무엇을 만났을 때 생기나요?',ARRAY['SC5-1-u2-X19','SC5-1-u2-X13','SC5-1-u2-X15']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C11","difficulty":1,"kind":"mc","stem":"그림자는 빛이 무엇을 만났을 때 생기나요?","options":[{"t":"불투명한 물체를 만나 더 나아가지 못할 때","correct":true},{"t":"소리를 만났을 때","mis":"SC5-1-u2-X19"},{"t":"물체를 돌아서 지나갈 때","mis":"SC5-1-u2-X13"},{"t":"그림자는 물체가 스스로 만든다","mis":"SC5-1-u2-X15"}],"explanation":["빛은 곧게 가요.","막히면 못 가요.","불투명한 물체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#5','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C14',1,'mc','auto','잔잔한 호수에 산의 모습이 비치는 것과 관련 있는 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X19','SC5-1-u2-X28']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C14","difficulty":1,"kind":"mc","stem":"잔잔한 호수에 산의 모습이 비치는 것과 관련 있는 빛의 성질은 어느 것인가요?","options":[{"t":"빛의 반사","correct":true},{"t":"빛의 굴절","mis":"SC5-1-u2-X23"},{"t":"그림자가 생기는 성질","mis":"SC5-1-u2-X19"},{"t":"호수가 스스로 빛을 내는 성질","mis":"SC5-1-u2-X28"}],"explanation":["물이 거울 같아요.","되비쳐요.","반사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#6','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C10',1,'blank','auto','「레이저 지시기 앞쪽에 분무기로 (    )을 뿌리면 빛이 나아가는 길이 잘 보입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u2-X12']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C10","difficulty":1,"kind":"blank","stem":"「레이저 지시기 앞쪽에 분무기로 (    )을 뿌리면 빛이 나아가는 길이 잘 보입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"모래","mis":"SC5-1-u2-X12"},{"t":"기름","mis":"SC5-1-u2-X12"},{"t":"얼음","mis":"SC5-1-u2-X12"}],"explanation":["분무기에 든 것이에요.","물방울이에요.","물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#7','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C20',1,'match','auto','기구와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-1-u2-C20","difficulty":1,"kind":"match","stem":"기구와 하는 일을 알맞게 이으세요.","pairs":[{"l":"치과 거울","r":"입안의 잘 보이지 않는 곳을 본다"},{"l":"관찰용 확대경","r":"작은 곤충을 크게 본다"},{"l":"자동차 뒷거울","r":"뒤에 있는 자동차를 본다"}],"mis":"SC5-1-u2-X26","explanation":["거울과 렌즈예요.","하는 일이 달라요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#8','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C8',1,'mc','auto','빛이 모두 사라지면 생길 수 있는 일은 어느 것인가요?',ARRAY['SC5-1-u2-X10']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C8","difficulty":1,"kind":"mc","stem":"빛이 모두 사라지면 생길 수 있는 일은 어느 것인가요?","options":[{"t":"아침에 방문을 찾아가기 어렵다","correct":true},{"t":"좋아하는 노래를 들을 수 없다","mis":"SC5-1-u2-X10"},{"t":"음식의 맛을 느낄 수 없다","mis":"SC5-1-u2-X10"},{"t":"꽃의 향기를 맡을 수 없다","mis":"SC5-1-u2-X10"}],"explanation":["빛과 관계있는 일이에요.","보는 일이에요.","방문을 찾기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#9','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C2',2,'mc','auto','하늘빛반 일지 ①의 다 신호가 나타내는 숫자는 어느 것인가요?',ARRAY['SC5-1-u2-X01','SC5-1-u2-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C2","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ①의 다 신호가 나타내는 숫자는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"1","mis":"SC5-1-u2-X01"},{"t":"9","mis":"SC5-1-u2-X02"},{"t":"5","mis":"SC5-1-u2-X02"}],"explanation":["선으로 시작해요.","선 하나에 점 넷이에요.","6이에요."],"asset":{"type":"passage","lines":["운동장 건너편 모둠이 빛 신호 세 개를 보냈다.","가 : · · · — —","나 : — — — — —","다 : — · · · ·","교실을 어둡게 하고 천장을 향해 신호를 보냈다.","한 친구가 손전등을 친구 눈에 비춰 주의를 받았다.","소리를 내지 않고도 숫자를 주고받았다."],"title":"하늘빛반 빛 탐구 일지 ① 빛 신호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#10','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C7',2,'mc','auto','하늘빛반 일지 ②의 ⑤에서 골목 안 자전거가 보이지 않은 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X09','SC5-1-u2-X07','SC5-1-u2-X06']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C7","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ②의 ⑤에서 골목 안 자전거가 보이지 않은 까닭은 어느 것인가요?","options":[{"t":"골목 안에는 자전거를 비추는 빛이 없었기 때문에","correct":true},{"t":"골목 안 자전거가 더 작기 때문에","mis":"SC5-1-u2-X09"},{"t":"어두우면 자전거가 스스로 어두워지기 때문에","mis":"SC5-1-u2-X07"},{"t":"눈에서 나온 빛이 골목까지 닿지 않았기 때문에","mis":"SC5-1-u2-X06"}],"explanation":["가로등 아래와 견줘요.","빛이 비추는지 봐요.","빛이 없었어요."],"asset":{"type":"passage","lines":["① 어둠상자 구멍을 손전등으로 빈틈없이 막고 관찰 — 잘 보이지 않음","② 손전등을 켜고 관찰 — 상자 속 인형이 잘 보임","③ 짝과 역할을 바꾸어 한 번 더 함","④ 낮, 커튼을 모두 치고 불을 끔 — 커튼 틈 쪽 책만 보임","⑤ 밤, 가로등 아래 자전거는 보이고 골목 안 자전거는 안 보임"],"title":"하늘빛반 빛 탐구 일지 ② 물체를 보려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#11','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C11',2,'mc','auto','하늘빛반 일지 ③의 ④에서 그림자가 두 개 생긴 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X15','SC5-1-u2-X11','SC5-1-u2-X13']::text[],false,'{"seq":11,"concept":"SC5-1-u2-C11","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ③의 ④에서 그림자가 두 개 생긴 까닭은 어느 것인가요?","options":[{"t":"두 손전등의 빛이 각각 곧게 나아가다 인형에 막혔기 때문에","correct":true},{"t":"인형의 그림자가 스스로 둘로 나뉘었기 때문에","mis":"SC5-1-u2-X15"},{"t":"두 빛이 부딪혀 휘었기 때문에","mis":"SC5-1-u2-X11"},{"t":"빛이 인형을 돌아서 지나갔기 때문에","mis":"SC5-1-u2-X13"}],"explanation":["빛이 두 개예요.","각각 막혔어요.","그래서 둘이에요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#12','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C13',2,'mc','auto','하늘빛반 일지 ④의 ①과 ②를 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X17','SC5-1-u2-X16']::text[],false,'{"seq":12,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ④의 ①과 ②를 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"거울의 방향을 바꾸면 빛이 닿는 곳도 달라진다","correct":true},{"t":"거울을 돌려도 빛이 닿는 곳은 같다","mis":"SC5-1-u2-X17"},{"t":"레이저 지시기를 움직여야만 닿는 곳이 바뀐다","mis":"SC5-1-u2-X17"},{"t":"거울을 돌리면 빛이 사라진다","mis":"SC5-1-u2-X16"}],"explanation":["달라진 것은 거울이에요.","닿는 곳이 바뀌었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#13','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C16',2,'mc','auto','하늘빛반 일지 ⑤에서 렌즈 ㉯를 지난 빛을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X25','SC5-1-u2-X23']::text[],false,'{"seq":13,"concept":"SC5-1-u2-C16","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑤에서 렌즈 ㉯를 지난 빛을 바르게 말한 것은 어느 것인가요?","options":[{"t":"바깥쪽으로 꺾여 퍼져 나갔다","correct":true},{"t":"안쪽으로 꺾여 모였다","mis":"SC5-1-u2-X21"},{"t":"꺾이지 않고 곧게 나아갔다","mis":"SC5-1-u2-X25"},{"t":"렌즈에 부딪쳐 되돌아 나왔다","mis":"SC5-1-u2-X23"}],"explanation":["오목 렌즈예요.","바깥쪽이에요.","퍼져요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#14','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C20',2,'mc','auto','하늘빛반 일지 ⑥의 마 안경에 들어 있는 렌즈는 어느 것인가요?',ARRAY['SC5-1-u2-X27','SC5-1-u2-X26']::text[],false,'{"seq":14,"concept":"SC5-1-u2-C20","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑥의 마 안경에 들어 있는 렌즈는 어느 것인가요?","options":[{"t":"오목 렌즈","correct":true},{"t":"볼록 렌즈만","mis":"SC5-1-u2-X27"},{"t":"평면거울","mis":"SC5-1-u2-X26"},{"t":"렌즈가 없다","mis":"SC5-1-u2-X26"}],"explanation":["멀리 있는 것이 흐려요.","오목 렌즈 안경이에요.","오목 렌즈예요."],"asset":{"type":"passage","lines":["가 수술용 확대경 — 렌즈","나 신발 가게 거울 — 거울","다 사진기 — 렌즈","라 거울 예술 작품 — 거울","마 멀리 있는 것이 흐릴 때 쓰는 안경 — 렌즈"],"title":"하늘빛반 빛 탐구 일지 ⑥ 생활 속 거울과 렌즈 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#15','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C14',2,'ox','auto','물체가 반사한 빛이 우리 눈에 들어와 물체가 보여요.',ARRAY['SC5-1-u2-X06']::text[],false,'{"seq":15,"concept":"SC5-1-u2-C14","difficulty":2,"kind":"ox","stem":"물체가 반사한 빛이 우리 눈에 들어와 물체가 보여요.","answer":"O","reason_options":[{"t":"빛이 물체에서 반사되어 눈으로 들어오기 때문에","correct":true},{"t":"눈에서 나온 빛이 물체에 닿아야 하기 때문에","mis":"SC5-1-u2-X06"}],"mis":"SC5-1-u2-X06","explanation":["빛은 어디서 오나요?","물체에서 눈으로 와요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#16','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C23',2,'mc','auto','하늘빛반 일지 ⑦에서 2모둠이 고쳐야 할 점은 어느 것인가요?',ARRAY['SC5-1-u2-X31','SC5-1-u2-X32']::text[],false,'{"seq":16,"concept":"SC5-1-u2-C23","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑦에서 2모둠이 고쳐야 할 점은 어느 것인가요?","options":[{"t":"다른 빛이 들어오지 않도록 상자 뚜껑을 닫는다","correct":true},{"t":"볼록 렌즈를 거울로 바꾼다","mis":"SC5-1-u2-X31"},{"t":"상자를 더 크게 만든다","mis":"SC5-1-u2-X32"},{"t":"고칠 것이 없다","mis":"SC5-1-u2-X31"}],"explanation":["어두운 상자여야 해요.","뚜껑이 열렸어요.","닫아야 해요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#17','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C10',3,'error','auto','하늘빛반 일지 ⑧에서 찬희의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u2-X12','SC5-1-u2-X11']::text[],false,'{"seq":17,"concept":"SC5-1-u2-C10","difficulty":3,"kind":"error","stem":"하늘빛반 일지 ⑧에서 찬희의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"다온 — 「물은 빛의 길을 보이게 할 뿐이고, 빛은 언제나 곧게 나아가.」","correct":true,"mis_target":"SC5-1-u2-X12"},{"t":"리아 — 「물을 뿌리면 빛이 더 세져서 곧아져.」","mis":"SC5-1-u2-X12"},{"t":"한별 — 「빛은 원래 구불구불한데 물이 펴 줘.」","mis":"SC5-1-u2-X11"}],"explanation":["물의 역할이에요.","길을 보여 줘요.","다온이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#18','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C17',3,'ox','auto','빛이 물에서 공기로 비스듬히 나아갈 때에도 경계에서 꺾여요.',ARRAY['SC5-1-u2-X22']::text[],false,'{"seq":18,"concept":"SC5-1-u2-C17","difficulty":3,"kind":"ox","stem":"빛이 물에서 공기로 비스듬히 나아갈 때에도 경계에서 꺾여요.","answer":"O","reason_options":[{"t":"빛은 서로 다른 물질의 경계를 지날 때 꺾이기 때문에","correct":true},{"t":"물 밖으로 나온 빛은 사라지기 때문에","mis":"SC5-1-u2-X22"}],"mis":"SC5-1-u2-X22","explanation":["반대 방향이에요.","경계는 그대로예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#19','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C19',3,'mc','auto','세상의 모든 거울이 사라진다면 어떤 일이 생길까요?',ARRAY['SC5-1-u2-X40','SC5-1-u2-X26']::text[],false,'{"seq":19,"concept":"SC5-1-u2-C19","difficulty":3,"kind":"mc","stem":"세상의 모든 거울이 사라진다면 어떤 일이 생길까요?","options":[{"t":"운전할 때 뒤에 오는 자동차를 보기 어렵다","correct":true},{"t":"빛이 더 이상 곧게 나아가지 못한다","mis":"SC5-1-u2-X40"},{"t":"낮에도 아무것도 보이지 않는다","mis":"SC5-1-u2-X40"},{"t":"작은 곤충을 크게 볼 수 없다","mis":"SC5-1-u2-X26"}],"explanation":["거울이 하는 일이에요.","뒷거울이 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#20','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C16',3,'mc','auto','그림의 렌즈 ㉠을 오목 렌즈로 바꾸면 지난 빛은 어떻게 될까요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X25','SC5-1-u2-X23']::text[],false,'{"seq":20,"concept":"SC5-1-u2-C16","difficulty":3,"kind":"mc","stem":"그림의 렌즈 ㉠을 오목 렌즈로 바꾸면 지난 빛은 어떻게 될까요?","options":[{"t":"바깥쪽으로 꺾여 퍼진다","correct":true},{"t":"그림처럼 한곳으로 모인다","mis":"SC5-1-u2-X21"},{"t":"꺾이지 않고 곧게 나아간다","mis":"SC5-1-u2-X25"},{"t":"렌즈에 부딪쳐 되돌아온다","mis":"SC5-1-u2-X23"}],"explanation":["오목 렌즈예요.","모임의 반대예요.","퍼져요."],"asset":{"type":"geo","items":[{"w":300,"h":180,"seg":[[[20,50],[150,50]],[[20,90],[150,90]],[[20,130],[150,130]],[[150,50],[250,90]],[[150,90],[250,90]],[[150,130],[250,90]]],"lab":[[[150,168],"렌즈 ㉠"]],"oval":[[150,90,10,66]],"cap":"렌즈 ㉠을 지난 빛"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#21','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C24',3,'mc','auto','라이파이와 빛의 직진을 이어 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u2-X13','SC5-1-u2-X36','SC5-1-u2-X35']::text[],false,'{"seq":21,"concept":"SC5-1-u2-C24","difficulty":3,"kind":"mc","stem":"라이파이와 빛의 직진을 이어 바르게 말한 것은 어느 것인가요?","options":[{"t":"빛이 곧게 나아가 기기에 닿아야 하므로 장애물이 있으면 끊길 수 있다","correct":true},{"t":"빛이 장애물을 돌아가므로 끊기지 않는다","mis":"SC5-1-u2-X13"},{"t":"빛이 없어도 되므로 장애물은 상관없다","mis":"SC5-1-u2-X36"},{"t":"라이파이는 소리로 통신하므로 직진과 관계없다","mis":"SC5-1-u2-X35"}],"explanation":["빛은 곧게 가요.","막히면 못 가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#22','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C8',3,'mc','auto','빛이 없는 세상을 역할놀이로 나타낼 때 가장 알맞은 장면은 어느 것인가요?',ARRAY['SC5-1-u2-X10']::text[],false,'{"seq":22,"concept":"SC5-1-u2-C8","difficulty":3,"kind":"mc","stem":"빛이 없는 세상을 역할놀이로 나타낼 때 가장 알맞은 장면은 어느 것인가요?","options":[{"t":"깜깜한 방에서 더듬더듬 방문을 찾는 장면","correct":true},{"t":"친구의 목소리가 하나도 안 들리는 장면","mis":"SC5-1-u2-X10"},{"t":"꽃향기가 하나도 안 나는 장면","mis":"SC5-1-u2-X10"},{"t":"음식의 맛이 하나도 안 나는 장면","mis":"SC5-1-u2-X10"}],"explanation":["빛이 없으면 무엇을 못 하나요?","보는 일이에요.","방문을 찾는 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#23','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C16',4,'mc','auto','간이 프로젝터 상자에 끼울 렌즈로 하늘빛반 일지 ⑤의 ㉮와 ㉯ 가운데 알맞은 것과 그 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X31','SC5-1-u2-X25']::text[],false,'{"seq":23,"concept":"SC5-1-u2-C16","difficulty":4,"kind":"mc","stem":"간이 프로젝터 상자에 끼울 렌즈로 하늘빛반 일지 ⑤의 ㉮와 ㉯ 가운데 알맞은 것과 그 까닭은 어느 것인가요?","options":[{"t":"㉮ — 볼록 렌즈가 빛을 굴절시켜 화면을 크게 비추기 때문에","correct":true},{"t":"㉯ — 빛을 안쪽으로 모으기 때문에","mis":"SC5-1-u2-X21"},{"t":"㉮ — 빛을 반사해 화면을 되비추기 때문에","mis":"SC5-1-u2-X31"},{"t":"둘 다 아니다 — 렌즈는 빛을 꺾지 않기 때문에","mis":"SC5-1-u2-X25"}],"explanation":["간이 프로젝터를 떠올려요.","볼록 렌즈를 끼웠어요.","㉮예요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#24','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C9',4,'essay','teacher','하늘빛반 일지 ③의 ①~③에서 알 수 있는 빛의 성질을 쓰고, ④에서 그림자가 두 개 생긴 까닭을 그 성질과 이어서 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u2-C9","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ③의 ①~③에서 알 수 있는 빛의 성질을 쓰고, ④에서 그림자가 두 개 생긴 까닭을 그 성질과 이어서 설명하세요.","answer_guide":{"answer":"예: ①~③에서 햇빛과 레이저 지시기의 빛이 곧게 나아가는 것을 보아 빛은 곧게 나아간다는 것을 알 수 있다. 이것을 빛의 직진이라고 한다. ④에서는 두 손전등의 빛이 각각 곧게 나아가다가 불투명한 인형에 막혀 더 나아가지 못했기 때문에 인형 뒤 벽에 그림자가 두 개 생겼다.","scoring_points":["빛의 직진을 썼는가","불투명한 물체에 막힌다고 썼는가","두 빛이 각각 막힌다고 썼는가"]},"explanation":["곧은 빛을 떠올려요.","막힌 뒤쪽이에요.","두 개의 까닭을 써요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_b#25','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C19',4,'essay','teacher','하늘빛반 일지 ⑧의 도하와 은결의 말이 왜 옳지 않은지 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u2-C19","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ⑧의 도하와 은결의 말이 왜 옳지 않은지 바로잡아 쓰세요.","answer_guide":{"answer":"예: 도하야, 렌즈는 빛을 반사하는 것이 아니라 굴절시켜서 글씨를 크게 보여 줘. 빛을 반사하는 것은 거울이야. 은결아, 거울과 렌즈는 빛이 나아가는 방향을 바꾸거나 꺾을 뿐이야. 거울과 렌즈가 모두 사라져도 빛은 곧게 나아가고, 햇빛이 있으면 물체도 볼 수 있어. 다만 뒷거울로 뒤차를 보거나 돋보기로 글씨를 크게 보는 일이 어려워질 거야.","scoring_points":["도하의 말을 굴절로 바로잡았는가","은결의 말을 빛 자체는 그대로라고 바로잡았는가","거울·렌즈가 없을 때 어려워지는 일을 썼는가"]},"explanation":["도하부터 따져요.","은결은 빛 자체예요.","근거를 들어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#1','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C12',1,'mc','auto','하늘빛반 일지 ④의 ①에서 관찰한 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X17','SC5-1-u2-X16']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C12","difficulty":1,"kind":"mc","stem":"하늘빛반 일지 ④의 ①에서 관찰한 빛의 성질은 어느 것인가요?","options":[{"t":"빛의 반사","correct":true},{"t":"빛의 굴절","mis":"SC5-1-u2-X23"},{"t":"빛의 직진만","mis":"SC5-1-u2-X17"},{"t":"빛이 사라지는 성질","mis":"SC5-1-u2-X16"}],"explanation":["거울에 비췄어요.","방향이 바뀌어요.","반사예요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#2','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C12',1,'sa','auto','「거울로 내 모습을 볼 수 있는 것은 빛의 □□와 관련 있습니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C12","difficulty":1,"kind":"sa","stem":"「거울로 내 모습을 볼 수 있는 것은 빛의 □□와 관련 있습니다.」 □□에 알맞은 말을 쓰세요.","answer":["반사"],"explanation":["거울이에요.","되비쳐요.","반사예요."],"mis":"SC5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#3','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C15',1,'ox','auto','볼록 렌즈는 가운데가 오목하고 가장자리로 갈수록 두꺼워져요.',ARRAY['SC5-1-u2-X20']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C15","difficulty":1,"kind":"ox","stem":"볼록 렌즈는 가운데가 오목하고 가장자리로 갈수록 두꺼워져요.","answer":"X","reason_options":[{"t":"볼록 렌즈는 가운데가 볼록하고 가장자리로 갈수록 얇아지기 때문에","correct":true},{"t":"볼록 렌즈와 오목 렌즈는 모양이 같기 때문에","mis":"SC5-1-u2-X20"}],"mis":"SC5-1-u2-X20","explanation":["이름을 봐요.","가운데가 볼록해요.","오목 렌즈 설명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#4','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C16',1,'mc','auto','볼록 렌즈를 지난 나란한 빛은 어떻게 나아가나요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X25','SC5-1-u2-X23']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C16","difficulty":1,"kind":"mc","stem":"볼록 렌즈를 지난 나란한 빛은 어떻게 나아가나요?","options":[{"t":"안쪽으로 꺾여 한곳으로 모인다","correct":true},{"t":"바깥쪽으로 꺾여 퍼진다","mis":"SC5-1-u2-X21"},{"t":"꺾이지 않고 그대로 나아간다","mis":"SC5-1-u2-X25"},{"t":"거울처럼 되돌아 나온다","mis":"SC5-1-u2-X23"}],"explanation":["볼록 렌즈예요.","안쪽으로 꺾여요.","모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#5','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C24',1,'mc','auto','라이파이 기술에서 정보를 실어 나르는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X35']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C24","difficulty":1,"kind":"mc","stem":"라이파이 기술에서 정보를 실어 나르는 것은 어느 것인가요?","options":[{"t":"LED 등의 빛","correct":true},{"t":"확성기의 소리","mis":"SC5-1-u2-X35"},{"t":"자석의 힘","mis":"SC5-1-u2-X35"},{"t":"선풍기의 바람","mis":"SC5-1-u2-X35"}],"explanation":["빛으로 통신해요.","LED 등이에요.","빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#6','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C17',1,'blank','auto','「물이 든 통에 (    )를 몇 방울 떨어뜨리면 물속에서 빛이 지나가는 길이 잘 보입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u2-X24']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C17","difficulty":1,"kind":"blank","stem":"「물이 든 통에 (    )를 몇 방울 떨어뜨리면 물속에서 빛이 지나가는 길이 잘 보입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"우유","correct":true},{"t":"소금","mis":"SC5-1-u2-X24"},{"t":"설탕","mis":"SC5-1-u2-X24"},{"t":"식용유","mis":"SC5-1-u2-X24"}],"explanation":["스포이트로 넣었어요.","흰 액체예요.","우유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#7','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C13',1,'match','auto','평면거울 실험의 준비물과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-1-u2-C13","difficulty":1,"kind":"match","stem":"평면거울 실험의 준비물과 쓰임을 알맞게 이으세요.","pairs":[{"l":"레이저 지시기(확산형)","r":"거울을 향해 빛을 내보낸다"},{"l":"받침대","r":"평면거울을 수직으로 세운다"},{"l":"모양판","r":"빛으로 맞힐 목표가 된다"}],"mis":"SC5-1-u2-X18","explanation":["반사 실험이에요.","빛·세우기·목표예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#8','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C21',1,'mc','auto','조사한 내용을 붙임쪽지에 쓸 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C21","difficulty":1,"kind":"mc","stem":"조사한 내용을 붙임쪽지에 쓸 때 알맞은 방법은 어느 것인가요?","options":[{"t":"한 장의 붙임쪽지에는 하나의 예만 쓴다","correct":true},{"t":"한 장의 붙임쪽지에 예를 모두 쓴다","mis":"SC5-1-u2-X29"},{"t":"모둠에서 한 사람이 혼자 다 쓴다","mis":"SC5-1-u2-X29"},{"t":"인터넷 그림을 출처 없이 붙인다","mis":"SC5-1-u2-X29"}],"explanation":["붙임쪽지 쓰기예요.","하나씩 써요.","한 장에 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#9','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C3',2,'mc','auto','하늘빛반 일지 ①에서 고쳐야 할 행동은 어느 것인가요?',ARRAY['SC5-1-u2-X03','SC5-1-u2-X04']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C3","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ①에서 고쳐야 할 행동은 어느 것인가요?","options":[{"t":"손전등을 친구 눈에 비춘 것","correct":true},{"t":"교실을 어둡게 한 것","mis":"SC5-1-u2-X03"},{"t":"천장을 향해 신호를 보낸 것","mis":"SC5-1-u2-X03"},{"t":"소리를 내지 않고 신호를 보낸 것","mis":"SC5-1-u2-X04"}],"explanation":["안전을 떠올려요.","눈을 지켜요.","눈에 비춘 것이에요."],"asset":{"type":"passage","lines":["운동장 건너편 모둠이 빛 신호 세 개를 보냈다.","가 : · · · — —","나 : — — — — —","다 : — · · · ·","교실을 어둡게 하고 천장을 향해 신호를 보냈다.","한 친구가 손전등을 친구 눈에 비춰 주의를 받았다.","소리를 내지 않고도 숫자를 주고받았다."],"title":"하늘빛반 빛 탐구 일지 ① 빛 신호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#10','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C5',2,'mc','auto','하늘빛반 일지 ②의 ①과 ②를 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X05','SC5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C5","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ②의 ①과 ②를 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"물체를 보려면 물체를 비추는 빛이 있어야 한다","correct":true},{"t":"눈을 크게 뜨면 빛 없이도 보인다","mis":"SC5-1-u2-X07"},{"t":"물체는 소리를 내야 보인다","mis":"SC5-1-u2-X05"},{"t":"상자 안이 따뜻해야 보인다","mis":"SC5-1-u2-X09"}],"explanation":["달라진 것은 손전등이에요.","빛이 비췄어요.","빛이 있어야 해요."],"asset":{"type":"passage","lines":["① 어둠상자 구멍을 손전등으로 빈틈없이 막고 관찰 — 잘 보이지 않음","② 손전등을 켜고 관찰 — 상자 속 인형이 잘 보임","③ 짝과 역할을 바꾸어 한 번 더 함","④ 낮, 커튼을 모두 치고 불을 끔 — 커튼 틈 쪽 책만 보임","⑤ 밤, 가로등 아래 자전거는 보이고 골목 안 자전거는 안 보임"],"title":"하늘빛반 빛 탐구 일지 ② 물체를 보려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#11','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C10',2,'mc','auto','하늘빛반 일지 ③의 ③에서 물을 뿌린 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X12']::text[],false,'{"seq":11,"concept":"SC5-1-u2-C10","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ③의 ③에서 물을 뿌린 까닭은 어느 것인가요?","options":[{"t":"빛이 나아가는 길을 잘 보기 위해서","correct":true},{"t":"빛을 곧게 만들기 위해서","mis":"SC5-1-u2-X12"},{"t":"빛을 차갑게 하기 위해서","mis":"SC5-1-u2-X12"},{"t":"빛을 꺾기 위해서","mis":"SC5-1-u2-X12"}],"explanation":["물의 역할이에요.","길이 보여요.","보기 위해서예요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#12','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C12',2,'mc','auto','하늘빛반 일지 ④의 ③으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X17','SC5-1-u2-X16','SC5-1-u2-X13']::text[],false,'{"seq":12,"concept":"SC5-1-u2-C12","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ④의 ③으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"빛은 거울에 부딪쳐야 방향이 바뀌고, 거울이 없으면 곧게 나아간다","correct":true},{"t":"빛은 거울이 없어도 방향이 바뀐다","mis":"SC5-1-u2-X17"},{"t":"거울이 없으면 빛이 사라진다","mis":"SC5-1-u2-X16"},{"t":"빛은 벽을 돌아서 나아간다","mis":"SC5-1-u2-X13"}],"explanation":["거울을 치웠어요.","곧게 나아갔어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#13','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C17',2,'mc','auto','하늘빛반 일지 ⑤의 물이 든 통에서 빛이 꺾인 곳은 어디인가요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X22']::text[],false,'{"seq":13,"concept":"SC5-1-u2-C17","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑤의 물이 든 통에서 빛이 꺾인 곳은 어디인가요?","options":[{"t":"공기와 물의 경계","correct":true},{"t":"레이저 지시기 바로 앞","mis":"SC5-1-u2-X25"},{"t":"통의 바닥","mis":"SC5-1-u2-X22"},{"t":"물속 한가운데","mis":"SC5-1-u2-X22"}],"explanation":["경계를 떠올려요.","공기와 물이 만나요.","경계예요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#14','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C20',2,'mc','auto','하늘빛반 일지 ⑥의 다 사진기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X25','SC5-1-u2-X27']::text[],false,'{"seq":14,"concept":"SC5-1-u2-C20","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑥의 다 사진기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"볼록 렌즈와 오목 렌즈가 들어 있어 빛의 굴절을 이용한다","correct":true},{"t":"거울이 들어 있어 빛의 반사만 이용한다","mis":"SC5-1-u2-X26"},{"t":"렌즈가 들어 있지만 빛은 꺾이지 않는다","mis":"SC5-1-u2-X25"},{"t":"물체를 크게만 보여 주는 렌즈 하나뿐이다","mis":"SC5-1-u2-X27"}],"explanation":["사진기 속을 떠올려요.","두 렌즈가 있어요.","굴절이에요."],"asset":{"type":"passage","lines":["가 수술용 확대경 — 렌즈","나 신발 가게 거울 — 거울","다 사진기 — 렌즈","라 거울 예술 작품 — 거울","마 멀리 있는 것이 흐릴 때 쓰는 안경 — 렌즈"],"title":"하늘빛반 빛 탐구 일지 ⑥ 생활 속 거울과 렌즈 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#15','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C23',2,'ox','auto','간이 프로젝터는 볼록 렌즈가 빛을 굴절시키는 성질을 이용해요.',ARRAY['SC5-1-u2-X31']::text[],false,'{"seq":15,"concept":"SC5-1-u2-C23","difficulty":2,"kind":"ox","stem":"간이 프로젝터는 볼록 렌즈가 빛을 굴절시키는 성질을 이용해요.","answer":"O","reason_options":[{"t":"볼록 렌즈가 빛을 꺾어 화면을 크게 비추기 때문에","correct":true},{"t":"볼록 렌즈가 빛을 반사해 화면을 되비추기 때문에","mis":"SC5-1-u2-X31"}],"mis":"SC5-1-u2-X31","explanation":["렌즈를 썼어요.","렌즈는 꺾어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#16','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C22',2,'mc','auto','하늘빛반 일지 ⑦에서 3모둠이 고쳐야 할 점은 어느 것인가요?',ARRAY['SC5-1-u2-X30','SC5-1-u2-X32']::text[],false,'{"seq":16,"concept":"SC5-1-u2-C22","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑦에서 3모둠이 고쳐야 할 점은 어느 것인가요?","options":[{"t":"투명한 유리판 대신 거울로 벽을 만든다","correct":true},{"t":"유리판을 더 많이 붙인다","mis":"SC5-1-u2-X30"},{"t":"유리판에 렌즈를 붙여 빛을 꺾는다","mis":"SC5-1-u2-X30"},{"t":"고칠 것이 없다","mis":"SC5-1-u2-X32"}],"explanation":["거울 미로예요.","반사가 필요해요.","거울로 바꿔요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#17','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C18',3,'error','auto','하늘빛반 일지 ⑧에서 도하의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X26']::text[],false,'{"seq":17,"concept":"SC5-1-u2-C18","difficulty":3,"kind":"error","stem":"하늘빛반 일지 ⑧에서 도하의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"수민 — 「렌즈는 빛을 굴절시켜서 글씨를 크게 보여 줘.」","correct":true,"mis_target":"SC5-1-u2-X23"},{"t":"은후 — 「렌즈는 빛을 흡수해서 크게 보여 줘.」","mis":"SC5-1-u2-X26"},{"t":"지유 — 「렌즈는 거울처럼 빛을 되돌려 보내.」","mis":"SC5-1-u2-X23"}],"explanation":["렌즈가 하는 일이에요.","꺾어요.","수민이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#18','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C18',3,'ox','auto','세상의 모든 거울과 렌즈가 사라지면 낮에도 아무것도 보이지 않아요.',ARRAY['SC5-1-u2-X40']::text[],false,'{"seq":18,"concept":"SC5-1-u2-C18","difficulty":3,"kind":"ox","stem":"세상의 모든 거울과 렌즈가 사라지면 낮에도 아무것도 보이지 않아요.","answer":"X","reason_options":[{"t":"햇빛이 물체를 비추면 거울이나 렌즈가 없어도 물체를 볼 수 있기 때문에","correct":true},{"t":"거울과 렌즈가 빛을 만들어 내기 때문에","mis":"SC5-1-u2-X40"}],"mis":"SC5-1-u2-X40","explanation":["물체를 보려면 무엇이 필요할까요?","빛이에요.","보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#19','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C20',3,'mc','auto','세상의 모든 렌즈가 사라진다면 어떤 일이 생길까요?',ARRAY['SC5-1-u2-X26','SC5-1-u2-X40']::text[],false,'{"seq":19,"concept":"SC5-1-u2-C20","difficulty":3,"kind":"mc","stem":"세상의 모든 렌즈가 사라진다면 어떤 일이 생길까요?","options":[{"t":"사진기로 사진을 찍기 어려워진다","correct":true},{"t":"치과에서 입안을 보기 어려워진다","mis":"SC5-1-u2-X26"},{"t":"빛이 더 이상 곧게 나아가지 못한다","mis":"SC5-1-u2-X40"},{"t":"물체 뒤에 그림자가 생기지 않는다","mis":"SC5-1-u2-X40"}],"explanation":["렌즈가 하는 일이에요.","사진기 속에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#20','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C17',3,'mc','auto','그림에서 빛의 방향이 꺾인 곳은 어디인가요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X22']::text[],false,'{"seq":20,"concept":"SC5-1-u2-C17","difficulty":3,"kind":"mc","stem":"그림에서 빛의 방향이 꺾인 곳은 어디인가요?","options":[{"t":"공기와 물의 경계","correct":true},{"t":"레이저 지시기 바로 앞","mis":"SC5-1-u2-X25"},{"t":"물속 깊은 곳","mis":"SC5-1-u2-X22"},{"t":"빛은 꺾이지 않았다","mis":"SC5-1-u2-X22"}],"explanation":["빛줄기를 따라가요.","선이 꺾인 자리예요.","경계예요."],"asset":{"type":"geo","items":[{"w":300,"h":200,"seg":[[[10,100],[290,100]],[[60,25],[150,100]],[[150,100],[195,190]]],"lab":[[[88,12],"레이저 지시기"],[[40,82],"공기"],[[40,140],"물"],[[262,88],"경계"]],"cap":"공기에서 물로 비춘 빛"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#21','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C22',3,'mc','auto','거울 미로와 간이 프로젝터를 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u2-X31','SC5-1-u2-X30','SC5-1-u2-X32']::text[],false,'{"seq":21,"concept":"SC5-1-u2-C22","difficulty":3,"kind":"mc","stem":"거울 미로와 간이 프로젝터를 바르게 견준 것은 어느 것인가요?","options":[{"t":"거울 미로는 빛의 반사를, 간이 프로젝터는 빛의 굴절을 이용한다","correct":true},{"t":"거울 미로는 굴절을, 간이 프로젝터는 반사를 이용한다","mis":"SC5-1-u2-X31"},{"t":"두 장치 모두 빛의 굴절을 이용한다","mis":"SC5-1-u2-X30"},{"t":"두 장치 모두 빛과 관계없다","mis":"SC5-1-u2-X32"}],"explanation":["거울과 렌즈예요.","반사와 굴절이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#22','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C15',3,'mc','auto','렌즈에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X28','SC5-1-u2-X20']::text[],false,'{"seq":22,"concept":"SC5-1-u2-C15","difficulty":3,"kind":"mc","stem":"렌즈에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"투명한 유리나 플라스틱으로 빛이 통과할 때 방향이 변하도록 한 기구","correct":true},{"t":"빛을 되비추는 기구","mis":"SC5-1-u2-X23"},{"t":"스스로 빛을 만들어 내는 기구","mis":"SC5-1-u2-X28"},{"t":"빛이 통과하지 못하는 기구","mis":"SC5-1-u2-X20"}],"explanation":["렌즈의 뜻이에요.","빛이 통과해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#23','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C22',4,'mc','auto','1모둠의 피자가 한 판이 아니라 몇 조각만 보여요. 가장 먼저 해 볼 일은 어느 것인가요?',ARRAY['SC5-1-u2-X34','SC5-1-u2-X30']::text[],false,'{"seq":23,"concept":"SC5-1-u2-C22","difficulty":4,"kind":"mc","stem":"1모둠의 피자가 한 판이 아니라 몇 조각만 보여요. 가장 먼저 해 볼 일은 어느 것인가요?","options":[{"t":"두 거울 사이의 각도를 조금씩 바꾸어 본다","correct":true},{"t":"피자 조각을 더 크게 그린다","mis":"SC5-1-u2-X34"},{"t":"거울을 렌즈로 바꾸어 빛을 꺾는다","mis":"SC5-1-u2-X30"},{"t":"방을 더 밝게 한다","mis":"SC5-1-u2-X34"}],"explanation":["각도가 움직이게 붙였어요.","각도를 조절해요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#24','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C12',4,'essay','teacher','하늘빛반 일지 ④의 ①~③으로 알 수 있는 빛의 성질을 설명하고, ④에서 고쳐야 할 점과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u2-C12","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ④의 ①~③으로 알 수 있는 빛의 성질을 설명하고, ④에서 고쳐야 할 점과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 빛이 거울에 부딪치면 나아가는 방향이 바뀐다. 이것을 빛의 반사라고 한다. 거울의 방향을 바꾸면 빛이 닿는 곳도 달라지고, 거울을 치우면 빛은 곧게 나아간다. ④에서는 교실 불을 켜서 빛이 지나가는 길이 잘 보이지 않았으므로 교실을 어둡게 하고 실험해야 한다.","scoring_points":["반사를 바르게 설명했는가","거울 방향과 닿는 곳의 관계를 썼는가","교실을 어둡게 해야 한다고 썼는가"]},"explanation":["거울에 비춘 빛이에요.","방향이 바뀌어요.","고칠 점을 써요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_c#25','sci',5,1,'u2','','g5_1_sci_u2_review_c','unit_review','SC5-1-u2-C23',4,'essay','teacher','하늘빛반 일지 ⑦의 2모둠, 3모둠, 4모둠 설계를 어떻게 고치면 좋을지 각각 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u2-C23","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ⑦의 2모둠, 3모둠, 4모둠 설계를 어떻게 고치면 좋을지 각각 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 2모둠은 다른 빛이 들어오면 화면이 잘 보이지 않으므로 상자 뚜껑을 닫아야 한다. 3모둠은 투명한 유리판으로는 내 모습과 길이 거울처럼 비치지 않으므로 거울로 벽을 만들어 빛의 반사를 이용해야 한다. 4모둠은 장치를 크고 화려하게 만드는 것보다 거울이나 렌즈의 어떤 성질을 이용할지 먼저 정하고 그림과 글로 나타내야 한다.","scoring_points":["2모둠을 바르게 고쳤는가","3모둠을 반사와 이어 고쳤는가","4모둠에게 성질을 먼저 정하라고 썼는가"]},"explanation":["모둠마다 따져요.","빛의 성질을 떠올려요.","까닭을 함께 써요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#1','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',1,'mc','auto','하늘빛반 일지 ⑤에서 렌즈와 물로 관찰한 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X19']::text[],false,'{"seq":1,"concept":"SC5-1-u2-C18","difficulty":1,"kind":"mc","stem":"하늘빛반 일지 ⑤에서 렌즈와 물로 관찰한 빛의 성질은 어느 것인가요?","options":[{"t":"빛의 굴절","correct":true},{"t":"빛의 반사","mis":"SC5-1-u2-X23"},{"t":"빛의 그림자","mis":"SC5-1-u2-X19"},{"t":"빛의 소리","mis":"SC5-1-u2-X19"}],"explanation":["꺾였어요.","경계에서 꺾여요.","굴절이에요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#2','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',1,'sa','auto','「돋보기로 작은 글씨를 크게 보는 것은 빛의 □□을 이용한 것입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u2-C18","difficulty":1,"kind":"sa","stem":"「돋보기로 작은 글씨를 크게 보는 것은 빛의 □□을 이용한 것입니다.」 □□에 알맞은 말을 쓰세요.","answer":["굴절"],"explanation":["돋보기는 렌즈예요.","꺾여요.","굴절이에요."],"mis":"SC5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#3','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C19',1,'ox','auto','자동차 뒷거울은 빛의 반사를 이용해요.',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":3,"concept":"SC5-1-u2-C19","difficulty":1,"kind":"ox","stem":"자동차 뒷거울은 빛의 반사를 이용해요.","answer":"O","reason_options":[{"t":"거울이 빛을 반사해 뒤에 있는 자동차를 보여 주기 때문에","correct":true},{"t":"뒷거울이 빛을 꺾어 뒤차를 크게 보여 주기 때문에","mis":"SC5-1-u2-X26"}],"mis":"SC5-1-u2-X26","explanation":["뒷거울은 거울이에요.","거울은 되비춰요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#4','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C20',1,'mc','auto','작은 글씨를 크게 볼 때 쓰는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X26']::text[],false,'{"seq":4,"concept":"SC5-1-u2-C20","difficulty":1,"kind":"mc","stem":"작은 글씨를 크게 볼 때 쓰는 것은 어느 것인가요?","options":[{"t":"돋보기안경","correct":true},{"t":"치과 거울","mis":"SC5-1-u2-X26"},{"t":"자동차 뒷거울","mis":"SC5-1-u2-X26"},{"t":"전등 갓","mis":"SC5-1-u2-X26"}],"explanation":["크게 봐요.","렌즈예요.","돋보기안경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#5','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C22',1,'mc','auto','하늘빛반 일지 ⑦에서 1모둠의 피자 한 판 장치가 이용한 빛의 성질은 어느 것인가요?',ARRAY['SC5-1-u2-X30','SC5-1-u2-X16']::text[],false,'{"seq":5,"concept":"SC5-1-u2-C22","difficulty":1,"kind":"mc","stem":"하늘빛반 일지 ⑦에서 1모둠의 피자 한 판 장치가 이용한 빛의 성질은 어느 것인가요?","options":[{"t":"빛의 반사","correct":true},{"t":"빛의 굴절","mis":"SC5-1-u2-X30"},{"t":"빛을 흡수하는 성질","mis":"SC5-1-u2-X30"},{"t":"빛이 사라지는 성질","mis":"SC5-1-u2-X16"}],"explanation":["거울을 썼어요.","거울은 되비춰요.","반사예요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#6','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C25',1,'blank','auto','「라이파이는 빛이 통과하지 못하는 (    )이 있으면 통신이 끊길 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u2-X36','SC5-1-u2-X35','SC5-1-u2-X39']::text[],false,'{"seq":6,"concept":"SC5-1-u2-C25","difficulty":1,"kind":"blank","stem":"「라이파이는 빛이 통과하지 못하는 (    )이 있으면 통신이 끊길 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"장애물","correct":true},{"t":"LED 등","mis":"SC5-1-u2-X36"},{"t":"사람의 목소리","mis":"SC5-1-u2-X35"},{"t":"와이파이","mis":"SC5-1-u2-X39"}],"explanation":["빛을 막는 것이에요.","가로막아요.","장애물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#7','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C25',1,'match','auto','장소와 라이파이를 쓸 수 있는지를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-1-u2-C25","difficulty":1,"kind":"match","stem":"장소와 라이파이를 쓸 수 있는지를 알맞게 이으세요.","pairs":[{"l":"LED 등이 켜진 교실","r":"라이파이를 잘 쓸 수 있다"},{"l":"불이 꺼진 캄캄한 창고","r":"빛이 없어 쓰기 어렵다"},{"l":"두꺼운 벽 너머 옆방","r":"빛이 막혀 쓰기 어렵다"}],"mis":"SC5-1-u2-X36","explanation":["빛이 있나요?","빛이 닿나요?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#8','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C26',1,'mc','auto','라이파이 기술에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X38']::text[],false,'{"seq":8,"concept":"SC5-1-u2-C26","difficulty":1,"kind":"mc","stem":"라이파이 기술에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"세계 표준 방식이 정해져 많은 국가에서 연구하고 있다","correct":true},{"t":"이미 완성되어 아무도 연구하지 않는다","mis":"SC5-1-u2-X38"},{"t":"한 나라에서만 몰래 쓰는 기술이다","mis":"SC5-1-u2-X38"},{"t":"빛의 성질을 몰라도 만들 수 있다","mis":"SC5-1-u2-X38"}],"explanation":["세계 표준이 정해졌어요.","많은 나라가 연구해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#9','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C2',2,'mc','auto','하늘빛반이 숫자 4를 보내려면 어떤 신호를 보내야 하나요?',ARRAY['SC5-1-u2-X01','SC5-1-u2-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u2-C2","difficulty":2,"kind":"mc","stem":"하늘빛반이 숫자 4를 보내려면 어떤 신호를 보내야 하나요?","options":[{"t":"· · · · —","correct":true},{"t":"— — — — ·","mis":"SC5-1-u2-X01"},{"t":"· · · — —","mis":"SC5-1-u2-X02"},{"t":"— · · · ·","mis":"SC5-1-u2-X02"}],"explanation":["1부터 점이 늘어요.","4는 점 넷이에요.","점 넷에 선 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#10','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C7',2,'mc','auto','하늘빛반 일지 ②의 ④에서 커튼 틈 쪽 책만 보인 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C7","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ②의 ④에서 커튼 틈 쪽 책만 보인 까닭은 어느 것인가요?","options":[{"t":"커튼 틈으로 들어온 햇빛이 그쪽 책을 비추었기 때문에","correct":true},{"t":"그쪽 책이 스스로 빛을 냈기 때문에","mis":"SC5-1-u2-X07"},{"t":"그쪽 책이 더 컸기 때문에","mis":"SC5-1-u2-X09"},{"t":"그쪽이 더 따뜻했기 때문에","mis":"SC5-1-u2-X09"}],"explanation":["빛이 어디로 들어왔나요?","커튼 틈이에요.","햇빛이 비췄어요."],"asset":{"type":"passage","lines":["① 어둠상자 구멍을 손전등으로 빈틈없이 막고 관찰 — 잘 보이지 않음","② 손전등을 켜고 관찰 — 상자 속 인형이 잘 보임","③ 짝과 역할을 바꾸어 한 번 더 함","④ 낮, 커튼을 모두 치고 불을 끔 — 커튼 틈 쪽 책만 보임","⑤ 밤, 가로등 아래 자전거는 보이고 골목 안 자전거는 안 보임"],"title":"하늘빛반 빛 탐구 일지 ② 물체를 보려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#11','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C11',2,'mc','auto','하늘빛반 일지 ③의 ④에서 손전등 하나를 끄면 어떻게 될까요?',ARRAY['SC5-1-u2-X15','SC5-1-u2-X13']::text[],false,'{"seq":11,"concept":"SC5-1-u2-C11","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ③의 ④에서 손전등 하나를 끄면 어떻게 될까요?","options":[{"t":"그림자가 하나만 남는다","correct":true},{"t":"그림자 두 개가 그대로 있다","mis":"SC5-1-u2-X15"},{"t":"그림자가 셋으로 늘어난다","mis":"SC5-1-u2-X15"},{"t":"빛이 인형을 돌아가 그림자가 모두 사라진다","mis":"SC5-1-u2-X13"}],"explanation":["빛이 하나 줄었어요.","막히는 빛도 하나예요.","하나만 남아요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#12','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C13',2,'mc','auto','하늘빛반 일지 ④의 ④를 보고 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X18','SC5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ④의 ④를 보고 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"교실을 어둡게 하고 실험한다","correct":true},{"t":"레이저 지시기의 빛을 더 세게 한다","mis":"SC5-1-u2-X18"},{"t":"거울을 치우고 실험한다","mis":"SC5-1-u2-X17"},{"t":"교실 불을 더 밝게 켠다","mis":"SC5-1-u2-X18"}],"explanation":["빛의 길이 안 보였어요.","밝으면 잘 안 보여요.","어둡게 해요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#13','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',2,'mc','auto','하늘빛반 일지 ⑤에서 물이 든 통과 물을 뺀 통을 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X22']::text[],false,'{"seq":13,"concept":"SC5-1-u2-C18","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑤에서 물이 든 통과 물을 뺀 통을 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"빛은 서로 다른 물질의 경계를 지날 때 꺾인다","correct":true},{"t":"빛은 언제나 꺾여 나아간다","mis":"SC5-1-u2-X25"},{"t":"물을 빼도 빛은 꺾인다","mis":"SC5-1-u2-X25"},{"t":"빛은 물속에서 사라진다","mis":"SC5-1-u2-X22"}],"explanation":["물만 달라졌어요.","경계가 있고 없어요.","경계에서 꺾여요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#14','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C21',2,'mc','auto','하늘빛반이 일지 ⑥의 조사표를 만들 때 바른 태도는 어느 것인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":14,"concept":"SC5-1-u2-C21","difficulty":2,"kind":"mc","stem":"하늘빛반이 일지 ⑥의 조사표를 만들 때 바른 태도는 어느 것인가요?","options":[{"t":"신뢰할 수 있는 누리집에서 최신 자료를 찾고 출처를 밝힌다","correct":true},{"t":"찾은 그림을 허락 없이 그대로 쓴다","mis":"SC5-1-u2-X29"},{"t":"한 사람이 조사표를 혼자 다 만든다","mis":"SC5-1-u2-X29"},{"t":"한 칸에 예를 여러 개 섞어 쓴다","mis":"SC5-1-u2-X29"}],"explanation":["조사하는 태도예요.","믿을 수 있는 자료예요.","첫 번째예요."],"asset":{"type":"passage","lines":["가 수술용 확대경 — 렌즈","나 신발 가게 거울 — 거울","다 사진기 — 렌즈","라 거울 예술 작품 — 거울","마 멀리 있는 것이 흐릴 때 쓰는 안경 — 렌즈"],"title":"하늘빛반 빛 탐구 일지 ⑥ 생활 속 거울과 렌즈 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#15','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C24',2,'ox','auto','라이파이의 LED 등은 너무 빠르게 깜박여서 우리 눈에는 그냥 켜져 있는 것처럼 보여요.',ARRAY['SC5-1-u2-X35']::text[],false,'{"seq":15,"concept":"SC5-1-u2-C24","difficulty":2,"kind":"ox","stem":"라이파이의 LED 등은 너무 빠르게 깜박여서 우리 눈에는 그냥 켜져 있는 것처럼 보여요.","answer":"O","reason_options":[{"t":"깜박임이 아주 빨라 사람은 알아차리지 못하고 기기가 읽기 때문에","correct":true},{"t":"사람이 깜박임을 하나하나 세어 읽어야 하기 때문에","mis":"SC5-1-u2-X35"}],"mis":"SC5-1-u2-X35","explanation":["통신 과정 ②예요.","아주 빨라요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#16','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C23',2,'mc','auto','하늘빛반 일지 ⑦에서 4모둠이 가장 먼저 해야 할 일은 어느 것인가요?',ARRAY['SC5-1-u2-X32']::text[],false,'{"seq":16,"concept":"SC5-1-u2-C23","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑦에서 4모둠이 가장 먼저 해야 할 일은 어느 것인가요?","options":[{"t":"거울과 렌즈 가운데 무엇의 어떤 성질을 이용할지 정한다","correct":true},{"t":"가장 비싼 재료부터 산다","mis":"SC5-1-u2-X32"},{"t":"가장 크게 만들 자리를 찾는다","mis":"SC5-1-u2-X32"},{"t":"반짝이 장식부터 고른다","mis":"SC5-1-u2-X32"}],"explanation":["설계의 처음이에요.","성질이 먼저예요.","이용할 성질을 정해요."],"asset":{"type":"passage","lines":["1모둠 피자 한 판 — 거울 두 개를 셀로판테이프로 붙여 각도가 움직이게 함","2모둠 간이 프로젝터 — 볼록 렌즈를 끼운 상자, 뚜껑은 열어 둠","3모둠 거울 미로 — 거울이 모자라 투명한 유리판으로 벽을 만듦","4모둠 — 「무슨 성질을 쓸지는 나중에! 가장 크고 화려하게!」"],"title":"하늘빛반 빛 탐구 일지 ⑦ 장치 설계 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#17','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',3,'error','auto','하늘빛반 일지 ⑧에서 은결의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u2-X40','SC5-1-u2-X28']::text[],false,'{"seq":17,"concept":"SC5-1-u2-C18","difficulty":3,"kind":"error","stem":"하늘빛반 일지 ⑧에서 은결의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"태린 — 「거울과 렌즈가 없어도 빛은 곧게 나아가고, 빛이 있으면 물체도 보여.」","correct":true,"mis_target":"SC5-1-u2-X40"},{"t":"소윤 — 「거울과 렌즈가 사라지면 낮에도 아무것도 안 보여.」","mis":"SC5-1-u2-X40"},{"t":"현서 — 「거울이 빛을 만들어 주니까 빛도 사라져.」","mis":"SC5-1-u2-X28"}],"explanation":["빛 자체를 떠올려요.","거울과 렌즈는 빛을 바꿀 뿐이에요.","태린이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#18','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C12',3,'ox','auto','반사와 굴절은 모두 곧게 나아가던 빛이 무언가를 만나 나아가는 방향이 달라지는 현상이에요.',ARRAY['SC5-1-u2-X16']::text[],false,'{"seq":18,"concept":"SC5-1-u2-C12","difficulty":3,"kind":"ox","stem":"반사와 굴절은 모두 곧게 나아가던 빛이 무언가를 만나 나아가는 방향이 달라지는 현상이에요.","answer":"O","reason_options":[{"t":"반사는 거울에 부딪쳐, 굴절은 경계에서 방향이 달라지기 때문에","correct":true},{"t":"반사와 굴절은 모두 빛이 사라지는 현상이기 때문에","mis":"SC5-1-u2-X16"}],"mis":"SC5-1-u2-X16","explanation":["두 성질을 견줘요.","방향이 달라져요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#19','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C14',3,'mc','auto','밤에 가로등 빛이 방으로 들어오는 것을 빛의 반사를 이용해 막는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X19']::text[],false,'{"seq":19,"concept":"SC5-1-u2-C14","difficulty":3,"kind":"mc","stem":"밤에 가로등 빛이 방으로 들어오는 것을 빛의 반사를 이용해 막는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문 바깥쪽에 거울을 달아 빛을 다른 쪽으로 되비춘다","correct":true},{"t":"창문에 볼록 렌즈를 붙여 빛을 크게 만든다","mis":"SC5-1-u2-X23"},{"t":"가로등을 더 밝게 켜 둔다","mis":"SC5-1-u2-X19"},{"t":"창문을 활짝 열어 둔다","mis":"SC5-1-u2-X19"}],"explanation":["반사를 이용해요.","거울이 필요해요.","되비춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#20','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C13',3,'mc','auto','그림에서 레이저 지시기의 빛으로 모양판 다를 맞히려면 어떻게 하면 될까요?',ARRAY['SC5-1-u2-X17','SC5-1-u2-X18']::text[],false,'{"seq":20,"concept":"SC5-1-u2-C13","difficulty":3,"kind":"mc","stem":"그림에서 레이저 지시기의 빛으로 모양판 다를 맞히려면 어떻게 하면 될까요?","options":[{"t":"레이저 지시기는 그대로 두고 거울의 방향을 조금 바꾼다","correct":true},{"t":"거울을 치운다","mis":"SC5-1-u2-X17"},{"t":"레이저 지시기의 빛을 더 세게 한다","mis":"SC5-1-u2-X18"},{"t":"교실을 더 밝게 한다","mis":"SC5-1-u2-X18"}],"explanation":["지금은 나에 닿아요.","거울 방향이 열쇠예요.","조금 바꿔요."],"asset":{"type":"geo","items":[{"w":300,"h":205,"seg":[[[260,15],[260,185]],[[40,40],[260,100]],[[260,100],[40,160]]],"lab":[[[80,24],"레이저 지시기"],[[238,196],"평면거울"],[[22,100],"가"],[[22,160],"나"],[[22,190],"다"]],"cap":"평면거울로 모양판 맞히기"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#21','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C25',3,'mc','auto','라이파이의 좋은 점과 아쉬운 점을 바르게 나눈 것은 어느 것인가요?',ARRAY['SC5-1-u2-X39','SC5-1-u2-X36','SC5-1-u2-X37']::text[],false,'{"seq":21,"concept":"SC5-1-u2-C25","difficulty":3,"kind":"mc","stem":"라이파이의 좋은 점과 아쉬운 점을 바르게 나눈 것은 어느 것인가요?","options":[{"t":"좋은 점: 빛을 가리면 보안에 유리 — 아쉬운 점: 장애물이 있으면 끊김","correct":true},{"t":"좋은 점: 장애물이 있으면 끊김 — 아쉬운 점: 보안에 유리","mis":"SC5-1-u2-X39"},{"t":"좋은 점: 빛이 없어도 잘 됨 — 아쉬운 점: 없음","mis":"SC5-1-u2-X36"},{"t":"좋은 점: 빛이 벽을 뚫음 — 아쉬운 점: LED 등을 씀","mis":"SC5-1-u2-X37"}],"explanation":["좋은 점과 아쉬운 점이에요.","보안과 장애물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#22','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C21',3,'mc','auto','발표 자료에 다른 모둠이 그린 그림을 쓰고 싶어요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":22,"concept":"SC5-1-u2-C21","difficulty":3,"kind":"mc","stem":"발표 자료에 다른 모둠이 그린 그림을 쓰고 싶어요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"그린 친구에게 허락을 받고 누구의 그림인지 밝힌다","correct":true},{"t":"말없이 가져다 쓴다","mis":"SC5-1-u2-X29"},{"t":"조금 바꿔서 내가 그린 것처럼 쓴다","mis":"SC5-1-u2-X29"},{"t":"그림은 창작물이 아니니 마음대로 쓴다","mis":"SC5-1-u2-X29"}],"explanation":["다른 사람의 창작물이에요.","허락이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#23','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C25',4,'mc','auto','학교 도서관에 라이파이를 쓰려고 할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['SC5-1-u2-X37','SC5-1-u2-X36']::text[],false,'{"seq":23,"concept":"SC5-1-u2-C25","difficulty":4,"kind":"mc","stem":"학교 도서관에 라이파이를 쓰려고 할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"책상마다 LED 등의 빛이 닿는지 확인하고 빛을 가리는 높은 책장을 옮긴다","correct":true},{"t":"보안을 위해 LED 등을 모두 끈다","mis":"SC5-1-u2-X37"},{"t":"빛이 없어도 되니 지하 창고에 둔다","mis":"SC5-1-u2-X36"},{"t":"벽이 많을수록 빨라지니 칸막이를 세운다","mis":"SC5-1-u2-X36"}],"explanation":["빛이 닿아야 해요.","가리는 것을 줄여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#24','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',4,'essay','teacher','하늘빛반 일지 ⑤의 네 관찰을 이용하여 빛의 굴절을 설명하고, 볼록 렌즈와 오목 렌즈를 지난 빛이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u2-C18","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ⑤의 네 관찰을 이용하여 빛의 굴절을 설명하고, 볼록 렌즈와 오목 렌즈를 지난 빛이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 빛이 직진하다가 렌즈를 통과하거나 공기에서 물로 비스듬히 들어갈 때 나아가는 방향이 꺾인다. 물을 빼면 꺾이지 않으므로 빛은 서로 다른 물질의 경계에서 꺾인다는 것을 알 수 있다. 이것을 빛의 굴절이라고 한다. 볼록 렌즈를 지난 빛은 안쪽으로 꺾여 모이고, 오목 렌즈를 지난 빛은 바깥쪽으로 꺾여 퍼진다.","scoring_points":["굴절을 경계에서 꺾임으로 설명했는가","물을 뺀 통과 견주었는가","볼록·오목 렌즈의 차이를 썼는가"]},"explanation":["네 관찰을 견줘요.","경계가 열쇠예요.","두 렌즈를 견줘요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u2_review_d#25','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C26',4,'essay','teacher','「빛의 성질」 단원에서 배운 것을 「물체를 보려면 → 빛의 세 가지 성질 → 거울과 렌즈 → 빛으로 통신하는 기술」의 차례로 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u2-C26","difficulty":4,"kind":"essay","stem":"「빛의 성질」 단원에서 배운 것을 「물체를 보려면 → 빛의 세 가지 성질 → 거울과 렌즈 → 빛으로 통신하는 기술」의 차례로 정리해 쓰세요.","answer_guide":{"answer":"예: 물체를 보려면 물체를 비추는 빛이 있어야 한다. 빛은 곧게 나아가고(직진), 거울에 부딪치면 나아가는 방향이 바뀌며(반사), 서로 다른 물질의 경계에서 꺾여 나아간다(굴절). 거울은 반사를 이용해 치과 거울·자동차 뒷거울로, 렌즈는 굴절을 이용해 돋보기안경·사진기로 우리 생활을 편리하게 한다. 라이파이는 LED 등의 빛으로 통신하는 기술이며, 이런 기술을 연구하려면 빛의 성질을 알아야 한다.","scoring_points":["물체를 보려면 빛이 필요함을 썼는가","직진·반사·굴절을 바르게 썼는가","거울·렌즈의 쓰임과 라이파이를 썼는가"]},"explanation":["처음부터 떠올려요.","세 성질을 넣어요.","쓰임과 기술로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
